QT_ISI(23,{"3733":["(Dan tiadalah) Maa bermakna Nafi (Kami turunkan kepada kaumnya) kaum Habib An Najjar (setelah dia meninggal) sesudah Habib mati karena dirajam oleh mereka (suatu pasukan pun dari langit) yaitu malaikat-malaikat untuk membinasakan mereka (dan tidak layak Kami menurunkannya) menurunkan Malaikat untuk membinasakan seseorang.",[["۞ وَمَآ","And not"],["أَنزَلْنَا","We sent down"],["عَلَىٰ","upon"],["قَوْمِهِۦ","his people"],["مِنۢ","after him"],["بَعْدِهِۦ","after him"],["مِن","any"],["جُندٍۢ","host"],["مِّنَ","from"],["ٱلسَّمَآءِ","the heaven"],["وَمَا","and not"],["كُنَّا","were We"],["مُنزِلِينَ","(to) send down"]]],"3734":["(Tidak ada siksaan) yakni hukuman atas mereka (melainkan satu teriakan saja) malaikat Jibril berteriak keras kepada mereka (maka tiba-tiba mereka semuanya mati) tak bergerak lagi, mati semuanya.",[["إِن","Not"],["كَانَتْ","it was"],["إِلَّا","but"],["صَيْحَةًۭ","a shout"],["وَٰحِدَةًۭ","one"],["فَإِذَا","then behold"],["هُمْ","They"],["خَـٰمِدُونَ","(were) extinguished"]]],"3735":["(Alangkah besarnya penyesalan terhadap hamba-hamba itu) terhadap mereka dan orang-orang yang seperti mereka, yaitu orang-orang yang mendustakan rasul-rasul, karena akhirnya mereka dibinasakan. Yang dimaksud dengan penyesalan di sini adalah perasaan sakit yang amat sangat akibat suara malaikat Jibril. Kata Nida atau kata seru pada lafal Yaa hasratan hanyalah merupakan kata kiasan, maknanya sudah saatnya bagimu, maka menghadaplah kamu (tiada datang seorang rasul pun kepada mereka melainkan mereka selalu memperolok-olokkannya) ungkapan-ungkapan ini untuk menjelaskan penyebab dari penyesalan tadi. Di dalamnya terkandung pengertian ejekan mereka yang menyebabkan diri mereka binasa, setelah itu mereka menyesal karenanya.",[["يَـٰحَسْرَةً","Alas"],["عَلَى","for"],["ٱلْعِبَادِ ۚ","the servants"],["مَا","Not"],["يَأْتِيهِم","came to them"],["مِّن","any"],["رَّسُولٍ","Messenger"],["إِلَّا","but"],["كَانُوا۟","they did"],["بِهِۦ","mock at him"],["يَسْتَهْزِءُونَ","mock at him"]]],"3736":["(Tidakkah mereka mengetahui) yakni penduduk Mekah yang mengatakan kepada Nabi saw. sebagaimana yang disitir oleh firman-Nya, \"Kamu bukan seorang yang dijadikan rasul.\" (Q.S. Ar-Ra'd, 43.) Istifham atau kata tanya pada ayat ini mengandung makna Taqrir yakni ketahuilah oleh kalian (berapa banyak) lafal Kam mengandung makna kalimat berita, yakni banyak sekali; maknanya, sesungguhnya Kami (telah Kami binasakan sebelum mereka) amatlah banyak (umat-umat) bangsa-bangsa. (Bahwasanya mereka itu) orang-orang yang telah Kami binasakan (kepada mereka) yaitu orang-orang yang mendustakan Nabi saw. (tiada kembali) apakah mereka tidak mengambil pelajaran darinya. Lafal Annahum dan seterusnya berkedudukan menjadi Badal dari kalimat sebelumnya, dengan memelihara makna yang telah disebutkan.",[["أَلَمْ","Do not"],["يَرَوْا۟","they see"],["كَمْ","how many"],["أَهْلَكْنَا","We destroyed"],["قَبْلَهُم","before them"],["مِّنَ","of"],["ٱلْقُرُونِ","the generations"],["أَنَّهُمْ","That they"],["إِلَيْهِمْ","to them"],["لَا","will not return"],["يَرْجِعُونَ","will not return"]]],"3737":["(Dan tiadalah) bila dianggap sebagai In Nafiyah. Sesungguhnya, bila dianggap sebagai In Mukhaffafah dari Inna (masing-masing) dari semua makhluk, Kullun berkedudukan menjadi Mubtada (melainkan) apabila dibaca Tasydid artinya sama dengan lafal illa. Jika dibaca Takhfif yaitu menjadi Lamaa, maka huruf Lamnya adalah Lam Fariqah dan huruf Ma-nya adalah Zaidah (dikumpulkan) menjadi Khabar dari Mubtada, yakni dihimpunkan (kepada Kami kembali) untuk menjalani penghisaban; lafal ayat ini menjadi Khabar kedua",[["وَإِن","And surely"],["كُلٌّۭ","all"],["لَّمَّا","then"],["جَمِيعٌۭ","together"],["لَّدَيْنَا","before Us"],["مُحْضَرُونَ","(will be) brought"]]],"3738":["(Dan suatu tanda bagi mereka) yang menunjukkan bahwa mereka akan dibangkitkan kembali, lafal ayat ini berkedudukan menjadi Khabar Muqaddam (adalah bumi yang mati) dapat dibaca Al Maytati atau Al Mayyitati (Kami hidupkan bumi itu) dengan air, menjadi Mubtada Muakhkhar (dan Kami keluarkan daripadanya biji-bijian) seperti gandum (maka daripadanya mereka makan.)",[["وَءَايَةٌۭ","And a Sign"],["لَّهُمُ","for them"],["ٱلْأَرْضُ","(is) the earth"],["ٱلْمَيْتَةُ","dead"],["أَحْيَيْنَـٰهَا","We give it life"],["وَأَخْرَجْنَا","and We bring forth"],["مِنْهَا","from it"],["حَبًّۭا","grain"],["فَمِنْهُ","and from it"],["يَأْكُلُونَ","they eat"]]],"3739":["(Dan Kami jadikan padanya kebun-kebun) ladang-ladang (kurma dan anggur dan Kami pancarkan padanya beberapa mata air) dari sebagian kebun-kebun itu.",[["وَجَعَلْنَا","And We placed"],["فِيهَا","therein"],["جَنَّـٰتٍۢ","gardens"],["مِّن","of"],["نَّخِيلٍۢ","date-palms"],["وَأَعْنَـٰبٍۢ","and grapevines"],["وَفَجَّرْنَا","and We caused to gush forth"],["فِيهَا","in it"],["مِنَ","of"],["ٱلْعُيُونِ","the springs"]]],"3740":["(Supaya mereka dapat makan dari buahnya) dapat dibaca Tsamarihi atau Tsumurihi, yakni buah pohon yang telah disebutkan tadi, yaitu buah kurma dan buah-buah lainnya (dan dari apa yang diusahakan oleh tangan mereka) bukan dari hasil buah-buahan. (Maka mengapakah mereka tidak bersyukur?) atas nikmat-nikmat Allah yang telah dilimpahkan kepada mereka.",[["لِيَأْكُلُوا۟","That they may eat"],["مِن","of"],["ثَمَرِهِۦ","its fruit"],["وَمَا","And not"],["عَمِلَتْهُ","made it"],["أَيْدِيهِمْ ۖ","their hands"],["أَفَلَا","So will not"],["يَشْكُرُونَ","they be grateful"]]],"3741":["(Maha Suci Allah yang telah menciptakan pasangan-pasangan) yang berjenis-jenis (semuanya, baik dari apa yang ditumbuhkan oleh bumi) berupa biji-bijian dan lain-lainnya (dan dari diri mereka) yaitu jenis pria dan wanita (maupun dari apa yang tidak mereka ketahui) yaitu makhluk-makhluk yang ajaib dan aneh.",[["سُبْحَـٰنَ","Glory be"],["ٱلَّذِى","(to) the One Who"],["خَلَقَ","created"],["ٱلْأَزْوَٰجَ","(in) pairs"],["كُلَّهَا","all"],["مِمَّا","of what"],["تُنۢبِتُ","grows"],["ٱلْأَرْضُ","the earth"],["وَمِنْ","and of"],["أَنفُسِهِمْ","themselves"],["وَمِمَّا","and of what"],["لَا","not"],["يَعْلَمُونَ","they know"]]],"3742":["(Dan suatu tanda bagi mereka) yang menunjukkan kekuasaan Allah yang besar (adalah malam; Kami tanggalkan) Kami pisahkan (siang dari malam itu, maka dengan serta merta mereka berada dalam kegelapan) mereka memasuki kegelapan malam hari.",[["وَءَايَةٌۭ","And a Sign"],["لَّهُمُ","for them"],["ٱلَّيْلُ","(is) the night"],["نَسْلَخُ","We withdraw"],["مِنْهُ","from it"],["ٱلنَّهَارَ","the day"],["فَإِذَا","Then behold"],["هُم","They"],["مُّظْلِمُونَ","(are) those in darkness"]]],"3743":["(Dan matahari berjalan) ayat ini dan seterusnya merupakan bagian daripada ayat Wa-aayatul Lahum, atau merupakan ayat yang menyendiri, yakni tidak terikat oleh ayat sebelumnya demikian pula ayat Wal Qamara, pada ayat selanjutnya (di tempat peredarannya) tidak akan menyimpang dari garis edarnya. (Demikianlah) beredarnya matahari itu (ketetapan Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["وَٱلشَّمْسُ","And the sun"],["تَجْرِى","runs"],["لِمُسْتَقَرٍّۢ","to a term appointed"],["لَّهَا ۚ","for it"],["ذَٰلِكَ","That"],["تَقْدِيرُ","(is the) Decree"],["ٱلْعَزِيزِ","(of) the All-Mighty"],["ٱلْعَلِيمِ","the All-Knowing"]]],"3744":["(Dan bagi bulan) dapat dibaca Wal Qamaru atau Wal Qamara, bila dibaca nashab yaitu Wal Qamara berarti dinashabkan oleh Fiil sesudahnya yang berfungsi menafsirkannya yaitu (telah Kami tetapkan) bagi peredarannya (manzilah-manzilah) sebanyak dua puluh delapan manzilah selama dua puluh delapan malam untuk setiap bulannya. Kemudian bersembunyi selama dua malam, jika bilangan satu bulan tiga puluh hari, dan satu malam jika bilangan satu bulan dua puluh sembilan hari (sehingga kembalilah ia) setelah sampai ke manzilah yang terakhir, menurut pandangan mata (sebagai bentuk tandan yang tua) bila sudah lanjut masanya bagaikan ketandan, lalu menipis, berbentuk sabit dan berwarna kuning.",[["وَٱلْقَمَرَ","And the moon "],["قَدَّرْنَـٰهُ","We have ordained for it"],["مَنَازِلَ","phases"],["حَتَّىٰ","until"],["عَادَ","it returns"],["كَٱلْعُرْجُونِ","like the date stalk"],["ٱلْقَدِيمِ","the old"]]],"3745":["(Tidaklah mungkin bagi matahari) tidak akan terjadi (mendapatkan bulan) yaitu matahari dan bulan bersatu di malam hari (dan malam pun tidak dapat mendahului siang) malam hari tidak akan datang sebelum habis waktu siang hari. (Dan masing-masing) matahari, bulan dan bintang-bintang. Tanwin lafal Kullun ini merupakan pergantian dari Mudhaf Ilaih (pada garis edarnya) yang membundar (beredar) pada garis edarnya masing-masing. Di dalam ungkapan ini benda-benda langit diserupakan sebagai makhluk yang berakal, karenanya mereka diungkapkan dengan lafal Yasbahuuna.",[["لَا","Not"],["ٱلشَّمْسُ","the sun"],["يَنۢبَغِى","is permitted"],["لَهَآ","for it "],["أَن","that"],["تُدْرِكَ","it overtakes"],["ٱلْقَمَرَ","the moon"],["وَلَا","and not"],["ٱلَّيْلُ","the night"],["سَابِقُ","(can) outstrip"],["ٱلنَّهَارِ ۚ","the day"],["وَكُلٌّۭ","but all"],["فِى","in"],["فَلَكٍۢ","an orbit"],["يَسْبَحُونَ","they are floating"]]],"3746":["(Dan suatu tanda bagi mereka) yang menunjukkan kekuasaan Kami (adalah bahwa Kami angkut keturunan mereka) menurut qiraat yang lain lafal Dzurriyyatahum dibaca dalam bentuk jamak sehingga bacaannya menjadi Dzurriyyaatihim, maksudnya ialah kakek moyang mereka (dalam bahtera) yakni perahu Nabi Nuh (yang penuh muatan) dipadati penumpang.",[["وَءَايَةٌۭ","And a Sign"],["لَّهُمْ","for them"],["أَنَّا","(is) that"],["حَمَلْنَا","We carried"],["ذُرِّيَّتَهُمْ","their offspring"],["فِى","in"],["ٱلْفُلْكِ","the ship"],["ٱلْمَشْحُونِ","laden"]]],"3747":["(Dan Kami ciptakan untuk mereka seperti bahtera itu) seperti perahu Nabi Nuh, perahu kecil dan besar yang dibuat oleh mereka sesudahnya, bentuknya sama dengan perahu Nabi Nuh. Ini berkat apa yang telah Allah swt. ajarkan kepada Nabi Nuh (yang akan mereka kendarai) mereka berlayar dengannya.",[["وَخَلَقْنَا","And We created"],["لَهُم","for them"],["مِّن","from"],["مِّثْلِهِۦ","(the) likes of it"],["مَا","what"],["يَرْكَبُونَ","they ride"]]],"3748":["(Dan jika Kami menghendaki niscaya Kami tenggelamkan mereka) sekalipun memakai perahu (maka tiadalah penolong) yakni penyelamat (bagi mereka dan tidak -pula- mereka diselamatkan) ditolong sehingga selamat.",[["وَإِن","And if"],["نَّشَأْ","We will"],["نُغْرِقْهُمْ","We could drown them"],["فَلَا","then not"],["صَرِيخَ","(would be) a responder to a cry"],["لَهُمْ","for them"],["وَلَا","and not"],["هُمْ","they"],["يُنقَذُونَ","would be saved"]]],"3749":["(Tetapi -Kami selamatkan mereka- karena rahmat yang besar dari Kami dan untuk memberikan kesenangan hidup sampai kepada suatu ketika) tiada yang menyelamatkan mereka melainkan rahmat Kami kepada mereka; dan karena Kami hendak memberikan kesenangan hidup kepada mereka sampai batas ajal mereka.",[["إِلَّا","Except"],["رَحْمَةًۭ","(by) Mercy"],["مِّنَّا","from Us"],["وَمَتَـٰعًا","and provision"],["إِلَىٰ","for"],["حِينٍۢ","a time"]]],"3750":["(Dan apabila dikatakan kepada mereka, \"Takutlah kalian akan siksa yang di hadapan kalian) berupa azab di dunia sebagaimana apa yang telah menimpa orang-orang selain mereka (dan siksa yang akan datang) yaitu azab di akhirat (supaya kalian mendapat rahmat\") tetapi mereka tetap berpaling.",[["وَإِذَا","And when"],["قِيلَ","it is said"],["لَهُمُ","to them"],["ٱتَّقُوا۟","Fear"],["مَا","what"],["بَيْنَ","(is) before you"],["أَيْدِيكُمْ","(is) before you"],["وَمَا","and what"],["خَلْفَكُمْ","(is) behind you"],["لَعَلَّكُمْ","so that you may"],["تُرْحَمُونَ","receive mercy"]]],"3751":["(Dan sekali-kali tiada datang kepada mereka suatu tanda dari tanda-tanda kekuasaan Rabb mereka melainkan mereka selalu berpaling daripadanya.)",[["وَمَا","And not"],["تَأْتِيهِم","comes to them"],["مِّنْ","of"],["ءَايَةٍۢ","a Sign"],["مِّنْ","from"],["ءَايَـٰتِ","(the) Signs"],["رَبِّهِمْ","(of) their Lord"],["إِلَّا","but"],["كَانُوا۟","they"],["عَنْهَا","from it"],["مُعْرِضِينَ","turn away"]]],"3752":["(Dan apabila dikatakan) berkata sahabat-sahabat yang miskin (kepada mereka, \"Nafkahkanlah) sedekahkanlah kepada kami (sebagian dari rezeki yang diberikan Allah kepada kalian\") berupa harta benda (maka orang-orang yang kafir itu berkata kepada orang-orang yang beriman,) dengan nada yang sinis sebagai ejekan yang ditujukan kepada mereka, (\"Apakah kami akan memberi makanan kepada orang-orang yang jika Allah menghendaki tentulah Dia akan memberinya makan) sesuai dengan keyakinan kalian itu. (Tiada lain kalian) yaitu apa yang kalian katakan kepada kami, padahal kalian mempunyai keyakinan bahwa Allah pasti memberi makan kalian (melainkan dalam kesesatan yang nyata\") yakni jelas sesatnya. Ditegaskannya lafal Al Ladziina Kafaruu mengandung arti yang mendalam.",[["وَإِذَا","And when"],["قِيلَ","it is said"],["لَهُمْ","to them"],["أَنفِقُوا۟","Spend"],["مِمَّا","from what"],["رَزَقَكُمُ","(has) provided you"],["ٱللَّهُ","Allah"],["قَالَ","Said"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["لِلَّذِينَ","to those who"],["ءَامَنُوٓا۟","believed"],["أَنُطْعِمُ","Should we feed"],["مَن","whom"],["لَّوْ","if"],["يَشَآءُ","Allah willed "],["ٱللَّهُ","Allah willed "],["أَطْعَمَهُۥٓ","He would have fed him"],["إِنْ","Not"],["أَنتُمْ","(are) you"],["إِلَّا","except"],["فِى","in"],["ضَلَـٰلٍۢ","an error"],["مُّبِينٍۢ","clear"]]],"3753":["(Dan mereka berkata, \"Bilakah terjadinya janji ini?) yakni hari berbangkit (jika kalian orang-orang yang benar?\") mengenai apa yang kalian katakan.",[["وَيَقُولُونَ","And they say"],["مَتَىٰ","When (is)"],["هَـٰذَا","this"],["ٱلْوَعْدُ","promise"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"3754":["Allah berfirman, (\"Mereka tidak menunggu) menanti-nanti (melainkan satu teriakan saja), yaitu tiupan malaikat Israfil yang pertama (yang akan membinasakan mereka ketika mereka sedang bertengkar\") lafal Yakhishshimuuna pada asalnya adalah Yakhtashimuuna, kemudian harakat Ta dipindahkan kepada Kha, lalu Ta diidgamkan kepada Shad. Maksudnya, mereka dalam keadaan lalai dari kedatangan hari kiamat, disebabkan mereka sibuk dalam pertengkaran mereka, jual beli yang mereka lakukan, makan, dan minum serta kesibukan-kesibukan lainnya. Menurut qiraat yang lain lafal Yakhishshimuuna mempunyai Wazan sama dengan lafal Yadhribuuna, artinya sebagian dari mereka bertengkar dengan sebagian yang lain.",[["مَا","Not"],["يَنظُرُونَ","they await"],["إِلَّا","except"],["صَيْحَةًۭ","a shout"],["وَٰحِدَةًۭ","one"],["تَأْخُذُهُمْ","it will seize them"],["وَهُمْ","while they"],["يَخِصِّمُونَ","are disputing"]]],"3755":["(Lalu mereka tidak kuasa membuat suatu wasiat pun) tidak dapat berwasiat (dan tidak pula dapat kembali kepada keluarganya) dari pasar dan dari tempat-tempat kesibukan mereka, semuanya mati di tempatnya masing-masing.",[["فَلَا","Then not"],["يَسْتَطِيعُونَ","they will be able"],["تَوْصِيَةًۭ","(to) make a will"],["وَلَآ","and not"],["إِلَىٰٓ","to"],["أَهْلِهِمْ","their people"],["يَرْجِعُونَ","they (can) return"]]],"3756":["(Dan ditiuplah sangkakala) yaitu tiupan yang kedua untuk membangkitkan makhluk supaya hidup kembali; jarak antara dua tiupan, yakni tiupan pertama dengan tiupan kedua lamanya empat puluh tahun (maka tiba-tiba mereka) orang-orang yang telah terkubur itu (dari kuburnya) dari tempat mereka dikubur (Keluar dengan segera menuju kepada Rabb mereka) mereka keluar dengan cepat lalu menuju kepada-Nya.",[["وَنُفِخَ","And will be blown"],["فِى","[in]"],["ٱلصُّورِ","the trumpet"],["فَإِذَا","and behold"],["هُم","They"],["مِّنَ","from"],["ٱلْأَجْدَاثِ","the graves"],["إِلَىٰ","to"],["رَبِّهِمْ","their Lord"],["يَنسِلُونَ","[they] will hasten"]]],"3757":["(Mereka berkata) orang-orang kafir di antara manusia, (\"Aduhai!) Ya di sini menunjukkan makna Tanbih (celakalah kami) binasalah kami lafal Wailun adalah Mashdar yang tidak mempunyai Fi'il dari lafalnya. (Siapakah yang membangkitkan kami dari tempat tidur kami -kubur-?\") karena mereka seolah-olah dalam keadaan tidur di antara kedua tiupan itu, maksudnya mereka tidak diazab. (Inilah) kebangkitan ini (yang) telah (dijanjikan yang Maha Pemurah dan benarlah) mengenainya (Rasul-rasul-Nya) mereka mengakui atas kebenaran yang telah dikatakan oleh para rasul, tetapi pengakuan mereka tidak bermanfaat lagi. Menurut pendapat yang lain, bahwa kalimat tersebut dikatakan kepada mereka.",[["قَالُوا۟","They [will] say"],["يَـٰوَيْلَنَا","O woe to us"],["مَنۢ","Who"],["بَعَثَنَا","has raised us"],["مِن","from"],["مَّرْقَدِنَا ۜ ۗ","our sleeping place"],["هَـٰذَا","This (is)"],["مَا","What"],["وَعَدَ","(had) promised"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["وَصَدَقَ","and told (the) truth"],["ٱلْمُرْسَلُونَ","the Messengers"]]],"3758":["(Tiadalah teriakan itu selain sekali teriakan saja, tiba-tiba mereka semua kepada Kami) di hadapan Kami (dikumpulkan.)",[["إِن","Not"],["كَانَتْ","it will be"],["إِلَّا","but"],["صَيْحَةًۭ","a shout"],["وَٰحِدَةًۭ","single"],["فَإِذَا","so behold"],["هُمْ","They"],["جَمِيعٌۭ","all"],["لَّدَيْنَا","before Us"],["مُحْضَرُونَ","(will be) brought"]]],"3759":["(Pada hari itu seseorang tidak akan dirugikan sedikit pun dan kalian tidak dibalasi, kecuali) dengan balasan (apa yang telah kalian kerjakan.)",[["فَٱلْيَوْمَ","So this Day"],["لَا","not"],["تُظْلَمُ","will be wronged"],["نَفْسٌۭ","a soul"],["شَيْـًۭٔا","(in) anything"],["وَلَا","and not"],["تُجْزَوْنَ","you will be recompensed"],["إِلَّا","except"],["مَا","(for) what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"3760":["(Sesungguhnya penghuni surga pada hari itu dalam kesibukan) mereka tidak menghiraukan lagi apa yang dialami oleh ahli neraka, karena mereka sibuk dengan kenikmatan-kenikmatan yang sedang mereka rasakan, seperti memecahkan selaput dara bidadari-bidadari; mereka tidak mempunyai kesibukan yang membuat mereka lelah atau payah, karena di dalam surga tidak ada kelelahan. Lafal Syughulin dapat pula dibaca Syughlin (bersenang-senang) yakni bergelimangan di dalam kenikmatan. Lafal Faakihuuna menjadi Khabar kedua dari Inna, sedangkan Khabar yang pertama adalah Fii Syughulin.",[["إِنَّ","Indeed"],["أَصْحَـٰبَ","(the) companions"],["ٱلْجَنَّةِ","(of) Paradise"],["ٱلْيَوْمَ","this Day"],["فِى","[in]"],["شُغُلٍۢ","will be occupied"],["فَـٰكِهُونَ","(in) amusement"]]],"3761":["(Mereka) lafal Hum menjadi Mubtada (dan istri-istri mereka berada dalam tempat yang teduh) lafal Zhilaalun ini adalah bentuk jamak dari lafal Zhillun atau Zhillatun; menjadi Khabar Mubtada; arti Zhillun adalah tidak terkena panas matahari maksudnya teduh. (Di atas dipan-dipan) lafal Araa-iki adalah bentuk jamak dari lafal Ariikah, adalah ranjang atau permadani yang tebal (mereka bersandaran) bertelekan di atas dipan-dipan; lafal ayat ini menjadi Khabar kedua dan menjadi tempat berta'alluqnya Alal Araaa-iki.",[["هُمْ","They"],["وَأَزْوَٰجُهُمْ","and their spouses"],["فِى","in"],["ظِلَـٰلٍ","shades"],["عَلَى","on"],["ٱلْأَرَآئِكِ","[the] couches"],["مُتَّكِـُٔونَ","reclining"]]],"3762":["(Di surga itu mereka memperoleh buah-buahan dan mereka memperoleh pula) di dalamnya (apa yang mereka minta) apa yang mereka dambakan.",[["لَهُمْ","For them"],["فِيهَا","therein"],["فَـٰكِهَةٌۭ","(are) fruits"],["وَلَهُم","and for them"],["مَّا","(is) whatever"],["يَدَّعُونَ","they call for"]]],"3763":["(Kepada mereka dikatakan, \"Salaam\") kedudukan kalimat ini menjadi Mubtada (sebagai ucapan selamat) yang menjadi Khabarnya ialah (dari Rabb Yang Maha Penyayang) kepada mereka, yakni Dia mengucapkan kepada mereka, \"Kesejahteraan atas kalian.\"",[["سَلَـٰمٌۭ","Peace"],["قَوْلًۭا","A word"],["مِّن","from"],["رَّبٍّۢ","a Lord"],["رَّحِيمٍۢ","Most Merciful"]]],"3764":["(Dan) Dia berfirman pula, (\"Berpisahlah kalian dan orang-orang mukmin pada hari ini hai orang-orang yang berbuat jahat) mereka diperintahkan supaya berpisah di kala mereka bercampur dengan orang-orang mukmin.",[["وَٱمْتَـٰزُوا۟","But stand apart"],["ٱلْيَوْمَ","today"],["أَيُّهَا","O criminals"],["ٱلْمُجْرِمُونَ","O criminals"]]],"3765":["(Bukankah Aku telah memerintahkan kepada kalian hai Bani Adam) melalui lisan Rasul-rasul-Ku (supaya kalian tidak menyembah setan) jangan menaatinya. (Sesungguhnya setan itu adalah musuh yang nyata bagi kalian\") yakni jelas permusuhannya.",[["۞ أَلَمْ","Did not"],["أَعْهَدْ","I enjoin"],["إِلَيْكُمْ","upon you"],["يَـٰبَنِىٓ","O Children of Adam"],["ءَادَمَ","O Children of Adam"],["أَن","That"],["لَّا","(do) not"],["تَعْبُدُوا۟","worship"],["ٱلشَّيْطَـٰنَ ۖ","the Shaitaan"],["إِنَّهُۥ","indeed, he"],["لَكُمْ","(is) for you"],["عَدُوٌّۭ","an enemy"],["مُّبِينٌۭ","clear"]]],"3766":["(Dan hendaklah kalian menyembah-Ku) yakni esakanlah Aku dan taatilah Aku. (Inilah jalan) maksudnya tuntunan (yang lurus.)",[["وَأَنِ","And that"],["ٱعْبُدُونِى ۚ","you worship Me"],["هَـٰذَا","This"],["صِرَٰطٌۭ","(is) a Path"],["مُّسْتَقِيمٌۭ","Straight"]]],"3767":["(Sesungguhnya setan itu telah menyesatkan sebagian besar di antara kalian) lafal Jibillan adalah bentuk jamak dari Jabiilun seperti wazan Qadiimun, artinya makhluk. Menurut qiraat yang lain dibaca Jibullan dengan harakat Dhammah pada huruf Ba. (Maka apakah kalian tidak memikirkan?) tentang permusuhan setan dan penyesatannya; atau azab yang bakal menimpa mereka, yang karenanya mereka lalu mau beriman. Dikatakan kepada mereka di akhirat nanti:",[["وَلَقَدْ","And indeed"],["أَضَلَّ","he led astray"],["مِنكُمْ","from you"],["جِبِلًّۭا","a multitude"],["كَثِيرًا ۖ","great"],["أَفَلَمْ","Then did not"],["تَكُونُوا۟","you"],["تَعْقِلُونَ","use reason"]]],"3768":["(Inilah Jahanam yang kalian dahulu diancam) dengannya.",[["هَـٰذِهِۦ","This (is)"],["جَهَنَّمُ","(the) Hell"],["ٱلَّتِى","which"],["كُنتُمْ","you were"],["تُوعَدُونَ","promised"]]],"3769":["(Masuklah ke dalamnya pada hari ini disebabkan kalian dahulu mengingkarinya.)",[["ٱصْلَوْهَا","Burn therein"],["ٱلْيَوْمَ","today"],["بِمَا","because"],["كُنتُمْ","you used to"],["تَكْفُرُونَ","disbelieve"]]],"3770":["(Pada hari ini Kami tutup mulut mereka) mulut orang-orang kafir, karena mereka mengatakan, yaitu sebagaimana yang disitir oleh firman-Nya, \"Demi Allah, Rabb kami, tiadalah kami mempersekutukan Allah.\" (Q.S. 6 Al An'am, 23) (Dan berkatalah kepada Kami tangan mereka dan kaki mereka memberi kesaksian) juga anggota-anggota mereka lainnya (terhadap apa yang dahulu mereka kerjakan) setiap anggota tubuh mengucapkan apa yang telah diperbuatnya.",[["ٱلْيَوْمَ","This Day"],["نَخْتِمُ","We will seal"],["عَلَىٰٓ","[on]"],["أَفْوَٰهِهِمْ","their mouths"],["وَتُكَلِّمُنَآ","and will speak to Us"],["أَيْدِيهِمْ","their hands"],["وَتَشْهَدُ","and will bear witness"],["أَرْجُلُهُم","their feet"],["بِمَا","about what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"3771":["(Dan jika Kami menghendaki pastilah Kami hapuskan penglihatan mereka) Kami jadikan penglihatan mereka buta sama sekali (lalu mereka berlomba-lomba) bersegera (-mencari- jalan) untuk pergi sebagaimana kebiasaan mereka. (Maka betapakah) bagaimanakah (mereka dapat melihat) jalan itu, jika mereka dalam keadaan buta? Yakni mereka pasti tidak akan dapat melihat jalan itu.",[["وَلَوْ","And if"],["نَشَآءُ","We willed"],["لَطَمَسْنَا","We (would have) surely obliterated"],["عَلَىٰٓ","[over]"],["أَعْيُنِهِمْ","their eyes"],["فَٱسْتَبَقُوا۟","then they (would) race"],["ٱلصِّرَٰطَ","(to find) the path"],["فَأَنَّىٰ","then how"],["يُبْصِرُونَ","(could) they see"]]],"3772":["(Dan jika Kami menghendaki pastilah Kami ubah mereka) diubah menjadi kera, babi atau batu (di tempat mereka berada) menurut qiraat yang lain lafal Makanatihim dibaca dalam bentuk jamak, yaitu Makaanaatihim, yaitu di tempat-tempat mereka (maka mereka tidak sanggup berjalan dan tidak pula sanggup kembali) yakni mereka tidak dapat pergi dan tidak dapat pulang kembali.",[["وَلَوْ","And if"],["نَشَآءُ","We willed"],["لَمَسَخْنَـٰهُمْ","surely, We (would have) transformed them"],["عَلَىٰ","in"],["مَكَانَتِهِمْ","their places"],["فَمَا","then not"],["ٱسْتَطَـٰعُوا۟","they would have been able"],["مُضِيًّۭا","to proceed"],["وَلَا","and not"],["يَرْجِعُونَ","return"]]],"3773":["(Dan barang siapa yang Kami panjangkan umurnya) yaitu diperpanjang ajalnya (niscaya dia Kami kembalikan) menurut qiraat yang lain tidak dibaca Nunakkis-hu melainkan Nunkis-hu yang berasal dari Mashdar At-Tankiis, yakni mengembalikannya (kepada kejadiannya) sehingga setelah ia kuat dan muda lalu menjadi tua dan lemah kembali. (Maka apakah mereka tidak memikirkan?) bahwasanya Dzat Yang Maha Kuasa memperbuat demikian, berkuasa pula untuk membangkitkan hidup kembali, oleh karenanya mereka lalu mau beriman kepada-Nya. Menurut qiraat yang lain lafal Ya'qiluuna dibaca Ta'qiluuna dengan memakai huruf Ta.",[["وَمَن","And (he) whom"],["نُّعَمِّرْهُ","We grant him long life"],["نُنَكِّسْهُ","We reverse him"],["فِى","in"],["ٱلْخَلْقِ ۖ","the creation"],["أَفَلَا","Then will not"],["يَعْقِلُونَ","they use intellect"]]],"3774":["(Dan Kami tidak mengajarkan kepadanya) yakni kepada Nabi saw. (tentang syair) ayat ini diturunkan sebagai sanggahan terhadap perkataan orang-orang kafir, karena mereka telah mengatakan, bahwa sesungguhnya Alquran yang didatangkan olehnya adalah syair (dan bersyair itu tidak layak) tidak mudah (baginya.) (Alquran itu tiada lain) apa yang diturunkan kepadanya, tiada lain (hanyalah pelajaran) nasihat (dan Kitab yang memberi penerangan) yang menjelaskan tentang hukum-hukum dan lain-lainnya.",[["وَمَا","And not"],["عَلَّمْنَـٰهُ","We taught him"],["ٱلشِّعْرَ","[the] poetry"],["وَمَا","and not"],["يَنۢبَغِى","it is befitting"],["لَهُۥٓ ۚ","for him"],["إِنْ","Not"],["هُوَ","it"],["إِلَّا","(is) except"],["ذِكْرٌۭ","a Reminder"],["وَقُرْءَانٌۭ","and a Quran"],["مُّبِينٌۭ","clear"]]],"3775":["(Supaya dia memberi peringatan) dengan Alquran itu; lafal Liyundzira dapat pula dibaca Litundzira artinya supaya kamu memberi peringatan dengan Alquran itu (kepada orang-orang yang hidup) hatinya, maksudnya tanggap terhadap apa-apa yang dinasihatkan kepada mereka; mereka adalah orang-orang mukmin (dan supaya pastilah ketetapan) azab (terhadap orang-orang kafir) mereka diserupakan orang mati, karena mereka tidak tanggap terhadap apa-apa yang dinasihatkan kepada mereka.",[["لِّيُنذِرَ","To warn"],["مَن","(him) who"],["كَانَ","is"],["حَيًّۭا","alive"],["وَيَحِقَّ","and may be proved true"],["ٱلْقَوْلُ","the Word"],["عَلَى","against"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"3776":["(Dan apakah mereka tidak melihat) tidak memperhatikan, Istifham di sini mengandung makna Taqrir dan huruf Wau yang masuk kepadanya merupakan huruf 'Athaf (bahwa Kami telah menciptakan untuk mereka) ini ditujukan kepada segolongan manusia (dari apa yang telah Kami ciptakan dengan kekuasaan Kami) dari hasil ciptaan Kami tanpa sekutu dan tanpa pembantu (yaitu berupa binatang ternak) unta, sapi, dan kambing lalu mereka menguasainya?) dapat memeliharanya.",[["أَوَلَمْ","Do not"],["يَرَوْا۟","they see"],["أَنَّا","that We"],["خَلَقْنَا","[We] created"],["لَهُم","for them"],["مِّمَّا","from what"],["عَمِلَتْ","have made"],["أَيْدِينَآ","Our hands"],["أَنْعَـٰمًۭا","cattle"],["فَهُمْ","then they"],["لَهَا","[for them]"],["مَـٰلِكُونَ","(are the) owners"]]],"3777":["(Dan Kami tundukkan binatang-binatang itu) Kami jadikan mereka tunduk (untuk mereka; maka sebagiannya menjadi tunggangan mereka) menjadi kendaraan mereka (dan sebagiannya mereka makan.)",[["وَذَلَّلْنَـٰهَا","And We have tamed them"],["لَهُمْ","for them"],["فَمِنْهَا","so some of them "],["رَكُوبُهُمْ","they ride them"],["وَمِنْهَا","and some of them"],["يَأْكُلُونَ","they eat"]]],"3778":["(Dan mereka memperoleh padanya manfaat-manfaat) yakni dari bulu unta, kambing, dan dombanya (dan minuman) dari air susunya, lafal Masyaarib adalah bentuk jamak dari lafal Masyrab yang bermakna Asy-Syurb atau minuman, makna yang dimaksud adalah tempat minum. (Maka mengapakah mereka tidak bersyukur?) kepada Allah Yang telah melimpahkan nikmat-nikmat itu kepada mereka, lalu karenanya mereka mau beriman. Makna yang dimaksud ialah mereka tidak mensyukurinya.",[["وَلَهُمْ","And for them"],["فِيهَا","therein"],["مَنَـٰفِعُ","(are) benefits"],["وَمَشَارِبُ ۖ","and drinks"],["أَفَلَا","so (will) not"],["يَشْكُرُونَ","they give thanks"]]],"3779":["(Mereka mengambil selain Allah) selain-Nya (sebagai sesembahan-sesembahan) berhala-berhala yang mereka sembah (agar mereka mendapat pertolongan) terhindar dari azab Allah, karena mendapat syafaat dari tuhan-tuhan sesembahan mereka itu, ini menurut dugaan mereka sendiri.",[["وَٱتَّخَذُوا۟","But they have taken"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["ءَالِهَةًۭ","gods"],["لَّعَلَّهُمْ","that they may"],["يُنصَرُونَ","be helped"]]],"3780":["(Berhala-berhala itu tidak akan dapat) yakni sesembahan-sesembahan mereka itu tidak dapat menolong. Ungkapan kata berhala memakai jamak untuk orang yang berakal hanyalah sebagai kata kiasan saja, yakni mereka dianggap sebagai makhluk yang berakal (menolong mereka padahal berhala-berhala itu) sesembahan-sesembahan mereka itu (menjadi tentara mereka) menurut dugaan mereka, yaitu tentara yang siap menolong mereka (yang disiapkan) di dalam neraka bersama mereka.",[["لَا","Not"],["يَسْتَطِيعُونَ","they are able"],["نَصْرَهُمْ","to help them"],["وَهُمْ","but they "],["لَهُمْ","for them"],["جُندٌۭ","(are) hosts"],["مُّحْضَرُونَ","(who will) be brought"]]],"3781":["(Maka janganlah ucapan mereka menyedihkan kamu) seperti ucapan, bahwa kamu bukanlah seseorang yang diutus oleh Allah dan ucapan-ucapan lainnya. (Sesungguhnya Kami mengetahui apa yang mereka rahasiakan dan apa yang mereka nyatakan) dari perkataan-perkataan semacam itu dan yang lainnya, kelak Kami akan membalasnya kepada mereka.",[["فَلَا","So (let) not"],["يَحْزُنكَ","grieve you"],["قَوْلُهُمْ ۘ","their speech"],["إِنَّا","Indeed, We"],["نَعْلَمُ","[We] know"],["مَا","what"],["يُسِرُّونَ","they conceal"],["وَمَا","and what"],["يُعْلِنُونَ","they declare"]]],"3782":["(Apakah manusia tidak memperhatikan) apakah ia tidak mengetahui, orang yang dimaksud adalah Ashi bin Wail (bahwa Kami menciptakannya dari setitik air) yakni air mani, hingga Kami jadikan ia besar dan kuat (maka tiba-tiba ia menjadi penentang) yakni sangat memusuhi Kami (yang nyata) jelas menentangnya, tidak mau percaya kepada adanya hari berbangkit.",[["أَوَلَمْ","Does not"],["يَرَ","see"],["ٱلْإِنسَـٰنُ","[the] man"],["أَنَّا","that We"],["خَلَقْنَـٰهُ","[We] created him"],["مِن","from"],["نُّطْفَةٍۢ","a semen-drop"],["فَإِذَا","Then behold"],["هُوَ","He"],["خَصِيمٌۭ","(is) an opponent"],["مُّبِينٌۭ","clear"]]],"3783":["(Dia membuat perumpamaan bagi Kami) mengenai hal tersebut (dan dia lupa kepada kejadiannya) berasal dari air mani, dan terlebih lagi ia lupa kepada hal-hal yang selain itu (ia berkata, \"Siapakah yang dapat menghidupkan tulang-belulang yang telah hancur luluh?\") hancur berantakan, di dalam ungkapan ini tidak dikatakan Ramiimatun, karena isim bukan sifat. Menurut suatu riwayat dikisahkan bahwa Ashi bin Wail mengambil sebuah tulang yang telah hancur, kemudian ia cerai-beraikan tulang itu di hadapan Nabi saw. seraya berkata, \"Apakah kamu berpendapat, bahwa Allah nanti akan menghidupkan kembali tulang ini sesudah hancur luluh dan berantakan ini?\" Maka Nabi saw. menjawab, \"Ya, Dia akan memasukkanmu ke neraka.\"",[["وَضَرَبَ","And he sets forth"],["لَنَا","for Us"],["مَثَلًۭا","an example"],["وَنَسِىَ","and forgets"],["خَلْقَهُۥ ۖ","his (own) creation"],["قَالَ","He says"],["مَن","Who"],["يُحْىِ","will give life"],["ٱلْعِظَـٰمَ","(to) the bones"],["وَهِىَ","while they"],["رَمِيمٌۭ","(are) decomposed"]]],"3784":["(Katakanlah! \"Ia akan dihidupkan oleh Tuhan yang menciptakannya yang pertama kali. Dan Dia tentang segala makhluk) semua yang diciptakan-Nya (Maha Mengetahui) secara global dan rinci, baik sebelum mereka diciptakan maupun sesudahnya.",[["قُلْ","Say"],["يُحْيِيهَا","He will give them life"],["ٱلَّذِىٓ","Who"],["أَنشَأَهَآ","produced them"],["أَوَّلَ","(the) first"],["مَرَّةٍۢ ۖ","time"],["وَهُوَ","and He"],["بِكُلِّ","(is) of every"],["خَلْقٍ","creation"],["عَلِيمٌ","All-Knower"]]],"3785":["(Yaitu Tuhan yang menjadikan untuk kalian) yakni segolongan umat manusia (dari kayu yang hijau) yakni kayu pohon Marakh dan Affar atau semua jenis pohon selain pohon anggur (api, maka tiba-tiba kalian nyalakan -api- dari kayu itu.\") kalian membuat api daripadanya. Hal ini menunjukkan kekuasaan Allah swt. yang mampu untuk menghidupkan kembali manusia yang mati. Karena sesungguhnya di dalam kayu yang hijau itu terhimpun antara air, api, dan kayu; maka air tidak dapat memadamkan api, dan pula api tidak dapat membakar kayu.",[["ٱلَّذِى","The One Who"],["جَعَلَ","made"],["لَكُم","for you"],["مِّنَ","from"],["ٱلشَّجَرِ","the tree"],["ٱلْأَخْضَرِ","[the] green "],["نَارًۭا","fire"],["فَإِذَآ","and behold"],["أَنتُم","You"],["مِّنْهُ","from it"],["تُوقِدُونَ","ignite"]]],"3786":["(Dan tidakkah Tuhan yang menciptakan langit dan bumi itu) padahal langit dan bumi itu sangat besar (berkuasa menciptakan yang serupa dengan itu) yaitu manusia yang kecil bentuknya itu. (Benar) Dia berkuasa untuk menciptakannya, di sini Allah swt. menjawab diri-Nya sendiri. (Dan Dialah Maha Pencipta) banyak ciptaan-Nya (lagi Maha Mengetahui) segala sesuatu.",[["أَوَلَيْسَ","Is it not"],["ٱلَّذِى","(He) Who"],["خَلَقَ","created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["بِقَـٰدِرٍ","Able"],["عَلَىٰٓ","to"],["أَن","[that]"],["يَخْلُقَ","create"],["مِثْلَهُم ۚ","(the) like of them"],["بَلَىٰ","Yes, indeed"],["وَهُوَ","and He"],["ٱلْخَلَّـٰقُ","(is) the Supreme Creator"],["ٱلْعَلِيمُ","the All-Knower"]]],"3787":["(Sesungguhnya perkara-Nya) keadaan-Nya (apabila Dia menghendaki sesuatu) yakni berkehendak menciptakan sesuatu (hanyalah berkata kepadanya, \"Jadilah,\" maka terjadilah ia) berujudlah sesuatu itu. Menurut qiraat yang lain lafal Fayakuunu dibaca Fayakuna karena diathafkan kepada lafal Yaquula.",[["إِنَّمَآ","Only"],["أَمْرُهُۥٓ","His Command"],["إِذَآ","when"],["أَرَادَ","He intends"],["شَيْـًٔا","a thing"],["أَن","that"],["يَقُولَ","He says"],["لَهُۥ","to it"],["كُن","Be"],["فَيَكُونُ","and it is"]]],"3788":["(Maka Maha Suci Allah Yang dalam genggaman-Nya kekuasaan) lafal Malakuutu pada asalnya adalah Mulki kemudian ditambahkan huruf Wawu dan Ta untuk menunjukkan makna mubalaghah, artinya kekuasaan atas (segala sesuatu dan kepada-Nyalah kalian dikembalikan) kelak di akhirat.",[["فَسُبْحَـٰنَ","So glory be"],["ٱلَّذِى","(to) the One who"],["بِيَدِهِۦ","in Whose hand"],["مَلَكُوتُ","is (the) dominion"],["كُلِّ","(of) all"],["شَىْءٍۢ","things"],["وَإِلَيْهِ","and to Him"],["تُرْجَعُونَ","you will be returned"]]],"3789":["(Demi yang bersaf-saf dengan sebenar-benarnya) yaitu para malaikat yang berbaris membentuk saf-saf dalam menyembah Allah, atau para malaikat yang sayap-sayapnya bersaf-saf membentuk barisan di udara sambil menunggu apa yang diperintahkan kepada mereka.",[["وَٱلصَّـٰٓفَّـٰتِ","By those lined"],["صَفًّۭا","(in) rows"]]],"3790":["(Dan demi rombongan yang menggiring dengan sebenar-benarnya) demi para malaikat yang menggiring atau mengarak awan.",[["فَٱلزَّٰجِرَٰتِ","And those who drive"],["زَجْرًۭا","strongly"]]],"3791":["(Dan demi rombongan yang membacakan) maksudnya para pembaca Alquran yang sedang membacakannya sebagai (peringatan) lafal Dzikran menjadi Mashdar dari makna Fi'il At-Taaliyaat. Maksudnya, demi para qari yang membacakan peringatan atau Alquran.",[["فَٱلتَّـٰلِيَـٰتِ","And those who recite"],["ذِكْرًا","(the) Message"]]],"3792":["(Sesungguhnya Tuhan kalian) hai penduduk Mekah (benar-benar Esa.)",[["إِنَّ","Indeed"],["إِلَـٰهَكُمْ","your Lord"],["لَوَٰحِدٌۭ","(is) surely One"]]],"3793":["(Tuhan langit dan bumi dan apa yang berada di antara keduanya dan Tuhan tempat-tempat terbit matahari) dan tempat-tempat terbenamnya pada setiap harinya, yaitu arah Timur dan arah Barat.",[["رَّبُّ","Lord"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and what"],["بَيْنَهُمَا","(is) between both of them"],["وَرَبُّ","and Lord"],["ٱلْمَشَـٰرِقِ","(of) each point of sunrise"]]],"3794":["(Sesungguhnya Kami telah menghias langit yang terdekat dengan hiasan, yaitu bintang-bintang) dengan cahayanya, atau hiasan itu berupa bintang-bintang itu sendiri. Pengertian Idhafah di sini mengandung makna bayan atau menjelaskan, perihalnya sama dengan makna qiraat yang menanwinkannya.",[["إِنَّا","Indeed, We"],["زَيَّنَّا","[We] adorned"],["ٱلسَّمَآءَ","the sky"],["ٱلدُّنْيَا","[the world]"],["بِزِينَةٍ","with an adornment"],["ٱلْكَوَاكِبِ","(of) the stars"]]],"3795":["(Dan sebagai pemelihara) lafal Hifzhan dinashabkan oleh Fi'il yang diperkirakan keberadaannya pada sebelumnya, yakni Kami memelihara langit dengan bintang-bintang atau meteor-meteor (dari setiap) lafal ayat ini berta'alluq kepada Fi'il yang diperkirakan keberadaannya (setan yang durhaka) setan yang membangkang atau tidak mau taat.",[["وَحِفْظًۭا","And (to) guard"],["مِّن","against"],["كُلِّ","every"],["شَيْطَـٰنٍۢ","devil"],["مَّارِدٍۢ","rebellious"]]],"3796":["(Mereka tidak dapat mendengar-dengarkan) maksudnya setan-setan itu tidak dapat mendengar-dengarkan apa yang telah dipelihara oleh-Nya. Lafal ayat ini merupakan jumlah Isti'naf (pembicaraan para malaikat) yang berada di langit. Lafal Yasma'uuna dimuta'addikan dengan huruf Ilaa karena pengertiannya mengandung makna seperti apa yang terdapat di dalam lafal Al-Ishghaa. Menurut suatu qiraat dibaca La Yassamma'uuna dengan memakai Tasydid pada huruf Mim dan Sin-nya, berasal dari lafal Yatasamma'uuna, kemudian huruf Ta diidgamkan kepada huruf Sin, sehingga jadilah Yassamma'uuna (Dan mereka dilempari) yakni setan-setan itu dengan meteor-meteor (dari segala penjuru) langit.",[["لَّا","Not"],["يَسَّمَّعُونَ","they may listen"],["إِلَى","to"],["ٱلْمَلَإِ","the assembly"],["ٱلْأَعْلَىٰ","[the] exalted"],["وَيُقْذَفُونَ","are pelted"],["مِن","from"],["كُلِّ","every"],["جَانِبٍۢ","side"]]],"3797":["(Untuk mengusir mereka) lafal Duhuuran bentuk Mashdar dari lafal Daharahu, artinya dia mengusir mereka dan menjauhkan mereka, juga menjadi Maf'ul Lah (dan bagi mereka) di akhirat kelak (azab yang kekal) yang abadi.",[["دُحُورًۭا ۖ","Repelled"],["وَلَهُمْ","and for them"],["عَذَابٌۭ","(is) a punishment"],["وَاصِبٌ","perpetual"]]],"3798":["(Terkecuali setan yang mencuri-curi -pembicaraan malaikat- dengan sekali curi) lafal Al-Khathfah adalah Mashdar Marrah dan yang diistitsnakan atau yang dikecualikan adalah dhamir yang terkandung di dalam lafal Laa Yasma'uuna. Maksudnya, tiada yang dapat mendengarkan pembicaraan para malaikat kecuali hanya setan yang dapat mencuri-curinya dengan cepat (maka ia dikejar oleh meteor) yakni bintang yang bercahaya (yang melubanginya) yang menembus tubuh setan-setan itu, atau membakarnya, atau membuatnya cacat.",[["إِلَّا","Except"],["مَنْ","(him) who"],["خَطِفَ","snatches"],["ٱلْخَطْفَةَ","(by) theft"],["فَأَتْبَعَهُۥ","but follows him"],["شِهَابٌۭ","a burning flame"],["ثَاقِبٌۭ","piercing"]]],"3799":["(Maka tanyakanlah kepada mereka) kepada orang-orang kafir Mekah, kalimat ayat ini mengandung makna Taqrir atau Taubikh, yakni mengandung nada menetapkan atau celaan, (\"Apakah mereka yang lebih kukuh kejadiannya ataukah yang telah Kami ciptakan itu?\") yakni para malaikat, langit, bumi dan semua apa yang ada di antara keduanya. Didatangkannya lafal Man mengandung pengertian memprioritaskan makhluk yang berakal. (Sesungguhnya Kami telah menciptakan mereka) asal mereka, yaitu Nabi Adam (dan tanah liat) tanah yang melekat di tangan bilamana dipegang. Maksudnya, kejadian mereka adalah dari sesuatu yang lemah, karena itu janganlah mereka bersikap takabur dan sombong, yakni mengingkari Nabi saw. dan Alquran, yang hal ini dengan mudah dapat mengakibatkan mereka terjerumus ke dalam jurang kebinasaan.",[["فَٱسْتَفْتِهِمْ","Then ask them"],["أَهُمْ","Are they"],["أَشَدُّ","a stronger"],["خَلْقًا","creation"],["أَم","or"],["مَّنْ","(those) whom"],["خَلَقْنَآ ۚ","We have created"],["إِنَّا","Indeed, We"],["خَلَقْنَـٰهُم","created them"],["مِّن","from"],["طِينٍۢ","a clay"],["لَّازِبٍۭ","sticky"]]],"3800":["(Bahkan) lafal Bal di sini menunjukkan arti Intiqal, yakni perpindahan dari suatu topik pembicaraan kepada pembicaraan yang lain, yaitu pembahasan mengenai keadaan Nabi Muhammad dan orang-orang kafir Mekah (kamu heran) pembicaraan ayat ini ditujukan kepada Nabi saw. yakni kamu heran akan keingkaran mereka terhadapmu (dan) mereka (menghinakan kamu) karena keherananmu itu.",[["بَلْ","Nay"],["عَجِبْتَ","you wonder"],["وَيَسْخَرُونَ","while they mock"]]],"3801":["(Dan apabila mereka diberi pelajaran) maksudnya, dinasihati dengan ayat-ayat Alquran (mereka tiada mengingatinya) mereka tidak menjadikannya sebagai pelajaran.",[["وَإِذَا","And when"],["ذُكِّرُوا۟","they are reminded"],["لَا","not"],["يَذْكُرُونَ","they receive admonition"]]],"3802":["(Dan apabila mereka melihat sesuatu tanda kebesaran Allah) seperti terbelahnya bulan (mereka sangat menghinakan) mereka menghina dan mengejeknya.",[["وَإِذَا","And when"],["رَأَوْا۟","they see"],["ءَايَةًۭ","a Sign"],["يَسْتَسْخِرُونَ","they mock"]]],"3803":["(Dan mereka berkata) sehubungan dengan adanya tanda kebesaran Allah itu, (\"Tiada lain) tidak lain (ini hanyalah sihir yang nyata\") jelas sihirnya. Kemudian mereka berkata seraya mengingkari adanya hari berbangkit:",[["وَقَالُوٓا۟","And they say"],["إِنْ","Not"],["هَـٰذَآ","(is) this"],["إِلَّا","except"],["سِحْرٌۭ","a magic"],["مُّبِينٌ","clear"]]],"3804":["(Apakah apabila kami telah mati dan telah menjadi tanah serta menjadi tulang-belulang, apakah benar-benar kami akan dibangkitkan?) lafal A-idzaa dan A-innaa dapat pula dibaca Tas-hil, sehingga bacaannya menjadi Ayidzaa dan Ayinnaa.",[["أَءِذَا","Is it when"],["مِتْنَا","we are dead"],["وَكُنَّا","and have become"],["تُرَابًۭا","dust"],["وَعِظَـٰمًا","and bones"],["أَءِنَّا","shall we then"],["لَمَبْعُوثُونَ","be certainly resurrected"]]],"3805":["(Dan apakah bapak-bapak kami yang telah dahulu) kalau dibaca Au berarti huruf 'Athaf, jika dibaca Awa, berarti huruf Istifham, Wawu-nya adalah huruf 'Athaf, sedangkan Ma'thuf 'Alaihnya adalah Inna dan Isimnya secara Mahall, atau di'athafkan kepada Dhamir yang terkandung di dalam lafal Lamab'uutsuuna, Hamzah Istifham sebagai pemisahnya. Maksudnya, apakah bapak-bapak kami yang telah dahulu akan dibangkitkan pula?",[["أَوَءَابَآؤُنَا","Or our fathers"],["ٱلْأَوَّلُونَ","former"]]],"3806":["(Katakanlah kepada mereka, \"Ya) mereka pasti dibangkitkan hidup kembali (dan kalian akan terhina\") kalian akan menjadi orang-orang yang terhina karenanya.",[["قُلْ","Say"],["نَعَمْ","Yes"],["وَأَنتُمْ","and you"],["دَٰخِرُونَ","(will be) humiliated"]]],"3807":["(Maka sesungguhnya kebangkitan itu hanyalah dengan) dhamir pada ayat ini bersifat Mubham, kurang jelas, lalu ditafsirkan oleh ayat selanjutnya (suatu teriakan) atau satu hardikan saja (maka tiba-tiba mereka) yakni makhluk semuanya, menjadi hidup kembali seraya (melihat) apa yang dilakukan terhadap diri mereka.",[["فَإِنَّمَا","Then only"],["هِىَ","it"],["زَجْرَةٌۭ","(will be) a cry"],["وَٰحِدَةٌۭ","single"],["فَإِذَا","then, behold"],["هُمْ","They"],["يَنظُرُونَ","will see"]]],"3808":["(Dan mereka berkata) yakni orang-orang kafir, (\"Aduhai!) lafal Ya di sini menunjukkan makna Tanbih (celakalah kita\") binasalah kita. Lafal Al-Wail merupakan bentuk Mashdar yang tidak mempunyai kata kerja dari lafalnya sendiri. Kemudian para malaikat berkata kepada orang-orang kafir itu. (Inilah hari pembalasan) hari penghisaban amal perbuatan dan pembalasannya.",[["وَقَالُوا۟","And they will say"],["يَـٰوَيْلَنَا","O woe to us"],["هَـٰذَا","This"],["يَوْمُ","(is the) Day"],["ٱلدِّينِ","(of) the Recompense"]]],"3809":["(Inilah hari keputusan) di antara para makhluk semuanya (yang kalian selalu mendustakannya.)",[["هَـٰذَا","This"],["يَوْمُ","(is the) Day"],["ٱلْفَصْلِ","(of) Judgment"],["ٱلَّذِى","which"],["كُنتُم","you used to"],["بِهِۦ","[of it]"],["تُكَذِّبُونَ","deny"]]],"3810":["Kemudian diperintahkan kepada para malaikat itu, (\"Kumpulkanlah orang-rang yang zalim) yaitu orang-orang yang berbuat aniaya terhadap diri mereka sendiri karena mereka telah berbuat kemusyrikan (beserta teman sejawat mereka) teman-teman karib mereka, yaitu setan-setan (dan sesembahan-sesembahan yang selalu mereka sembah.)",[["۞ ٱحْشُرُوا۟","Gather"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","wronged"],["وَأَزْوَٰجَهُمْ","and their kinds"],["وَمَا","and what"],["كَانُوا۟","they used (to)"],["يَعْبُدُونَ","worship"]]],"3811":["(Selain Allah) yaitu berhala-berhala (maka tunjukkanlah kepada mereka) dan giringlah mereka (ke jalan jahim) atau jalan ke neraka.",[["مِن","Besides"],["دُونِ","Besides"],["ٱللَّهِ","Allah"],["فَٱهْدُوهُمْ","then lead them"],["إِلَىٰ","to"],["صِرَٰطِ","(the) Path"],["ٱلْجَحِيمِ","(of) the Hellfire"]]],"3812":["(Dan tahanlah mereka) di tempat perhentian atau Ash-Shirat (karena sesungguhnya mereka akan ditanya\") mengenai semua perkataan dan perbuatan mereka.",[["وَقِفُوهُمْ ۖ","And stop them"],["إِنَّهُم","indeed, they"],["مَّسْـُٔولُونَ","(are) to be questioned"]]],"3813":["Dikatakan kepada mereka dengan nada yang mengandung penghinaan dan cemoohan, (\"Kenapa kalian tidak tolong-menolong\") maksudnya mengapa sebagian di antara kalian tidak menolong kepada sebagian yang lain sebagaimana keadaan kalian waktu di dunia? Dan dikatakan pula kepada mereka:",[["مَا","What"],["لَكُمْ","(is) for you"],["لَا","(Why) not"],["تَنَاصَرُونَ","you help one another"]]],"3814":["(\"Bahkan mereka pada hari itu menyerah diri) atau mereka itu tunduk dalam keadaan penuh kehinaan.",[["بَلْ","Nay"],["هُمُ","they"],["ٱلْيَوْمَ","(on) that Day"],["مُسْتَسْلِمُونَ","(will) surrender"]]],"3815":["(Sebagian dari mereka menghadap kepada sebagian yang lain berbantah-bantahan\") saling cela-mencela dan saling bantah-membantah.",[["وَأَقْبَلَ","And will approach"],["بَعْضُهُمْ","some of them"],["عَلَىٰ","to"],["بَعْضٍۢ","others"],["يَتَسَآءَلُونَ","questioning one another"]]],"3816":["(Mereka berkata) yaitu sebagian dari pengikut-pengikut mereka berkata kepada para pemimpin mereka, (\"Sesungguhnya kalianlah yang datang kepada kami dari kanan\") maksudnya, dari segi yang kami merasa percaya kepada kalian karena kalian telah bersumpah kepada kami, bahwa kalian adalah orang-orang yang benar, karenanya kami percaya kepada kalian, dan kami mengikuti kalian. Maksudnya sesungguhnya kalian telah menyesatkan kami.",[["قَالُوٓا۟","They will say"],["إِنَّكُمْ","Indeed, you"],["كُنتُمْ","[you] used (to)"],["تَأْتُونَنَا","come (to) us"],["عَنِ","from"],["ٱلْيَمِينِ","the right"]]],"3817":["(Mereka berkata) yakni pemimpin-pemimpin yang diikuti oleh mereka (\"Sebenarnya kalianlah yang tidak beriman\") dan sesungguhnya tidak akan percaya penyesatan yang kami lakukan seandainya kalian adalah orang-orang yang beriman, niscaya kalian akan ingkar terhadap kami.",[["قَالُوا۟","They will say"],["بَل","Nay"],["لَّمْ","not"],["تَكُونُوا۟","you were"],["مُؤْمِنِينَ","believers"]]],"3818":["(Dan sekali-kali kami tidak berkuasa terhadap kalian) kami tidak mempunyai kemampuan untuk memaksa kalian mengikuti kami (bahkan kalianlah kaum yang melampaui batas) maksudnya, orang-orang yang sesat seperti kami.",[["وَمَا","And not"],["كَانَ","was"],["لَنَا","for us"],["عَلَيْكُم","over you"],["مِّن","any"],["سُلْطَـٰنٍۭ ۖ","authority"],["بَلْ","Nay"],["كُنتُمْ","you were"],["قَوْمًۭا","a people"],["طَـٰغِينَ","transgressing"]]],"3819":["(Maka pastilah) atau tetaplah (atas kita) semua (putusan Rabb kita) yakni azab-Nya, yaitu sebagaimana yang telah diungkapkan-Nya pada ayat yang lain, \"Sesungguhnya Aku akan penuhi neraka Jahanam dengan jin dan manusia bersama-sama.\" (Q.S. As-Sajdah, 13). (sesungguhnya kita) semua (akan merasakan) azab dengan adanya keputusan itu, yang akhirnya membuat mereka berkata:",[["فَحَقَّ","So has been proved true"],["عَلَيْنَا","against us"],["قَوْلُ","(the) Word"],["رَبِّنَآ ۖ","(of) our Lord"],["إِنَّا","indeed, we"],["لَذَآئِقُونَ","(will) certainly taste"]]],"3820":["(Maka kami telah menyesatkan kalian) sebagai penjelasan dari perkataan mereka yang disitir oleh firman-Nya (sesungguhnya kami adalah orang-orang yang sesat.)",[["فَأَغْوَيْنَـٰكُمْ","So we led you astray"],["إِنَّا","indeed, we"],["كُنَّا","were"],["غَـٰوِينَ","astray"]]],"3821":["Allah swt. berfirman, (Maka sesungguhnya mereka pada hari itu) pada hari kiamat (bersama-sama dalam azab) karena mereka bersekutu dalam kesesatan.",[["فَإِنَّهُمْ","Then indeed, they"],["يَوْمَئِذٍۢ","that Day"],["فِى","in"],["ٱلْعَذَابِ","the punishment"],["مُشْتَرِكُونَ","(will be) sharers"]]],"3822":["(Sesungguhnya demikianlah) artinya, sebagaimana Kami memperlakukan mereka (Kami berbuat terhadap orang-orang yang jahat) selain mereka. Yakni Kami pasti akan mengazab orang yang sesat beserta pengikut-pengikutnya.",[["إِنَّا","Indeed, We"],["كَذَٰلِكَ","thus"],["نَفْعَلُ","We deal"],["بِٱلْمُجْرِمِينَ","with the criminals"]]],"3823":["(Sesungguhnya mereka) yaitu orang-orang tersebut; dialamatkan kepada mereka karena berdasarkan penjelasan selanjutnya yaitu (dahulu apabila dikatakan kepada mereka, \"Laa Ilaaha Illallaah\") Tiada Tuhan melainkan Allah, (mereka menyombongkan diri.)",[["إِنَّهُمْ","Indeed, they"],["كَانُوٓا۟","were"],["إِذَا","when"],["قِيلَ","it was said"],["لَهُمْ","to them"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["ٱللَّهُ","Allah"],["يَسْتَكْبِرُونَ","were arrogant"]]],"3824":["(Dan mereka berkata, \"Apakah sesungguhnya kami) lafal A-innaa dapat pula dibaca Ayinnaa (harus meninggalkan sesembahan-sesembahan kami karena seorang penyair gila?\") yakni demi karena Muhammad.",[["وَيَقُولُونَ","And they say"],["أَئِنَّا","Are we"],["لَتَارِكُوٓا۟","to leave"],["ءَالِهَتِنَا","our gods"],["لِشَاعِرٍۢ","for a poet"],["مَّجْنُونٍۭ","mad"]]],"3825":["Allah swt. berfirman: (Sebenarnya dia Muhammad telah datang membawa kebenaran dan membenarkan rasul-rasul) yang juga datang membawa kebenaran, yaitu kalimat Laa Ilaaha Illallaah/tidak ada Tuhan selain Allah.",[["بَلْ","Nay"],["جَآءَ","he has brought"],["بِٱلْحَقِّ","the truth"],["وَصَدَّقَ","and confirmed"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"3826":["(Sesungguhnya kalian) di dalam ungkapan ini terkandung Iltifat karena seharusnya Innahum (pasti akan merasakan azab yang pedih.)",[["إِنَّكُمْ","Indeed, you"],["لَذَآئِقُوا۟","(will) surely taste"],["ٱلْعَذَابِ","the punishment"],["ٱلْأَلِيمِ","painful"]]],"3827":["(Dan kalian tidak diberi pembalasan melainkan) pembalasan (apa yang telah kalian kerjakan.)",[["وَمَا","And not"],["تُجْزَوْنَ","you will be recompensed"],["إِلَّا","except"],["مَا","what"],["كُنتُمْ","you used to"],["تَعْمَلُونَ","do"]]],"3828":["(Tetapi hamba-hamba Allah yang dibersihkan) yakni hamba-hamba Allah yang beriman, Istitsna di sini bersifat Munqathi', dan pembalasannya disebutkan pada firman selanjutnya, yaitu:",[["إِلَّا","Except"],["عِبَادَ","(the) slaves"],["ٱللَّهِ","(of) Allah"],["ٱلْمُخْلَصِينَ","the chosen ones"]]],"3829":["(Mereka itu memperoleh) di dalam surga (rezeki yang tertentu) setiap pagi dan sorenya.",[["أُو۟لَـٰٓئِكَ","Those"],["لَهُمْ","for them"],["رِزْقٌۭ","(will be) a provision"],["مَّعْلُومٌۭ","determined"]]],"3830":["(Yaitu buah-buahan) menjadi Badal atau 'Athaf Bayan dari lafal Rizqun; yaitu bermacam-macam rezeki yang dimakan hanya untuk dinikmati, bukan untuk memelihara kesehatan, karena penduduk surga tidak perlu lagi memelihara kesehatan sebab mereka telah diciptakan untuk hidup abadi dan sehat selama-lamanya. (Dan mereka adalah orang-orang yang dimuliakan) dengan pahala yang berlimpah dari Allah swt.",[["فَوَٰكِهُ ۖ","Fruits"],["وَهُم","and they"],["مُّكْرَمُونَ","(will) be honored"]]],"3831":["(Di dalam surga-surga yang penuh nikmat.)",[["فِى","In"],["جَنَّـٰتِ","Gardens"],["ٱلنَّعِيمِ","(of) Delight"]]],"3832":["(Di atas takhta-takhta kebesaran berhadap-hadapan) artinya, sebagian dari mereka duduk menghadap kepada sebagian yang lain, sehingga sebagian dari mereka tidak melihat tengkuk sebagian yang lainnya.",[["عَلَىٰ","On"],["سُرُرٍۢ","thrones"],["مُّتَقَـٰبِلِينَ","facing each other"]]],"3833":["(Diedarkan kepada mereka) maksudnya, kepada masing-masing di antara mereka diedarkan (gelas) yaitu tempat untuk minum berikut minumannya (yang berisikan khamar dari sungai khamar) yang mengalir bagaikan sungai di bumi.",[["يُطَافُ","Will be circulated"],["عَلَيْهِم","among them"],["بِكَأْسٍۢ","a cup"],["مِّن","from"],["مَّعِينٍۭ","a flowing spring"]]],"3834":["(Warnanya putih) lebih putih daripada air susu (sedap rasanya) sangat lezat rasanya (bagi orang-orang yang minum) berbeda dengan khamar di dunia yang apabila diminum rasanya tidak enak.",[["بَيْضَآءَ","White"],["لَذَّةٍۢ","delicious"],["لِّلشَّـٰرِبِينَ","for the drinkers"]]],"3835":["(Tidak ada di dalam khamar itu alkohol) yakni zat yang membuat akal mereka mabuk (dan mereka tiada mabuk karenanya) dapat dibaca Yunzafuuna atau yanzifuuna, yang berasal dari kalimat, Nazafasy Syaaribu, dan Anzafa, artinya memabukkan; maksudnya khamar surga itu tidak memabukkan berbeda halnya dengan khamar di dunia.",[["لَا","Not"],["فِيهَا","in it"],["غَوْلٌۭ","(is) bad effect"],["وَلَا","and not"],["هُمْ","they"],["عَنْهَا","from it"],["يُنزَفُونَ","will be intoxicated"]]],"3836":["(Di sisi mereka ada bidadari-bidadari yang tidak liar pandangannya) yaitu bidadari-bidadari yang selalu menundukkan pandangan matanya, atau dengan kata lain mereka hanya memandang suami-suami mereka saja dan tidak memandang orang lain, karena menurut mereka suami-suami mereka adalah orang-orang yang paling cakap (dan jelita matanya) artinya mata bidadari-bidadari itu sangat jelita.",[["وَعِندَهُمْ","And with them"],["قَـٰصِرَٰتُ","(will be) companions of modest gaze"],["ٱلطَّرْفِ","(will be) companions of modest gaze"],["عِينٌۭ","(having) beautiful eyes"]]],"3837":["(Seakan-akan mereka) yakni warna kulit mereka (adalah telur) burung unta (yang tersimpan dengan baik) bagaikan telur burung unta yang terlindungi oleh bulu induknya, sehingga tidak ada suatu debu pun yang menempel padanya, demikian pula warnanya, putih kekuning-kuningan, warna kulit seperti itu adalah warna kulit wanita yang paling cantik.",[["كَأَنَّهُنَّ","As if they were"],["بَيْضٌۭ","eggs"],["مَّكْنُونٌۭ","well protected"]]],"3838":["(Lalu sebagian mereka menghadap) yakni sebagian penduduk surga (kepada sebagian yang lain sambil bercakap-cakap) mengenai apa yang telah mereka lakukan di dunia.",[["فَأَقْبَلَ","And (will) approach"],["بَعْضُهُمْ","some of them"],["عَلَىٰ","to"],["بَعْضٍۢ","others"],["يَتَسَآءَلُونَ","questioning one another"]]],"3839":["(Berkatalah salah seorang di antara mereka, \"Sesungguhnya aku dahulu di dunia mempunyai seorang teman) yakni teman yang ingkar kepada adanya hari berbangkit.",[["قَالَ","Will say"],["قَآئِلٌۭ","a speaker"],["مِّنْهُمْ","among them"],["إِنِّى","Indeed, I"],["كَانَ","had"],["لِى","for me"],["قَرِينٌۭ","a companion"]]],"3840":["(Yang berkata,) kepadaku dengan nada yang mengejek, ('Apakah kamu sungguh-sungguh termasuk orang-orang yang membenarkan) adanya hari berbangkit?",[["يَقُولُ","Who (would) say"],["أَءِنَّكَ","Are you indeed"],["لَمِنَ","surely of"],["ٱلْمُصَدِّقِينَ","those who believe"]]],"3841":["(Apakah apabila kita telah mati dan kita telah menjadi tanah dan tulang-belulang, apakah sesungguhnya kita) kedua huruf Hamzah pada ketiga tempat yang disebutkan di atas, yaitu A-innaka, A-idzaa dan A-innaa boleh dibaca Tahqiq dan boleh pula dibaca Tas-hil (benar-benar akan dibangkitkan untuk diberi pembalasan?') maksudnya akan dibalas dan dihisab? Ia ternyata ingkar kepada hal tersebut.",[["أَءِذَا","Is (it) when"],["مِتْنَا","we have died"],["وَكُنَّا","and become"],["تُرَابًۭا","dust"],["وَعِظَـٰمًا","and bones"],["أَءِنَّا","will we"],["لَمَدِينُونَ","surely be brought to Judgment"]]],"3842":["(Berkata pulalah ia) yaitu penghuni surga yang mengatakan demikian kepada temannya ('Maukah kamu melihat keadaan temanku itu?'\") maksudnya bersama-sama untuk melihat apa yang dialami temannya di dalam neraka? Temannya menjawab, \"Tidak mau.\"",[["قَالَ","He (will) say"],["هَلْ","Will"],["أَنتُم","you"],["مُّطَّلِعُونَ","be looking"]]],"3843":["(Maka ia meninjaunya) yakni orang yang mengatakan demikian itu dari sebagian jendela surga (lalu ia melihat temannya itu) yaitu temannya yang ingkar kepada adanya hari berbangkit itu (di tengah-tengah neraka menyala-nyala) berada di tengah-tengah neraka Jahim.",[["فَٱطَّلَعَ","Then he (will) look"],["فَرَءَاهُ","and see him"],["فِى","in"],["سَوَآءِ","(the) midst"],["ٱلْجَحِيمِ","(of) the Hellfire"]]],"3844":["(Ia berkata pula) dengan nada mengejek, (\"Demi Allah, sesungguhnya) lafal In di sini adalah bentuk Takhfif dari Inna (kamu benar-benar hampir) kamu hampir saja (mencelakakanku) membinasakan aku melalui penyesatanmu itu.",[["قَالَ","He (will) say"],["تَٱللَّهِ","By Allah"],["إِن","verily"],["كِدتَّ","you almost"],["لَتُرْدِينِ","ruined me"]]],"3845":["(Jika tidak karena nikmat Rabbku) atas diriku yaitu berupa iman (pastilah aku termasuk orang-orang yang diseret) bersamamu ke dalam neraka. Dan penduduk surga berkata,",[["وَلَوْلَا","And if not"],["نِعْمَةُ","(for the) Grace"],["رَبِّى","(of) my Lord"],["لَكُنتُ","certainly, I (would) have been"],["مِنَ","among"],["ٱلْمُحْضَرِينَ","those brought"]]],"3846":["(Maka apakah kita tidak akan mati.)",[["أَفَمَا","Then are not"],["نَحْنُ","we"],["بِمَيِّتِينَ","(to) die"]]],"3847":["(Melainkan hanya kematian kita yang pertama) yakni kematian kita di dunia (dan kita tidak akan disiksa di akhirat ini?\") Istifham atau kata tanya di sini mengandung makna menetapkan kenikmatan yang mereka rasakan dan sebagai ungkapan rasa syukur mereka atas nikmat yang telah dilimpahkan Allah kepada diri mereka, yaitu mereka dijadikan hidup abadi dengan penuh kenikmatan dan tidak disiksa untuk selama-lamanya.",[["إِلَّا","Except"],["مَوْتَتَنَا","our death"],["ٱلْأُولَىٰ","the first"],["وَمَا","and not"],["نَحْنُ","we"],["بِمُعَذَّبِينَ","will be punished"]]],"3848":["(Sesungguhnya ini) yakni apa yang Aku jelaskan mengenai keadaan penduduk surga (benar-benar kemenangan yang besar.)",[["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَهُوَ","surely"],["ٱلْفَوْزُ","(is) the attainment"],["ٱلْعَظِيمُ","great"]]],"3849":["(Untuk kemenangan serupa ini hendaklah berusaha orang-orang yang beramal) menurut suatu pendapat, bahwa perkataan ini ditujukan kepada mereka. Dan menurut pendapat yang lain disebutkan, bahwa merekalah yang mengatakan demikian.",[["لِمِثْلِ","For (the) like"],["هَـٰذَا","(of) this"],["فَلْيَعْمَلِ","let work"],["ٱلْعَـٰمِلُونَ","the workers"]]],"3850":["(Apakah yang demikian itu) hal-hal yang telah disebutkan bagi ahli surga itu (merupakan hidangan yang lebih baik) suguhan atau hidangan yang diperuntukkan menjamu tamu atau orang yang menginap (ataukah pohon zaqqum) yang disediakan buat ahli neraka; pohon zaqqum adalah pohon yang paling buruk dan sangat pahit rasanya, tempat asalnya adalah Tihamah. Allah menumbuhkan pohon itu di dalam neraka Jahim, sebagaimana yang akan diterangkan nanti.",[["أَذَٰلِكَ","Is that"],["خَيْرٌۭ","better"],["نُّزُلًا","(as) hospitality"],["أَمْ","or"],["شَجَرَةُ","(the) tree"],["ٱلزَّقُّومِ","(of) Zaqqum"]]],"3851":["(Sesungguhnya Kami menjadikan pohon zaqqum itu) artinya ditumbuhkannya pohon tersebut di dalam neraka (sebagai fitnah bagi orang-orang yang lalim) yakni orang-orang kafir Mekah, karena mereka telah mengatakan, bahwa api itu membakar pohon, mana mungkin di dalam neraka dapat ditumbuhkan pohon.",[["إِنَّا","Indeed, We"],["جَعَلْنَـٰهَا","[We] have made it"],["فِتْنَةًۭ","a trial"],["لِّلظَّـٰلِمِينَ","for the wrongdoers"]]],"3852":["(Sesungguhnya dia adalah sebatang pohon yang keluar dari dasar neraka yang menyala) yakni dari dasar neraka Jahanam, dan ranting-rantingnya mencuat sampai ke relung-relungnya.",[["إِنَّهَا","Indeed, it"],["شَجَرَةٌۭ","(is) a tree"],["تَخْرُجُ","that grows"],["فِىٓ","in"],["أَصْلِ","(the) bottom"],["ٱلْجَحِيمِ","(of) the Hellfire"]]],"3853":["(Mayangnya) diserupakan dengan mayang pohon kurma (seperti kepala setan-setan) maksudnya, seperti ular-ular yang sangat buruk dan menjijikkan tampangnya.",[["طَلْعُهَا","Its emerging fruit"],["كَأَنَّهُۥ","(is) as if it"],["رُءُوسُ","(was) heads"],["ٱلشَّيَـٰطِينِ","(of) the devils"]]],"3854":["(Maka sesungguhnya mereka) yakni orang-orang kafir (benar-benar memakan sebagian dari pohon itu) sekalipun rasanya sangat memuakkan, karena mereka dalam keadaan sangat lapar (maka mereka memenuhi perutnya dengan buah zaqqum itu.)",[["فَإِنَّهُمْ","And indeed, they"],["لَـَٔاكِلُونَ","(will) surely eat"],["مِنْهَا","from it"],["فَمَالِـُٔونَ","and fill"],["مِنْهَا","with it"],["ٱلْبُطُونَ","(their) bellies"]]],"3855":["(Kemudian sesudah makan buah pohon zaqqum itu pasti mereka mendapat minuman yang bercampur dengan air yang sangat panas) yang mereka minum, hingga bercampur di dalam perut mereka apa yang mereka makan dan apa yang mereka minum itu.",[["ثُمَّ","Then"],["إِنَّ","indeed"],["لَهُمْ","for them"],["عَلَيْهَا","in it"],["لَشَوْبًۭا","(is) a mixture"],["مِّنْ","of"],["حَمِيمٍۢ","boiling water"]]],"3856":["(Kemudian sesungguhnya tempat kembali mereka benar-benar ke neraka Jahim) ayat ini memberikan pengertian, bahwa mereka keluar dahulu dari dalam neraka untuk meminum air hamim atau air yang sangat panas itu, dan bahwasanya air yang sangat panas itu adanya di luar neraka.",[["ثُمَّ","Then"],["إِنَّ","indeed"],["مَرْجِعَهُمْ","their return"],["لَإِلَى","(will) surely be to"],["ٱلْجَحِيمِ","the Hellfire"]]],"3857":["(Karena sesungguhnya mereka mendapati) menemukan (bapak-bapak mereka dalam keadaan sesat.)",[["إِنَّهُمْ","Indeed, they"],["أَلْفَوْا۟","found"],["ءَابَآءَهُمْ","their fathers"],["ضَآلِّينَ","astray"]]],"3858":["(Lalu mereka sangat tergesa-gesa mengikuti jejak orang-orang tua mereka itu) atau terburu-buru mengikutinya, oleh karenanya mereka tergesa-gesa mengikuti kesesatan bapak-bapak mereka, tanpa berpikir lebih jauh lagi.",[["فَهُمْ","So they"],["عَلَىٰٓ","on"],["ءَاثَـٰرِهِمْ","their footsteps"],["يُهْرَعُونَ","they hastened"]]],"3859":["(Dan sesungguhnya telah sesat sebelum mereka sebagian besar dari orang-orang yang dahulu) umat-umat yang terdahulu.",[["وَلَقَدْ","And verily"],["ضَلَّ","went astray"],["قَبْلَهُمْ","before them"],["أَكْثَرُ","most"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"3860":["(Dan sesungguhnya telah Kami utus pemberi-pemberi peringatan di kalangan mereka) yakni rasul-rasul yang memberi peringatan kepada mereka.",[["وَلَقَدْ","And verily"],["أَرْسَلْنَا","We sent"],["فِيهِم","among them"],["مُّنذِرِينَ","warners"]]],"3861":["(Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu) yakni orang-orang kafir itu, kesudahan mereka mendapat azab.",[["فَٱنظُرْ","Then see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلْمُنذَرِينَ","(of) those who were warned"]]],"3862":["(Kecuali hamba-hamba Allah yang dibersihkan -dari dosa-dosa-) yakni kaum mukminin, sesungguhnya mereka selamat dari azab, karena keikhlasan mereka dalam beribadah kepada Allah. Atau karena Allah telah membersihkan mereka dari dosa-dosanya, makna ini berdasar qiraat yang membacanya Mukhlashiina.",[["إِلَّا","Except"],["عِبَادَ","(the) slaves"],["ٱللَّهِ","(of) Allah"],["ٱلْمُخْلَصِينَ","the chosen ones"]]],"3863":["(Sesungguhnya Nuh telah menyeru Kami) melalui doanya, sebagaimana yang disitir oleh ayat lain, yaitu firman-Nya, \"Sesungguhnya aku ini adalah orang yang dikalahkan, oleh sebab itu menangkanlah (aku).\" (Q.S. Al-Qamar, 10). (maka sesungguhnya sebaik-baik yang memperkenankan) doanya adalah Kami. Maksudnya, Nuh berdoa kepada Allah untuk dimenangkan atas kaumnya, lalu Allah binasakan mereka melalui banjir besar hingga mereka tenggelam semuanya.",[["وَلَقَدْ","And verily"],["نَادَىٰنَا","called Us"],["نُوحٌۭ","Nuh"],["فَلَنِعْمَ","and Best"],["ٱلْمُجِيبُونَ","(are We as) Responders"]]],"3864":["(Dan Kami telah menyelamatkannya beserta keluarganya dari bencana yang besar) yakni dari banjir yang besar itu.",[["وَنَجَّيْنَـٰهُ","And We saved him"],["وَأَهْلَهُۥ","and his family"],["مِنَ","from"],["ٱلْكَرْبِ","the distress"],["ٱلْعَظِيمِ","the great"]]],"3865":["(Dan Kami jadikan anak cucunya orang-orang yang melanjutkan keturunan) dengan demikian maka manusia semuanya adalah anak cucu dari Nabi Nuh a.s. Nabi Nuh mempunyai tiga orang anak, yaitu Sam adalah bapak moyang bangsa Arab, bangsa Persia dan bangsa Romawi; Ham adalah bapak moyang bangsa yang berkulit hitam; Yafits adalah bapak moyang bangsa Turki, bangsa Khazr, Ya'juj dan Ma'juj dan lain-lainnya.",[["وَجَعَلْنَا","And We made"],["ذُرِّيَّتَهُۥ","his offspring"],["هُمُ","[they]"],["ٱلْبَاقِينَ","the survivors"]]],"3866":["(Dan Kami abadikan) Kami lestarikan (untuk Nuh itu) pujian yang baik (di kalangan orang-orang yang datang kemudian) yakni para nabi dan semua umat manusia hingga hari kiamat.",[["وَتَرَكْنَا","And We left"],["عَلَيْهِ","for him"],["فِى","among"],["ٱلْـَٔاخِرِينَ","the later generations"]]],"3867":["(Kesejahteraan) dari Kami dilimpahkan atas Nuh di seluruh alam.)",[["سَلَـٰمٌ","Peace be"],["عَلَىٰ","upon"],["نُوحٍۢ","Nuh"],["فِى","among"],["ٱلْعَـٰلَمِينَ","the worlds"]]],"3868":["(Sesungguhnya demikianlah Kami,) artinya sebagaimana Kami memberikan balasan kepada mereka (Kami memberi balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Indeed, We"],["كَذَٰلِكَ","thus"],["نَجْزِى","[We] reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"3869":["(Sesungguhnya dia termasuk di antara hamba-hamba Kami yang beriman.)",[["إِنَّهُۥ","Indeed, he"],["مِنْ","(was) of"],["عِبَادِنَا","Our slaves"],["ٱلْمُؤْمِنِينَ","believing"]]],"3870":["(Kemudian Kami tenggelamkan orang-orang yang lain) yakni orang-orang kafir dari kaum Nabi Nuh.",[["ثُمَّ","Then"],["أَغْرَقْنَا","We drowned"],["ٱلْـَٔاخَرِينَ","the others"]]],"3871":["(Dan sesungguhnya di antara golongan Nuh) yang mengikutinya dalam masalah pokok agama, yaitu masalah tauhid (adalah Ibrahim) sekalipun jarak zaman di antara keduanya sangat jauh, yaitu dua ribu enam ratus empat puluh tahun; dan adalah di antara keduanya terdapat Nabi Hud dan Nabi Saleh.",[["۞ وَإِنَّ","And indeed"],["مِن","among"],["شِيعَتِهِۦ","his kind"],["لَإِبْرَٰهِيمَ","(was) surely Ibrahim"]]],"3872":["(Ingatlah ketika ia datang kepada Rabbnya) maksudnya, ia mengikuti-Nya sewaktu datang kepada kaumnya (dengan hati yang suci) dari keraguan dan hal-hal lainnya.",[["إِذْ","When"],["جَآءَ","he came"],["رَبَّهُۥ","(to) his Lord"],["بِقَلْبٍۢ","with a heart"],["سَلِيمٍ","sound"]]],"3873":["(Ingatlah ketika ia berkata) sedangkan ia dalam keadaan demikian, yakni bersih dari keraguan terhadap Rabbnya (kepada bapaknya dan kaumnya) dengan nada yang mencela. (\"Apakah) yang (kalian sembah itu?)",[["إِذْ","When"],["قَالَ","he said"],["لِأَبِيهِ","to his father"],["وَقَوْمِهِۦ","and his people"],["مَاذَا","What is it"],["تَعْبُدُونَ","you worship"]]],"3874":["(Apakah dengan jalan berbohong) kedua huruf Hamzah pada ayat ini dapat dibaca Tahqiq atau Tas-hil (kalian menghendaki sesembahan-sesembahan selain Allah?) lafal Ifkan adalah Maf'ul Lah, dan lafal Aalihah adalah Maf'ul Bih bagi lafal Turiduuna. Al-Ifku artinya dusta yang paling buruk; makna yang dimaksud adalah, apakah kalian menyembah selain Allah?",[["أَئِفْكًا","Is it falsehood "],["ءَالِهَةًۭ","gods"],["دُونَ","other than"],["ٱللَّهِ","Allah "],["تُرِيدُونَ","(that) you desire"]]],"3875":["(Maka apakah anggapanmu terhadap Rabb semesta alam?\") jika kalian menyembah selain-Nya; apakah kalian menganggap bahwa Dia akan membiarkan kalian tanpa mengazab kalian? Tentu saja tidak, Dia pasti mengazab kalian. Mereka adalah orang-orang ahli perbintangan. Lalu mereka keluar pada hari raya mereka dan meletakkan makanan mereka di depan latar berhala-berhala mereka, mereka menduga bahwa hal itu dapat membawa berkah pada makanan mereka. Apabila mereka kembali, maka mereka memakan makanan tersebut. Mereka mengatakan kepada Nabi Ibrahim, \"Marilah kita keluar.\"",[["فَمَا","Then what"],["ظَنُّكُم","(do) you think"],["بِرَبِّ","about (the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"3876":["(Lalu ia memandang sekali pandang ke bintang-bintang) untuk mengelabui mereka, bahwasanya dia percaya kepada bintang-bintang itu, supaya mereka tidak menaruh rasa curiga terhadap dirinya.",[["فَنَظَرَ","Then he glanced"],["نَظْرَةًۭ","a glance"],["فِى","at"],["ٱلنُّجُومِ","the stars"]]],"3877":["(Kemudian ia berkata, \"Sesungguhnya aku sakit\") maksudnya, aku akan mengalami sakit.",[["فَقَالَ","And he said"],["إِنِّى","Indeed, I am"],["سَقِيمٌۭ","sick"]]],"3878":["(Lalu mereka berpaling daripadanya) menuju ke tempat perayaan mereka (dengan membelakangi)",[["فَتَوَلَّوْا۟","So they turned away"],["عَنْهُ","from him"],["مُدْبِرِينَ","departing"]]],"3879":["(Kemudian ia pergi dengan diam-diam) atau Nabi Ibrahim berangkat dengan diam-diam menuju (kepada berhala-berhala mereka) yang pada saat itu di hadapannya terdapat banyak hidangan makanan (lalu ia berkata) dengan nada yang sinis ditujukan kepada berhala-berhala mereka itu, (\"Apakah kalian tidak makan?\") tetapi berhala-berhala itu diam saja.",[["فَرَاغَ","Then he turned"],["إِلَىٰٓ","to"],["ءَالِهَتِهِمْ","their gods"],["فَقَالَ","and said"],["أَلَا","Do not"],["تَأْكُلُونَ","you eat"]]],"3880":["Maka Ibrahim berkata, (\"Kenapa kalian tidak menjawab?\") ternyata berhala-berhala itu tidak juga menjawab.",[["مَا","What (is)"],["لَكُمْ","for you"],["لَا","not"],["تَنطِقُونَ","you speak"]]],"3881":["(Lalu dihadapinya berhala-berhala itu sambil memukulnya dengan tangan kanannya) artinya, dengan sekuat-kuatnya hingga berhala-berhala itu pecah berantakan. Berita penghancuran berhala-berhala itu sampai kepada kaumnya melalui orang-orang yang melihat Nabi Ibrahim sedang menghancurkannya.",[["فَرَاغَ","Then he turned"],["عَلَيْهِمْ","upon them"],["ضَرْبًۢا","striking"],["بِٱلْيَمِينِ","with the right hand"]]],"3882":["(Kemudian kaumnya datang kepadanya dengan bergegas) mereka berjalan dengan terburu-buru, lalu mereka berkata kepada Nabi Ibrahim, \"Kami menyembahnya sedangkan kamu memecahkannya.\"",[["فَأَقْبَلُوٓا۟","Then they advanced"],["إِلَيْهِ","towards him"],["يَزِفُّونَ","hastening"]]],"3883":["(Ibrahim berkata) kepada mereka dengan nada sinis, (\"Apakah kalian menyembah patung-patung yang kalian pahat itu?) dari batu dan dari bahan-bahan lainnya sebagai berhala-berhala yang kalian sembah.",[["قَالَ","He said"],["أَتَعْبُدُونَ","Do you worship"],["مَا","what"],["تَنْحِتُونَ","you carve"]]],"3884":["(Padahal Allahlah yang telah menciptakan kalian dan apa yang kalian perbuat itu\") yakni tentang apa yang kalian pahat dan hasil pahatan kalian itu, karenanya sembahlah Dia dan esakanlah Dia. Huruf Maa di sini menurut suatu pendapat adalah Maa Mashdariyah, menurut pendapat lainnya adalah Maa Maushulah, dan menurut pendapat lainnya lagi adalah Maa Maushufah.",[["وَٱللَّهُ","While Allah"],["خَلَقَكُمْ","created you"],["وَمَا","and what"],["تَعْمَلُونَ","you make"]]],"3885":["(Mereka berkata) di antara sesama mereka (\"Dirikanlah suatu bangunan untuknya) lalu kumpulkanlah kayu-kayu bakar di bawahnya, dan nyalakanlah api padanya, maka apabila ia telah menyala (lemparkanlah dia ke dalam api yang menyala-nyala itu\") yakni ke dalam api yang telah membesar nyalanya itu.",[["قَالُوا۟","They said"],["ٱبْنُوا۟","Build"],["لَهُۥ","for him"],["بُنْيَـٰنًۭا","a structure"],["فَأَلْقُوهُ","and throw him"],["فِى","into"],["ٱلْجَحِيمِ","the blazing Fire"]]],"3886":["(Mereka hendak melakukan tipu muslihat kepadanya) dengan melemparkannya ke dalam api yang menyala-nyala untuk membinasakannya (maka Kami jadikan mereka orang-orang yang hina) orang-orang yang dikalahkan; karena ternyata Nabi Ibrahim keluar dari dalam api itu dalam keadaan selamat tidak apa-apa.",[["فَأَرَادُوا۟","And they intended"],["بِهِۦ","for him"],["كَيْدًۭا","a plot"],["فَجَعَلْنَـٰهُمُ","but We made them"],["ٱلْأَسْفَلِينَ","the lowest"]]],"3887":["(Dan Ibrahim berkata, \"Sesungguhnya aku pergi menghadap kepada Rabbku) artinya berhijrah demi karena-Nya meninggalkan negeri orang-orang kafir (dan Dia akan memberi petunjuk kepadaku) ke tempat yang aku diperintahkan-Nya berangkat ke sana, yaitu negeri Syam. Tatkala ia sampai di tanah suci yaitu Baitulmakdis, berkatalah ia dalam doanya,",[["وَقَالَ","And he said"],["إِنِّى","Indeed, I am"],["ذَاهِبٌ","going"],["إِلَىٰ","to"],["رَبِّى","my Lord"],["سَيَهْدِينِ","He will guide me"]]],"3888":["('Ya Rabbku! Anugerahkanlah kepadaku) seorang anak (yang termasuk orang-orang yang saleh.')",[["رَبِّ","My Lord"],["هَبْ","grant"],["لِى","me"],["مِنَ","of"],["ٱلصَّـٰلِحِينَ","the righteous"]]],"3889":["(Maka Kami beri dia kabar gembira dengan seorang anak yang amat sabar) yakni yang banyak memiliki kesabaran.",[["فَبَشَّرْنَـٰهُ","So We gave him the glad tidings"],["بِغُلَـٰمٍ","of a boy"],["حَلِيمٍۢ","forbearing"]]],"3890":["(Maka tatkala anak itu sampai pada umur sanggup berusaha bersama-sama Ibrahim) yaitu telah mencapai usia sehingga dapat membantunya bekerja; menurut suatu pendapat bahwa umur anak itu telah mencapai tujuh tahun. Menurut pendapat yang lain bahwa pada saat itu anak Nabi Ibrahim berusia tiga belas tahun (Ibrahim berkata, \"Hai anakku! Sesungguhnya aku melihat) maksudnya, telah melihat (dalam mimpi bahwa aku menyembelihmu!) mimpi para nabi adalah mimpi yang benar, dan semua pekerjaan mereka berdasarkan perintah dari Allah swt. (maka pikirkanlah apa pendapatmu!\") tentang impianku itu; Nabi Ibrahim bermusyawarah dengannya supaya ia menurut, mau disembelih, dan taat kepada perintah-Nya. (Ia menjawab, \"Hai bapakku) huruf Ta pada lafal Abati ini merupakan pergantian dari Ya Idhafah (kerjakanlah apa yang diperintahkan kepadamu) untuk melakukannya (Insya Allah engkau akan mendapatiku termasuk orang-orang yang sabar\") menghadapi hal tersebut.",[["فَلَمَّا","Then when"],["بَلَغَ","he reached"],["مَعَهُ","the (age of) working with him"],["ٱلسَّعْىَ","the (age of) working with him"],["قَالَ","he said"],["يَـٰبُنَىَّ","O my son"],["إِنِّىٓ","Indeed, I"],["أَرَىٰ","have seen"],["فِى","in"],["ٱلْمَنَامِ","the dream"],["أَنِّىٓ","that I am"],["أَذْبَحُكَ","sacrificing you"],["فَٱنظُرْ","so look"],["مَاذَا","what"],["تَرَىٰ ۚ","you see"],["قَالَ","He said"],["يَـٰٓأَبَتِ","O my father"],["ٱفْعَلْ","Do"],["مَا","what"],["تُؤْمَرُ ۖ","you are commanded"],["سَتَجِدُنِىٓ","You will find me"],["إِن","if"],["شَآءَ","Allah wills"],["ٱللَّهُ","Allah wills"],["مِنَ","of"],["ٱلصَّـٰبِرِينَ","the patient ones"]]],"3891":["(Tatkala keduanya telah berserah diri) artinya, tunduk dan patuh kepada perintah Allah swt. (dan Ibrahim membaringkan anaknya atas pelipisnya) Nabi Ismail dibaringkan pada salah satu pelipisnya; setiap manusia memiliki dua pelipis dan di antara keduanya terdapat jidat. Kejadian ini di Mina; kemudian Nabi Ibrahim menggorokkan pisau besarnya ke leher Nabi Ismail, akan tetapi berkat kekuasaan Allah pisau itu tidak mempan sedikit pun.",[["فَلَمَّآ","Then when"],["أَسْلَمَا","both of them had submitted"],["وَتَلَّهُۥ","and he put him down"],["لِلْجَبِينِ","upon his forehead"]]],"3892":["(Dan Kami panggil dia, \"Hai Ibrahim!)",[["وَنَـٰدَيْنَـٰهُ","And We called out to him"],["أَن","that"],["يَـٰٓإِبْرَٰهِيمُ","O Ibrahim"]]],"3893":["(Sesungguhnya kamu telah membenarkan mimpimu itu\") melalui apa yang telah kamu kerjakan, yaitu melaksanakan penyembelihan yang diperintahkan itu atau dengan kata lain, cukuplah bagimu hal itu. Jumlah kalimat Naadainaahu merupakan jawab dari lafal Lammaa, hanya ditambahi Wau (sesungguhnya demikianlah) maksudnya, sebagaimana Kami memberikan pahala kepadamu (Kami memberi balasan kepada orang-orang yang berbuat baik) terhadap diri mereka sendiri dengan melaksanakan apa yang diperintahkan kepada mereka, yaitu Kami akan melepaskan mereka dari kesulitan.",[["قَدْ","Verily"],["صَدَّقْتَ","you have fulfilled"],["ٱلرُّءْيَآ ۚ","the vision"],["إِنَّا","Indeed, We"],["كَذَٰلِكَ","thus"],["نَجْزِى","[We] reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"3894":["(Sesungguhnya ini) penyembelihan yang diperintahkan ini (benar-benar suatu ujian yang nyata) atau cobaan yang jelas.",[["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَهُوَ","(was) surely [it]"],["ٱلْبَلَـٰٓؤُا۟","the trial"],["ٱلْمُبِينُ","clear"]]],"3895":["(Dan Kami tebus anak itu) maksudnya, anak yang diperintahkan untuk disembelih (Nabi Ismail). Menurut suatu pendapat bahwa anak yang disembelih itu adalah Nabi Ishak (dengan seekor sembelihan) yakni dengan domba (yang besar) dari surga, yaitu domba yang sama dengan domba yang dijadikan kurban oleh Habil. Domba itu dibawa oleh malaikat Jibril, lalu Nabi Ibrahim menyembelihnya seraya membaca takbir.",[["وَفَدَيْنَـٰهُ","And We ransomed him"],["بِذِبْحٍ","with a sacrifice"],["عَظِيمٍۢ","great"]]],"3896":["(Kami abadikan) Kami lestarikan (untuk Ibrahim itu di kalangan orang-orang yang datang kemudian) pujian yang baik.",[["وَتَرَكْنَا","And We left"],["عَلَيْهِ","for him"],["فِى","among"],["ٱلْـَٔاخِرِينَ","the later generations"]]],"3897":["(\"Kesejahteraan) dari Kami (dilimpahkan atas Ibrahim.\")",[["سَلَـٰمٌ","Peace be"],["عَلَىٰٓ","on"],["إِبْرَٰهِيمَ","Ibrahim"]]],"3898":["(Demikianlah) sebagaimana Kami memberikan imbalan pahala kepada Ibrahim (kami memberi balasan kepada orang-orang yang berbuat baik) terhadap diri mereka sendiri.",[["كَذَٰلِكَ","Thus"],["نَجْزِى","We reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"3899":["(Sesungguhnya ia termasuk hamba-hamba Kami yang beriman.)",[["إِنَّهُۥ","Indeed, he (was)"],["مِنْ","of"],["عِبَادِنَا","Our slaves"],["ٱلْمُؤْمِنِينَ","believing"]]],"3900":["(Dan Kami beri dia kabar gembira dengan kelahiran Ishak) dengan adanya ayat ini dapat disimpulkan, bahwa anak yang disembelih itu bukanlah Nabi Ishak tetapi anak Nabi Ibrahim yang lainnya, yaitu Nabi Ismail (seorang nabi) menjadi Hal dari lafal yang diperkirakan keberadaannya, artinya kelak ia akan menjadi seorang nabi (yang termasuk orang-orang yang saleh.)",[["وَبَشَّرْنَـٰهُ","And We gave him glad tidings"],["بِإِسْحَـٰقَ","of Isaac"],["نَبِيًّۭا","a Prophet"],["مِّنَ","among"],["ٱلصَّـٰلِحِينَ","the righteous"]]],"3901":["(Kami limpahkan keberkatan atasnya) dengan diperbanyak anak cucunya (dan atas Ishak) anak Nabi Ibrahim, yaitu Kami menjadikan kebanyakan para nabi dari keturunannya. (Dan di antara anak cucunya ada yang berbuat baik) maksudnya, yang beriman (dan ada pula yang lalim terhadap dirinya sendiri) yang kafir (dengan nyata) nyata kekafirannya.",[["وَبَـٰرَكْنَا","And We blessed"],["عَلَيْهِ","him"],["وَعَلَىٰٓ","and [on]"],["إِسْحَـٰقَ ۚ","Isaac"],["وَمِن","And of"],["ذُرِّيَّتِهِمَا","their offspring"],["مُحْسِنٌۭ","(are) good-doers"],["وَظَالِمٌۭ","and unjust"],["لِّنَفْسِهِۦ","to himself"],["مُبِينٌۭ","clear"]]],"3902":["(Dan sesungguhnya Kami telah melimpahkan nikmat atas Musa dan Harun) yakni nikmat kenabian.",[["وَلَقَدْ","And verily"],["مَنَنَّا","We conferred Favor"],["عَلَىٰ","upon"],["مُوسَىٰ","Musa"],["وَهَـٰرُونَ","and Harun"]]],"3903":["(Dan Kami selamatkan keduanya dan kaumnya) yaitu kaum Bani Israel (dari bencana yang besar) dari perbudakan Firaun atas mereka.",[["وَنَجَّيْنَـٰهُمَا","And We saved both of them"],["وَقَوْمَهُمَا","and their people"],["مِنَ","from"],["ٱلْكَرْبِ","the distress"],["ٱلْعَظِيمِ","the great"]]],"3904":["(Dan Kami tolong mereka) dari cengkeraman bangsa Koptik (maka jadilah mereka orang-orang yang menang.)",[["وَنَصَرْنَـٰهُمْ","And We helped them"],["فَكَانُوا۟","so they became"],["هُمُ","so they became"],["ٱلْغَـٰلِبِينَ","the victors"]]],"3905":["(Dan Kami berikan kepada keduanya kitab yang sangat jelas) yang di dalamnya terkandung hukum-hukum dan batasan-batasan serta hal-hal lainnya, yang kesemuanya itu diterangkan dengan jelas dan gamblang di dalamnya; Kitab yang dimaksud adalah Kitab Taurat.",[["وَءَاتَيْنَـٰهُمَا","And We gave both of them"],["ٱلْكِتَـٰبَ","the Book"],["ٱلْمُسْتَبِينَ","the clear"]]],"3906":["(Dan kami tunjuki keduanya ke jalan) yakni kepada tuntunan (yang lurus.)",[["وَهَدَيْنَـٰهُمَا","And We guided both of them"],["ٱلصِّرَٰطَ","(to) the Path"],["ٱلْمُسْتَقِيمَ","the Straight"]]],"3907":["(Dan Kami abadikan) Kami lestarikan (untuk keduanya di kalangan orang-orang yang datang kemudian) pujian yang baik.",[["وَتَرَكْنَا","And We left"],["عَلَيْهِمَا","for both of them"],["فِى","among"],["ٱلْـَٔاخِرِينَ","the later generations"]]],"3908":["(Yaitu \"Kesejahteraan) dari Kami (dilimpahkan atas Musa dan Harun\".')",[["سَلَـٰمٌ","Peace be"],["عَلَىٰ","upon"],["مُوسَىٰ","Musa"],["وَهَـٰرُونَ","and Harun"]]],"3909":["(Sesungguhnya demikianlah) maksudnya, sebagaimana Kami memberikan balasan pahala kepada keduanya (Kami memberi balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Indeed, We"],["كَذَٰلِكَ","thus"],["نَجْزِى","reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"3910":["(Sesungguhnya keduanya termasuk hamba-hamba Kami yang beriman.)",[["إِنَّهُمَا","Indeed, both of them"],["مِنْ","(were) of"],["عِبَادِنَا","Our slaves"],["ٱلْمُؤْمِنِينَ","believing"]]],"3911":["(Dan sesungguhnya Ilyas) dapat dibaca Ilyaas atau Alyaas (benar-benar termasuk salah seorang rasul-rasul) menurut suatu pendapat bahwa Nabi Ilyas itu adalah anak saudara lelaki Nabi Harun dan Nabi Musa. Menurut pendapat yang lain bukan; ia diutus oleh Allah kepada kaum yang tinggal di kota Ba'albak dan sekitarnya.",[["وَإِنَّ","And indeed"],["إِلْيَاسَ","Elijah"],["لَمِنَ","(was) surely of"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"3912":["(Ingatlah ketika) lafal Idz di sini dinashabkan oleh lafal Udzkur yang diperkirakan keberadaannya (ia berkata kepada kaumnya, \"Mengapa kalian tidak bertakwa) kepada Allah?",[["إِذْ","When"],["قَالَ","he said"],["لِقَوْمِهِۦٓ","to his people"],["أَلَا","Will not"],["تَتَّقُونَ","you fear"]]],"3913":["(Patutkah kalian menyembah Ba'l) Ba'l adalah nama berhala yang terbuat dari emas, dan dengan nama berhala itu pula negeri mereka diberi nama, lalu dimudhafkan kepada lafal Bik, sehingga jadilah Ba'alabak. Maksud ayat ini ialah mengapa kalian menyembahnya (dan kalian tinggalkan) artinya kalian tidak menyembah (sebaik-baik pencipta) yakni Allah; maksudnya mengapa kalian tidak menyembah Allah?",[["أَتَدْعُونَ","Do you call"],["بَعْلًۭا","Baal"],["وَتَذَرُونَ","and you forsake"],["أَحْسَنَ","(the) Best"],["ٱلْخَـٰلِقِينَ","(of) Creators "]]],"3914":["(Yaitu Allah Rabb kalian dan Rabb bapak-bapak kalian yang terdahulu?\") kalau dibaca Allaahu Rabbukum Warabbu Aabaa-ikum, berarti sebelumnya diperkirakan adanya lafal Huwa. Kalau dibaca Allaaha Rabbakum warabba Aabaa-ikum berarti menjadi Badal dari lafal Ahsanal Khaaliqiina.",[["ٱللَّهَ","Allah"],["رَبَّكُمْ","your Lord"],["وَرَبَّ","and (the) Lord"],["ءَابَآئِكُمُ","(of) your forefathers"],["ٱلْأَوَّلِينَ","(of) your forefathers"]]],"3915":["(Maka mereka mendustakannya, karena itu mereka akan diseret) ke dalam neraka.",[["فَكَذَّبُوهُ","But they denied him"],["فَإِنَّهُمْ","so indeed, they"],["لَمُحْضَرُونَ","(will) surely be brought"]]],"3916":["(Kecuali hamba-hamba Allah yang dibersihkan dari dosa) yaitu hamba-hamba Allah yang beriman, mereka diselamatkan dari neraka.",[["إِلَّا","Except"],["عِبَادَ","(the) slaves"],["ٱللَّهِ","(of) Allah"],["ٱلْمُخْلَصِينَ","the chosen ones"]]],"3917":["(Dan Kami abadikan untuk Ilyas di kalangan orang-orang yang datang kemudian) pujian yang baik.",[["وَتَرَكْنَا","And We left"],["عَلَيْهِ","for him"],["فِى","among"],["ٱلْـَٔاخِرِينَ","the later generations"]]],"3918":["(Yaitu \"Kesejahteraan) dari Kami (dilimpahkan atas Ilyasin) yang dimaksud adalah Nabi Ilyas yang tadi, ia dinamakan demikian secara Taghlib, perihalnya sama dengan ucapan orang-orang Arab jika menamakan Muhallab dan kaumnya, mereka menamakannya Al-Muhallabuun. Dan menurut qiraat yang membacakannya menjadi Aali Yasiina dengan dipanjangkan harakat Hamzahnya, berarti keluarga Nabi Ilyas, dan makna yang dimaksud adalah Nabi Ilyas pula.",[["سَلَـٰمٌ","Peace be"],["عَلَىٰٓ","upon"],["إِلْ يَاسِينَ","Elijah"]]],"3919":["(Sesungguhnya demikianlah) sebagaimana Kami memberikan balasan pahala kepadanya (Kami memberikan balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Indeed, We"],["كَذَٰلِكَ","thus"],["نَجْزِى","reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"3920":["(Sesungguhnya dia termasuk hamba-hamba Kami yang beriman.)",[["إِنَّهُۥ","Indeed, he (was)"],["مِنْ","of"],["عِبَادِنَا","Our slaves"],["ٱلْمُؤْمِنِينَ","believing"]]],"3921":["(Dan sesungguhnya Luth benar-benar adalah seorang rasul.)",[["وَإِنَّ","And indeed"],["لُوطًۭا","Lut"],["لَّمِنَ","(was) of"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"3922":["(Ingatlah ketika Kami selamatkan dia dan keluarganya pengikut-pengikutnya semua.)",[["إِذْ","When"],["نَجَّيْنَـٰهُ","We saved him"],["وَأَهْلَهُۥٓ","and his family"],["أَجْمَعِينَ","all"]]],"3923":["(Kecuali seorang perempuan tua istrinya yang berada bersama-sama orang yang ditinggal) orang-orang yang ditinggal tertimpa azab.",[["إِلَّا","Except"],["عَجُوزًۭا","an old woman"],["فِى","(was) among"],["ٱلْغَـٰبِرِينَ","those who remained behind"]]],"3924":["(Kemudian Kami binasakan) Kami hancurkan (orang-orang yang lain) yaitu orang-orang yang kafir dari kaumnya.",[["ثُمَّ","Then"],["دَمَّرْنَا","We destroyed"],["ٱلْـَٔاخَرِينَ","the others"]]],"3925":["(Dan sesungguhnya kalian hai penduduk Mekah benar-benar akan melalui mereka) melalui bekas-bekas dan tempat-tempat tinggal mereka bila kalian mengadakan perjalanan (di waktu pagi) maksudnya di waktu siang hari.",[["وَإِنَّكُمْ","And indeed, you"],["لَتَمُرُّونَ","surely pass"],["عَلَيْهِم","by them"],["مُّصْبِحِينَ","(in the) morning"]]],"3926":["(Dan di waktu malam hari. Maka apakah kalian tidak memikirkan?) hai penduduk Mekah, mengenai apa yang telah menimpa mereka berupa azab, oleh karena kalian lalu mengambil pelajaran darinya.",[["وَبِٱلَّيْلِ ۗ","And at night"],["أَفَلَا","Then will not"],["تَعْقِلُونَ","you use reason"]]],"3927":["(Sesungguhnya Yunus benar-benar salah seorang rasul.)",[["وَإِنَّ","And indeed"],["يُونُسَ","Yunus"],["لَمِنَ","(was) surely of"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"3928":["(Ingatlah ketika ia lari) maksudnya, minggat (ke kapal yang penuh muatan) hal ini terjadi sewaktu ia bersitegang dengan kaumnya, karena ternyata azab yang diancamkan olehnya kepada kaumnya tidak turun-turun juga, akhirnya ia melarikan diri naik kapal. Dan kapal yang dinaikinya itu berhenti di tengah laut yang besar ombaknya. Juru mudi kapal mengatakan, bahwa di dalam kapal ini terdapat seorang hamba yang melarikan diri dari tuannya, hal ini akan tampak jelas melalui undian.",[["إِذْ","When"],["أَبَقَ","he ran away"],["إِلَى","to"],["ٱلْفُلْكِ","the ship"],["ٱلْمَشْحُونِ","laden"]]],"3929":["(Kemudian ia ikut berundi) para penumpang kapal itu semuanya diundi (lalu dia termasuk orang-orang yang kalah dalam undian itu) akibatnya ia dilemparkan ke laut.",[["فَسَاهَمَ","Then he drew lots"],["فَكَانَ","and was"],["مِنَ","of"],["ٱلْمُدْحَضِينَ","the losers"]]],"3930":["(Maka ia ditelan oleh ikan besar) ditelan bulat-bulat (dalam keadaan tercela) karena ia melakukan perbuatan yang tercela, yaitu pergi dengan memakai jalan laut kemudian naik kapal meninggalkan kaumnya, tanpa izin terlebih dahulu dari Rabbnya.",[["فَٱلْتَقَمَهُ","Then swallowed him"],["ٱلْحُوتُ","the fish"],["وَهُوَ","while he"],["مُلِيمٌۭ","(was) blameworthy"]]],"3931":["(Maka kalau sekiranya dia tidak termasuk orang-orang yang bertasbih) yakni selalu ingat kepada Allah, melalui zikirnya di dalam perut ikan seraya mengatakan, \"Laa Ilaaha Illaa Anta Subhaanaka Innii Kuntu Minazh Zhaalimiina\", artinya, \"Tidak ada Tuhan selain Engkau, Maha Suci Engkau, sesungguhnya aku termasuk orang-orang yang aniaya.\"",[["فَلَوْلَآ","And if not"],["أَنَّهُۥ","that he"],["كَانَ","was"],["مِنَ","of"],["ٱلْمُسَبِّحِينَ","those who glorify"]]],"3932":["(Niscaya ia akan tetap tinggal di perut ikan itu sampai hari berbangkit) artinya, niscaya perut ikan besar itu akan menjadi kuburnya hingga hari kiamat nanti.",[["لَلَبِثَ","Certainly, he (would have) remained"],["فِى","in"],["بَطْنِهِۦٓ","its belly"],["إِلَىٰ","until"],["يَوْمِ","the Day"],["يُبْعَثُونَ","they are resurrected"]]],"3933":["(Kemudian Kami lemparkan dia) Kami campakkan dia dari dalam perut ikan besar itu (ke daerah yang tandus) di permukaan bumi yang tandus, yakni ke tepi pantai pada hari itu juga, setelah tiga hari, tujuh hari, dua puluh hari atau setelah empat puluh hari sejak ia ditelan ikan besar itu (sedangkan ia dalam keadaan sakit) yakni kurus kering dan sakit bagaikan anak ayam yang terserang penyakit kok.",[["۞ فَنَبَذْنَـٰهُ","But We cast him"],["بِٱلْعَرَآءِ","onto the open shore"],["وَهُوَ","while he"],["سَقِيمٌۭ","(was) ill"]]],"3934":["(Dan Kami tumbuhkan untuk dia sebatang pohon dari jenis labu) pohon itu dapat menaunginya dengan batangnya, berbeda keadaannya dengan pohon labu yang biasanya. Hal ini merupakan suatu mukjizat baginya, setiap pagi dan petang datang kepadanya kambing hutan, ia meminum air susu dari teteknya hingga ia kuat kembali.",[["وَأَنۢبَتْنَا","And We caused to grow"],["عَلَيْهِ","over him"],["شَجَرَةًۭ","a plant"],["مِّن","of"],["يَقْطِينٍۢ","gourd"]]],"3935":["(Dan Kami utus dia) sesudah itu, sebagaimana status sebelumnya, kepada kaum Bunainawiy yang tinggal di daerah Maushul (kepada seratus ribu orang atau) bahkan (lebih dari itu) yakni lebih dua puluh atau tiga puluh atau tujuh puluh ribu orang.",[["وَأَرْسَلْنَـٰهُ","And We sent him"],["إِلَىٰ","to"],["مِا۟ئَةِ","a hundred"],["أَلْفٍ","thousand"],["أَوْ","or"],["يَزِيدُونَ","more"]]],"3936":["(Lalu mereka beriman) sewaktu mereka menyaksikan azab yang telah dijanjikan kepada mereka (karena itu Kami anugerahkan kenikmatan hidup kepada mereka) artinya, kami biarkan mereka menikmati harta yang ada pada mereka (hingga waktu yang tertentu) hingga ajal mereka datang.",[["فَـَٔامَنُوا۟","And they believed"],["فَمَتَّعْنَـٰهُمْ","so We gave them enjoyment"],["إِلَىٰ","for"],["حِينٍۢ","a while"]]],"3937":["(Tanyakanlah kepada mereka) kepada orang-orang kafir Mekah; ungkapan ini dimaksud sebagai ejekan terhadap mereka, (\"Apakah untuk Rabb kamu anak-anak perempuan) sesuai dengan dugaan mereka bahwa para malaikat itu adalah anak-anak perempuan Allah (dan untuk mereka anak laki-laki) mereka memilih yang lebih kuat dan yang lebih baik.",[["فَٱسْتَفْتِهِمْ","Then ask them"],["أَلِرَبِّكَ","Does your Lord"],["ٱلْبَنَاتُ","(have) daughters"],["وَلَهُمُ","while for them"],["ٱلْبَنُونَ","(are) sons"]]],"3938":["(Atau apakah Kami menciptakan malaikat-malaikat berupa perempuan dan mereka menyaksikannya\") yakni mereka menyaksikan penciptaan Kami itu, yang karenanya mereka mengatakan demikian?",[["أَمْ","Or"],["خَلَقْنَا","did We create"],["ٱلْمَلَـٰٓئِكَةَ","the Angels"],["إِنَـٰثًۭا","females"],["وَهُمْ","while they"],["شَـٰهِدُونَ","(were) witnesses"]]],"3939":["(Ketahuilah bahwa sesungguhnya mereka dengan kebohongannya) dengan kedustaan mereka itu (benar-benar mengatakan,)",[["أَلَآ","No doubt"],["إِنَّهُم","indeed, they"],["مِّنْ","of"],["إِفْكِهِمْ","their falsehood"],["لَيَقُولُونَ","[they] say"]]],"3940":["(\"Allah beranak\") melalui perkataan mereka yang menyatakan bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah. (Dan sesungguhnya mereka benar-benar orang yang berdusta) dalam hal ini.",[["وَلَدَ","Allah has begotten"],["ٱللَّهُ","Allah has begotten"],["وَإِنَّهُمْ","and indeed, they"],["لَكَـٰذِبُونَ","surely (are) liars"]]],"3941":["(Apakah Tuhan memilih) lafal Ashthafaa Hamzahnya adalah Hamzah Istifham yang berharakat Fatah, oleh karenanya Hamzah Washal tidak dibutuhkan lagi, sebab itu dibuang. Yakni apakah Allah mengutamakan (anak-anak perempuan daripada anak laki-laki?)",[["أَصْطَفَى","Has He chosen"],["ٱلْبَنَاتِ","[the] daughters"],["عَلَى","over"],["ٱلْبَنِينَ","sons"]]],"3942":["(Apakah yang terjadi pada kalian? Bagaimanakah caranya kalian menetapkan?) kesimpulan yang rusak ini.",[["مَا","What is with you"],["لَكُمْ","What is with you"],["كَيْفَ","How"],["تَحْكُمُونَ","you judge"]]],"3943":["(Maka apakah kalian tidak memikirkan?) bahwasanya Allah swt. itu Maha Tinggi lagi Maha Suci dari mempunyai anak?",[["أَفَلَا","Then will not"],["تَذَكَّرُونَ","you pay heed"]]],"3944":["(Atau apakah kalian mempunyai bukti yang nyata?) artinya hujah yang jelas menyatakan bahwa Allah mempunyai anak.",[["أَمْ","Or"],["لَكُمْ","(is) for you"],["سُلْطَـٰنٌۭ","an authority"],["مُّبِينٌۭ","clear"]]],"3945":["(Maka bawalah kitab kalian) kitab Taurat kalian, kemudian perlihatkanlah kepadaku mengenai hal itu di dalamnya (jika kalian memang orang-orang yang benar) di dalam perkataan dan dugaan kalian itu.",[["فَأْتُوا۟","Then bring"],["بِكِتَـٰبِكُمْ","your book"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"3946":["(Dan mereka adakan) orang-orang musyrik itu (antara Dia) yakni Allah swt. (dan antara jin) yakni malaikat dinamakan Al-Jinnah karena mereka tidak dapat dilihat oleh mata (hubungan nasab) melalui perkataan mereka yang menyatakan bahwasanya malaikat-malaikat itu adalah anak-anak perempuan Allah. (Dan sesungguhnya jin mengetahui bahwa mereka) yakni orang-orang yang mengatakan demikian (benar-benar akan diseret) ke dalam neraka dan mereka akan diazab di dalamnya.",[["وَجَعَلُوا۟","And they have made"],["بَيْنَهُۥ","between Him"],["وَبَيْنَ","and between"],["ٱلْجِنَّةِ","the jinn"],["نَسَبًۭا ۚ","a relationship"],["وَلَقَدْ","but certainly"],["عَلِمَتِ","know"],["ٱلْجِنَّةُ","the jinn"],["إِنَّهُمْ","that they"],["لَمُحْضَرُونَ","(will) surely be brought"]]],"3947":["(Maha Suci Allah) kalimat ini memahasucikan Dia (dari apa yang mereka sifatkan) yaitu bahwasanya Allah mempunyai anak.",[["سُبْحَـٰنَ","Glory be"],["ٱللَّهِ","(to) Allah"],["عَمَّا","above what"],["يَصِفُونَ","they attribute"]]],"3948":["(Kecuali hamba-hamba Allah yang dibersihkan dari dosa) yakni kecuali orang-orang yang beriman. Istitsna di sini adalah bersifat Munqathi'. Maksudnya bahwa mereka yang beriman itu memahasucikan Allah swt. dari apa yang telah disifatkan oleh mereka kepada-Nya.",[["إِلَّا","Except"],["عِبَادَ","(the) slaves"],["ٱللَّهِ","(of) Allah"],["ٱلْمُخْلَصِينَ","the chosen"]]],"3949":["(Maka sesungguhnya kalian dan apa-apa yang kalian sembah itu) yakni berhala-berhala sesembahan-sesembahan kalian itu.",[["فَإِنَّكُمْ","So indeed, you"],["وَمَا","and what"],["تَعْبُدُونَ","you worship"]]],"3950":["(Sekali-kali kalian dengannya tidak akan dapat) dengan melalui sesembahan kalian itu; lafal 'Alaihi berta'alluq kepada firman selanjutnya, yaitu (menyesatkan) seorang pun.",[["مَآ","Not"],["أَنتُمْ","you"],["عَلَيْهِ","from Him"],["بِفَـٰتِنِينَ","can tempt away (anyone)"]]],"3951":["(Kecuali orang-orang yang akan masuk neraka yang menyala-nyala) menurut ilmu Allah swt.",[["إِلَّا","Except"],["مَنْ","who"],["هُوَ","he"],["صَالِ","(is) to burn"],["ٱلْجَحِيمِ","(in) the Hellfire"]]],"3952":["Malaikat Jibril berkata kepada Nabi saw., (\"Tiada seorang pun di antara kami) para malaikat (melainkan mempunyai kedudukan yang tertentu) di langit, di tempat itu ia beribadah kepada Allah dan tidak melampaui tempat atau kedudukan yang lain.",[["وَمَا","And not"],["مِنَّآ","among us"],["إِلَّا","except"],["لَهُۥ","for him"],["مَقَامٌۭ","(is) a position"],["مَّعْلُومٌۭ","known"]]],"3953":["(Dan sesungguhnya kami benar-benar bersaf-saf) artinya meluruskan telapak kaki kami dalam salat.",[["وَإِنَّا","And indeed, we"],["لَنَحْنُ","surely, [we]"],["ٱلصَّآفُّونَ","stand in rows"]]],"3954":["(Dan sesungguhnya kami benar-benar bertasbih.\") menyucikan Allah dari hal-hal yang tidak layak bagi-Nya.",[["وَإِنَّا","And indeed, we"],["لَنَحْنُ","surely, [we]"],["ٱلْمُسَبِّحُونَ","glorify (Allah)"]]],"3955":["(Sesungguhnya) lafal In di sini adalah bentuk Takhfif dari lafal Inna (mereka) yakni orang-orang kafir Mekah (akan berkata,)",[["وَإِن","And indeed"],["كَانُوا۟","they used to"],["لَيَقُولُونَ","say"]]],"3956":["(\"Kalau sekiranya di sisi kami ada sebuah peringatan) maksudnya, sebuah kitab (dari orang-orang yang dahulu) yakni dari kitab-kitab yang diturunkan kepada orang-orang yang dahulu.",[["لَوْ","If"],["أَنَّ","that"],["عِندَنَا","we had"],["ذِكْرًۭا","a reminder"],["مِّنَ","from"],["ٱلْأَوَّلِينَ","the former (people)"]]],"3957":["(Benar-benar kami akan jadi hamba Allah yang mukhlis\") maksudnya beribadah kepada-Nya semata.",[["لَكُنَّا","Certainly, we (would) have been"],["عِبَادَ","slaves"],["ٱللَّهِ","(of) Allah"],["ٱلْمُخْلَصِينَ","the chosen"]]],"3958":["Allah berfirman, (\"Tetapi mereka mengingkarinya) mengingkari Kitab yang diturunkan kepada mereka, yaitu Alquran kitab yang lebih mulia daripada kitab-kitab yang diturunkan sebelumnya (kelak mereka akan mengetahui) akibat dari kekafiran dan keingkaran mereka itu.",[["فَكَفَرُوا۟","But they disbelieved"],["بِهِۦ ۖ","in it"],["فَسَوْفَ","so soon"],["يَعْلَمُونَ","they will know"]]],"3959":["(Dan sesungguhnya telah tetap janji Kami) pertolongan Kami (kepada hamba-hamba Kami yang menjadi rasul) yaitu sebagaimana yang telah diungkapkan oleh firman-Nya yang lain, \"Aku dan rasul-rasul-Ku pasti menang.\" (Q.S. Al-Mujadilah, 21).",[["وَلَقَدْ","And verily"],["سَبَقَتْ","has preceded"],["كَلِمَتُنَا","Our Word"],["لِعِبَادِنَا","for Our slaves"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"3960":["Atau janji tersebut sebagaimana yang diungkapkan-Nya pada ayat berikut ini, yaitu, (yaitu, 'Sesungguhnya mereka itulah yang pasti mendapat pertolongan.')",[["إِنَّهُمْ","Indeed they"],["لَهُمُ","surely they"],["ٱلْمَنصُورُونَ","(would be) the victorious"]]],"3961":["(Dan sesungguhnya tentara Kami) yakni orang-orang mukmin (itulah yang pasti menang) atas orang-orang kafir melalui hujah, dan mendapat kemenangan atas mereka di dunia ini. Dan jika sebagian dari orang-orang yang beriman itu tidak mendapat kemenangan atas orang-orang kafir di dunia ini, maka mereka pasti mendapat kemenangan di akhirat nanti.",[["وَإِنَّ","And indeed"],["جُندَنَا","Our host"],["لَهُمُ","surely, they"],["ٱلْغَـٰلِبُونَ","(will be) those who overcome"]]],"3962":["(Maka berpalinglah kamu dari mereka) yaitu dari orang-orang kafir Mekah (sampai suatu ketika\") sampai Dia memerintahkannya untuk memerangi mereka.",[["فَتَوَلَّ","So turn away"],["عَنْهُمْ","from them"],["حَتَّىٰ","until"],["حِينٍۢ","a time"]]],"3963":["(Dan terangkanlah kepada mereka) apabila azab turun kepada mereka (maka kelak mereka akan mengetahui) akibat dari kekafiran mereka.",[["وَأَبْصِرْهُمْ","And see them"],["فَسَوْفَ","so soon"],["يُبْصِرُونَ","they will see"]]],"3964":["Maka mereka mengatakan dengan nada yang mengejek, \"Kapankah turunnya azab itu?\" Lalu Allah berfirman mengancam mereka yang mengatakan demikian: (Maka apakah mereka meminta supaya siksa Kami disegerakan.)",[["أَفَبِعَذَابِنَا","Then is (it) for Our punishment"],["يَسْتَعْجِلُونَ","they hasten"]]],"3965":["(Maka apabila siksaan itu turun di halaman mereka) maksudnya, di tengah-tengah mereka. Sehubungan dengan makna lafal As-Saahah ini Imam Al-Farra mengatakan, bahwa orang-orang Arab bila menyebutkan suatu kaum cukup hanya dengan menyebutkan halaman tempat mereka tinggal (maka amat buruklah) yakni seburuk-buruk pagi hari adalah (pagi hari yang dialami oleh orang-orang yang diperingatkan itu) di dalam ungkapan ayat ini terdapat Isim Zahir yang menduduki tempatnya Isim Mudhmar.",[["فَإِذَا","But when"],["نَزَلَ","it descends"],["بِسَاحَتِهِمْ","in their territory"],["فَسَآءَ","then evil (will be)"],["صَبَاحُ","(the) morning"],["ٱلْمُنذَرِينَ","(for) those who were warned"]]],"3966":["(Dan berpalinglah kamu dari mereka hingga suatu ketika.)",[["وَتَوَلَّ","So turn away"],["عَنْهُمْ","from them"],["حَتَّىٰ","for"],["حِينٍۢ","a time"]]],"3967":["(Dan lihatlah, karena mereka juga akan melihat) ayat ini diulangi penyebutannya dengan maksud untuk mengukuhkan ancaman yang ditujukan kepada mereka, dan sekaligus sebagai penenang hati bagi Nabi saw.",[["وَأَبْصِرْ","And see"],["فَسَوْفَ","so soon"],["يُبْصِرُونَ","they will see"]]],"3968":["(Maha Suci Rabbmu Yang mempunyai keperkasaan) yakni kemenangan (dari apa yang mereka katakan) yaitu, bahwa Dia memiliki anak.",[["سُبْحَـٰنَ","Glory"],["رَبِّكَ","(be to) your Lord"],["رَبِّ","(the) Lord"],["ٱلْعِزَّةِ","(of) Honor"],["عَمَّا","above what"],["يَصِفُونَ","they attribute"]]],"3969":["(Dan kesejahteraan dilimpahkan atas para rasul) yang menyampaikan ajaran tauhid dan syariat-syariat dari Allah swt.",[["وَسَلَـٰمٌ","And peace be"],["عَلَى","upon"],["ٱلْمُرْسَلِينَ","the Messengers"]]],"3970":["(Dan segala puji bagi Allah Tuhan seru sekalian alam) Yang menolong mereka dan yang membinasakan orang-orang yang kafir.",[["وَٱلْحَمْدُ","And all praise"],["لِلَّهِ","(be) to Allah"],["رَبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"3971":["(Shaad) hanya Allahlah yang mengetahui artinya (demi Alquran yang mempunyai keagungan) yakni penjelasan atau kemuliaan. Jawab dari qasamnya tidak disebutkan, yaitu, bahwa perkaranya tidak seperti apa yang dikatakan oleh orang-orang kafir Mekah, tuhan itu bermacam-macam.",[["صٓ ۚ","Saad"],["وَٱلْقُرْءَانِ","By the Quran"],["ذِى","full (of) reminder"],["ٱلذِّكْرِ","full (of) reminder"]]],"3972":["(Sebenarnya orang-orang kafir itu) yakni penduduk Mekah yang kafir (berada dalam kesombongan) hamiyyah dan takabbur tidak mau beriman (dan permusuhan yang sengit) selalu menentang dan memusuhi Nabi saw.",[["بَلِ","Nay"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["فِى","(are) in"],["عِزَّةٍۢ","self-glory"],["وَشِقَاقٍۢ","and opposition"]]],"3973":["(Berapa banyak) sudah berapa banyak (umat sebelum mereka yang telah Kami binasakan) yaitu dari kalangan umat-umat yang terdahulu, (lalu mereka meminta tolong) sewaktu azab menimpa mereka (padahal waktu itu bukanlah saat untuk lari melepaskan diri) artinya, untuk melarikan diri dari azab, karena segalanya sudah terlambat. Huruf Ta pada lafal Laata merupakan huruf Zaidah, dan jumlah kalimat ayat ini berkedudukan menjadi Hal atau kata keterangan keadaan dari Fa'ilnya lafal Naadau. Maksudnya, mereka meminta tolong padahal sudah tidak ada lagi jalan untuk melarikan diri, dan pula tidak ada lagi jalan untuk selamat dari azab. Akan tetapi penduduk Mekah yang kafir tidaklah mengambil pelajaran dari mereka yang telah dibinasakan itu.",[["كَمْ","How many"],["أَهْلَكْنَا","We destroyed"],["مِن","before them"],["قَبْلِهِم","before them"],["مِّن","of"],["قَرْنٍۢ","a generation"],["فَنَادَوا۟","then they called out"],["وَّلَاتَ","when there (was) no longer"],["حِينَ","time"],["مَنَاصٍۢ","(for) escape"]]],"3974":["(Dan mereka heran karena mereka kedatangan seorang pemberi peringatan dari kalangan mereka sendiri) yakni seorang Rasul dari kalangan mereka yang memberi peringatan dan mempertakuti mereka dengan azab neraka sesudah dibangkitkan nanti. Orang yang dimaksud adalah Nabi saw. (dan orang-orang kafir berkata,) di dalam ungkapan ini Isim Zhahir menduduki tempat Isim Mudhmar (\"Ini adalah seorang ahli sihir yang banyak berdusta.)",[["وَعَجِبُوٓا۟","And they wonder"],["أَن","that"],["جَآءَهُم","has come to them"],["مُّنذِرٌۭ","a warner"],["مِّنْهُمْ ۖ","from themselves"],["وَقَالَ","And said"],["ٱلْكَـٰفِرُونَ","the disbelievers"],["هَـٰذَا","This"],["سَـٰحِرٌۭ","(is) a magician"],["كَذَّابٌ","a liar"]]],"3975":["(Mengapa ia menjadikan tuhan-tuhan itu Tuhan yang satu saja?\") demikian itu karena Nabi saw. pernah bersabda kepada mereka, \"Katakanlah, 'Laa Ilaaha Illallaah', artinya tiada Tuhan selain Allah. Mereka menjawab, 'Mana mungkin makhluk yang sedemikian banyak itu, semuanya dapat ditangani oleh Tuhan Yang Satu itu.' (Sesungguhnya itu benar-benar suatu hal yang sangat mengherankan\") sangat aneh.",[["أَجَعَلَ","Has he made"],["ٱلْـَٔالِهَةَ","the gods"],["إِلَـٰهًۭا","(into) one god"],["وَٰحِدًا ۖ","(into) one god"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَشَىْءٌ","(is) certainly a thing"],["عُجَابٌۭ","curious"]]],"3976":["(Dan pergilah pemimpin-pemimpin mereka) dari majelis tempat mereka berkumpul, yaitu tempat Abu Thalib; di tempat itulah mereka mendengar dari Nabi saw. yang mengatakan, \"Katakanlah oleh kalian, 'Laa Ilaaha Illallaah', artinya tiada Tuhan selain Allah (seraya mengatakan, 'Pergilah kalian') maksudnya, sebagian dari mereka berkata kepada sebagian yang lain 'pergilah kalian' (dan tetaplah menyembah tuhan-tuhan kalian) artinya bertahanlah kalian di dalam menyembah tuhan-tuhan kalian itu (sesungguhnya ini) ajaran tauhid yang disampaikan Nabi itu (benar-benar suatu hal yang dikehendaki\") olehnya supaya kita melakukannya.",[["وَٱنطَلَقَ","And went forth"],["ٱلْمَلَأُ","the chiefs"],["مِنْهُمْ","among them"],["أَنِ","that"],["ٱمْشُوا۟","Continue"],["وَٱصْبِرُوا۟","and be patient"],["عَلَىٰٓ","over"],["ءَالِهَتِكُمْ ۖ","your gods"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَشَىْءٌۭ","(is) certainly a thing"],["يُرَادُ","intended"]]],"3977":["(Kami tidak pernah mendengar hal ini dalam agama yang terakhir) maksudnya, agama Nabi Isa. (Tiada lain) tidak lain (ini hanyalah dusta yang diada-adakan) hal yang dibuat-buat saja.",[["مَا","Not"],["سَمِعْنَا","we heard"],["بِهَـٰذَا","of this"],["فِى","in"],["ٱلْمِلَّةِ","the religion"],["ٱلْـَٔاخِرَةِ","the last"],["إِنْ","Not"],["هَـٰذَآ","(is) this"],["إِلَّا","but"],["ٱخْتِلَـٰقٌ","a fabrication"]]],"3978":["(Mengapa telah diturunkan) dapat dibaca Tahqiq dapat pula dibaca Tas-hil (kepadanya) kepada Muhammad (peringatan) yakni kitab Alquran (di antara kita?) bukan diturunkan kepada orang yang tertua di antara kita atau orang yang paling terhormat di antara kita. Maksudnya, mengapa Alquran itu tidak diturunkan kepada orang yang paling tua atau orang yang paling terhormat di antara mereka. Lalu Allah berfirman, (\"Sebenarnya mereka ragu terhadap Alquran-Ku) atau ragu terhadap wahyu-Ku, yaitu Alquran, karena mereka mendustakan rasul yang mendatangkannya (dan sebenarnya belumlah) artinya, belum lagi (mereka merasakan azab-Ku\") seandainya mereka telah merasakannya niscaya mereka mau beriman kepada Nabi saw. tentang apa yang disampaikan olehnya dari sisi-Ku. Akan tetapi pada saat itu, yakni saat mereka merasakan azab-Ku, tidak ada gunanya lagi iman.",[["أَءُنزِلَ","Has been revealed"],["عَلَيْهِ","to him"],["ٱلذِّكْرُ","the Message"],["مِنۢ","from"],["بَيْنِنَا ۚ","among us"],["بَلْ","Nay"],["هُمْ","They"],["فِى","(are) in"],["شَكٍّۢ","doubt"],["مِّن","about"],["ذِكْرِى ۖ","My Message"],["بَل","Nay"],["لَّمَّا","not yet"],["يَذُوقُوا۟","they have tasted"],["عَذَابِ","My punishment"]]],"3979":["(Atau apakah mereka itu mempunyai perbendaharaan rahmat Rabbmu Yang Maha Perkasa) yakni Maha Menang (lagi Maha Pemberi?) termasuk derajat kenabian dan hal-hal lainnya, karenanya mereka dapat memberikannya kepada siapa yang mereka kehendaki.",[["أَمْ","Or"],["عِندَهُمْ","have they"],["خَزَآئِنُ","(the) treasures"],["رَحْمَةِ","(of the) Mercy"],["رَبِّكَ","(of) your Lord"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْوَهَّابِ","the Bestower"]]],"3980":["(Atau apakah bagi mereka kerajaan langit dan bumi dan yang ada di antara keduanya?) jika mereka menduga hal tersebut (maka hendaklah mereka menaiki tangga-tangga) yang dapat mengantarkan mereka ke langit, lalu mereka mengambil wahyu dan mendatangkannya, kemudian mereka memberikannya secara khusus kepada orang-orang yang mereka kehendaki. Istifham atau kata tanya pada kedua tempat itu mengandung makna ingkar.",[["أَمْ","Or"],["لَهُم","for them"],["مُّلْكُ","(is the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا ۖ","(is) between them"],["فَلْيَرْتَقُوا۟","Then let them ascend"],["فِى","by"],["ٱلْأَسْبَـٰبِ","the means"]]],"3981":["(Suatu tentara) maksudnya, suatu pasukan yang hina (di sana) yang telah mendustakanmu (pasti dikalahkan) menjadi sifat bagi lafal Jundun, sekalipun mereka terdiri (dari golongan-golongan yang bersekutu) lafal ayat ini menjadi sifat pula bagi lafal Jundun. Yakni suatu pasukan yang sama dengan pasukan-pasukan yang berserikat sebelum kamu yang memerangi para nabi. Pasukan-pasukan dahulu itu dapat dikalahkan dan dibinasakan, maka demikian pula mereka yang bersekutu untuk menghancurkanmu akan Kami binasakan pula.",[["جُندٌۭ","Soldiers "],["مَّا","there"],["هُنَالِكَ","there"],["مَهْزُومٌۭ","(they will be) defeated"],["مِّنَ","among"],["ٱلْأَحْزَابِ","the companies"]]],"3982":["(Telah mendustakan pula sebelum mereka itu kaum Nuh) lafal Qaum dianggap sebagai muannats karena ditinjau dari segi maknanya (Ad dan Firaun yang mempunyai patok yang banyak) disebutkan bahwa Firaun selalu mematok atau memasung setiap orang yang menentangnya, lalu kedua kaki dan tangan orang yang menentangnya itu diikatkan pada empat patok, kemudian disiksa. Oleh karenanya ia dijuluki sebagai Dzul Autaad.",[["كَذَّبَتْ","Denied"],["قَبْلَهُمْ","before them"],["قَوْمُ","(the) people"],["نُوحٍۢ","(of) Nuh"],["وَعَادٌۭ","and Aad"],["وَفِرْعَوْنُ","and Firaun"],["ذُو","(the) owner"],["ٱلْأَوْتَادِ","(of) the stakes"]]],"3983":["(Dan Tsamud, kaum Luth dan penduduk Aikah) yakni penduduk kota Al-Ghidhah, mereka adalah kaum Nabi Syuaib a.s. (Mereka itulah golongan-golongan yang bersekutu menentang rasul-rasul).",[["وَثَمُودُ","And Thamud"],["وَقَوْمُ","and (the) people"],["لُوطٍۢ","(of) Lut"],["وَأَصْحَـٰبُ","and (the) companions"],["لْـَٔيْكَةِ ۚ","(of) the wood"],["أُو۟لَـٰٓئِكَ","Those"],["ٱلْأَحْزَابُ","(were) the companies"]]],"3984":["(Tidak lain) tiada lain (semuanya) artinya masing-masing dari golongan-golongan yang bersekutu itu (hanyalah mendustakan rasul-rasul) karena mereka telah mendustakan salah seorang dari rasul-rasul itu, ini berarti sama saja dengan mendustakan semua rasul-rasul, karena sesungguhnya seruan dan ajaran mereka satu, yaitu menyeru kepada ajaran tauhid (maka pastilah) wajiblah bagi mereka (azab-Ku).",[["إِن","Not"],["كُلٌّ","all (of them)"],["إِلَّا","but"],["كَذَّبَ","denied"],["ٱلرُّسُلَ","the Messengers"],["فَحَقَّ","so (was) just"],["عِقَابِ","My penalty"]]],"3985":["(Tiadalah yang ditunggu-tunggu) yang dinantikan (oleh mereka) oleh orang-orang kafir Mekah. (melainkan hanya satu teriakan) yaitu tiupan sangkakala untuk kiamat yang saat itu mereka ditimpa oleh azab (yang tidak ada bagi mereka saat berselang) maksudnya, sesudah itu tidak akan ada saat hidup kembali seperti di dunia. Lafal Fawaaqin dapat pula dibaca Fuwaaqin.",[["وَمَا","And not"],["يَنظُرُ","await"],["هَـٰٓؤُلَآءِ","these"],["إِلَّا","but"],["صَيْحَةًۭ","a shout"],["وَٰحِدَةًۭ","one"],["مَّا","not"],["لَهَا","for it"],["مِن","any"],["فَوَاقٍۢ","delay"]]],"3986":["(Dan mereka berkata) sewaktu Allah menurunkan firman-Nya, \"Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kanannya...\" (Q.S. Al-Haqqah, 19) (\"Ya Rabb kami! Segerakanlah untuk kami catatan amal kami) yakni kitab catatan amal kami (sebelum hari berhisab\") mereka mengatakan hal ini dengan nada yang sinis dan mengejek.",[["وَقَالُوا۟","And they say"],["رَبَّنَا","Our Lord"],["عَجِّل","Hasten"],["لَّنَا","for us"],["قِطَّنَا","our share"],["قَبْلَ","before"],["يَوْمِ","(the) Day"],["ٱلْحِسَابِ","(of) the Account"]]],"3987":["Allah swt. berfirman, (\"Bersabarlah atas segala apa yang mereka katakan; ingatlah hamba Kami Daud yang mempunyai kekuatan) dalam beribadah; tersebutlah bahwa dia sepanjang tahun selalu berpuasa sehari dan berbuka sehari; bangun pada tengah malam untuk melakukan salat, kemudian tidur selama sepertiga malam dan seperenam malam harinya lagi ia gunakan untuk salat (sesungguhnya dia amat taat) yakni selalu mengerjakan hal-hal yang menjadi keridaan Allah swt.",[["ٱصْبِرْ","Be patient"],["عَلَىٰ","over"],["مَا","what"],["يَقُولُونَ","they say"],["وَٱذْكُرْ","and remember"],["عَبْدَنَا","Our slave"],["دَاوُۥدَ","Dawood"],["ذَا","the possessor of strength"],["ٱلْأَيْدِ ۖ","the possessor of strength"],["إِنَّهُۥٓ","Indeed, he (was)"],["أَوَّابٌ","repeatedly turning"]]],"3988":["(Sesungguhnya Kami menundukkan gunung-gunung untuk bertasbih bersama dia di waktu petang) di waktu salat Isyak (dan pagi) di waktu salat Duha, yaitu di waktu matahari mencapai sepenggalah.",[["إِنَّا","Indeed, We"],["سَخَّرْنَا","subjected"],["ٱلْجِبَالَ","the mountains"],["مَعَهُۥ","with him"],["يُسَبِّحْنَ","glorifying"],["بِٱلْعَشِىِّ","in the evening"],["وَٱلْإِشْرَاقِ","and [the] sunrise"]]],"3989":["(Dan) Kami tundukkan pula (burung-burung dalam keadaan berkumpul) berkumpul untuk bertasbih bersama dengan dia. (Masing-masing) dari gunung-gunung dan burung-burung itu (amat taat kepada-Nya) taat bertasbih kepada-Nya.",[["وَٱلطَّيْرَ","And the birds"],["مَحْشُورَةًۭ ۖ","assembled"],["كُلٌّۭ","all"],["لَّهُۥٓ","with him"],["أَوَّابٌۭ","repeatedly turning"]]],"3990":["(Dan Kami kuatkan kerajaannya) Kami kuatkan kerajaannya itu dengan para penjaga dan bala tentara; dan setiap malam mihrab Nabi Daud selalu dijaga oleh tiga puluh ribu pasukan (dan Kami berikan, kepadanya hikmah) yakni, kenabian dan ketepatan dalam berbagai perkara (dan kebijaksanaan dalam menyelesaikan perselisihan\") yaitu penjelasan yang memuaskan dalam semua urusan.",[["وَشَدَدْنَا","And We strengthened"],["مُلْكَهُۥ","his kingdom"],["وَءَاتَيْنَـٰهُ","and We gave him"],["ٱلْحِكْمَةَ","[the] wisdom"],["وَفَصْلَ","and decisive"],["ٱلْخِطَابِ","speech"]]],"3991":["(Dan adakah) Istifham atau kata tanya di sini mengandung makna Ta'ajjub dan Tasywiq, atau dengan kata lain mengandung makna yang mendorong dan merangsang pendengar untuk mendengarkan kalimat-kalimat selanjutnya (sampai kepadamu) hai Muhammad (berita orang-orang yang berperkara ketika mereka memanjat pagar mihrab?) yaitu mihrab Nabi Daud, yang dimaksud adalah mesjidnya; demikian itu terjadi karena mereka dilarang masuk, sebab Nabi Daud sedang beribadah. Akhirnya mereka masuk dengan memanjat pagar mihrabnya. Makna ayat ialah apakah kamu telah mendengar berita dan kisah mereka?",[["۞ وَهَلْ","And has (there)"],["أَتَىٰكَ","come to you"],["نَبَؤُا۟","(the) news"],["ٱلْخَصْمِ","(of) the litigants"],["إِذْ","when"],["تَسَوَّرُوا۟","they climbed over the wall"],["ٱلْمِحْرَابَ","(of) the chamber"]]],"3992":["(Ketika mereka masuk menemui Daud lalu ia terkejut karena kedatangan mereka. Mereka berkata, \"Janganlah kamu merasa takut) kami (adalah dua orang yang bersengketa) menurut suatu pendapat dikatakan, bahwa yang bersengketa itu adalah dua golongan, demikian itu supaya sesuai dengan dhamir jamak yang sebelumnya. Menurut pendapat yang lain disebutkan bahwa orang yang bersengketa itu dua orang, sedangkan dhamir jamak diartikan dengannya. Lafal Al-Khashmu dapat diartikan untuk satu orang atau lebih. Kedua orang itu adalah dua malaikat yang menjelma menjadi dua orang yang sedang bersengketa. Persengketaan yang terjadi di antara keduanya hanyalah sebagai perumpamaan, dimaksud untuk mengingatkan Nabi Daud a.s. atas apa yang telah dilakukannya. Karena ia mempunyai istri sebanyak sembilan puluh sembilan orang wanita. Tetapi sekalipun demikian ia melamar istri orang lain yang hanya mempunyai seorang istri kemudian ia mengawininya dan menggaulinya (salah seorang dari kami berbuat zalim kepada yang lain, maka berilah keputusan antara kami dengan adil dan janganlah kamu menyimpang dari kebenaran) janganlah kamu berlaku berat sebelah (dan tunjukilah kami) bimbinglah kami (ke jalan yang lurus) yakni keputusan yang pertengahan dan adil.",[["إِذْ","When"],["دَخَلُوا۟","they entered"],["عَلَىٰ","upon"],["دَاوُۥدَ","Dawood"],["فَفَزِعَ","and he was afraid"],["مِنْهُمْ ۖ","of them"],["قَالُوا۟","they said"],["لَا","(Do) not"],["تَخَفْ ۖ","fear"],["خَصْمَانِ","(We are) two litigants"],["بَغَىٰ","has wronged"],["بَعْضُنَا","one of us"],["عَلَىٰ","to"],["بَعْضٍۢ","another"],["فَٱحْكُم","so judge"],["بَيْنَنَا","between us"],["بِٱلْحَقِّ","in truth"],["وَلَا","and (do) not"],["تُشْطِطْ","be unjust"],["وَٱهْدِنَآ","and guide us"],["إِلَىٰ","to"],["سَوَآءِ","an even"],["ٱلصِّرَٰطِ","[the] path"]]],"3993":["(Sesungguhnya saudaraku ini) maksudnya, saudara seagamaku ini (mempunyai sembilan puluh sembilan ekor kambing) ini sebagai kata kiasan dari istri (dan aku mempunyai seekor saja. Maka dia berkata, 'Serahkanlah kambing itu kepadaku) yakni jadikanlah aku sebagai suaminya (dan dia mengalahkan aku) atau dia menang atas diriku (dalam perdebatan'\") yakni dalam sengketa ini, dan lawannya pun mengalah.",[["إِنَّ","Indeed"],["هَـٰذَآ","this"],["أَخِى","(is) my brother"],["لَهُۥ","he has"],["تِسْعٌۭ","ninety-nine"],["وَتِسْعُونَ","ninety-nine"],["نَعْجَةًۭ","ewe(s)"],["وَلِىَ","while I have"],["نَعْجَةٌۭ","ewe"],["وَٰحِدَةٌۭ","one"],["فَقَالَ","so he said"],["أَكْفِلْنِيهَا","Entrust her to me"],["وَعَزَّنِى","and he overpowered me"],["فِى","in"],["ٱلْخِطَابِ","[the] speech"]]],"3994":["(Daud berkata, \"Sesungguhnya dia telah berbuat lalim kepadamu dengan meminta kambingmu itu) dengan maksud untuk menggabungkannya (untuk ditambahkan kepada kambingnya. Sesungguhnya kebanyakan dari orang-orang yang berserikat itu) yakni orang-orang yang terlibat dalam satu perserikatan (sebagian mereka berbuat lalim kepada sebagian yang lain, kecuali orang-orang yang beriman dan mengerjakan amal yang saleh; dan amat sedikitlah mereka ini\") huruf Ma di sini untuk mengukuhkan makna sedikit. Lalu kedua malaikat itu naik ke langit dalam keadaan berubah menjadi ujud aslinya seraya berkata, \"Lelaki ini telah memutuskan perkara terhadap dirinya sendiri.\" Sehingga sadarlah Nabi Daud atas kekeliruannya itu. Lalu Allah berfirman, (Dan Daud yakin) yakni merasa yakin (bahwa Kami mengujinya) Kami menimpakan ujian kepadanya, berupa cobaan dalam bentuk cinta kepada perempuan itu (maka ia meminta ampun kepada Rabbnya lalu menyungkur rukuk) maksudnya bersujud (dan bertobat.)",[["قَالَ","He said"],["لَقَدْ","Certainly"],["ظَلَمَكَ","he has wronged you"],["بِسُؤَالِ","by demanding"],["نَعْجَتِكَ","your ewe"],["إِلَىٰ","to"],["نِعَاجِهِۦ ۖ","his ewes"],["وَإِنَّ","And indeed"],["كَثِيرًۭا","many"],["مِّنَ","of"],["ٱلْخُلَطَآءِ","the partners"],["لَيَبْغِى","certainly oppress"],["بَعْضُهُمْ","some of them"],["عَلَىٰ","[on]"],["بَعْضٍ","another"],["إِلَّا","except"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["وَقَلِيلٌۭ","and few"],["مَّا","(are) they"],["هُمْ ۗ","(are) they"],["وَظَنَّ","And became certain"],["دَاوُۥدُ","Dawood"],["أَنَّمَا","that"],["فَتَنَّـٰهُ","We (had) tried him"],["فَٱسْتَغْفَرَ","and he asked forgiveness"],["رَبَّهُۥ","(of) his Lord"],["وَخَرَّ","and fell down"],["رَاكِعًۭا","bowing"],["وَأَنَابَ ۩","and turned in repentance"]]],"3995":["(Maka Kami ampuni baginya kesalahannya itu. Dan sesungguhnya dia mempunyai kedudukan dekat pada sisi Kami) yakni dengan ditambahkan kebaikan baginya di dunia (dan tempat kembali yang baik) kelak di akhirat.",[["فَغَفَرْنَا","So We forgave"],["لَهُۥ","for him"],["ذَٰلِكَ ۖ","that"],["وَإِنَّ","And indeed"],["لَهُۥ","for him"],["عِندَنَا","with Us"],["لَزُلْفَىٰ","surely is a near access"],["وَحُسْنَ","and a good"],["مَـَٔابٍۢ","place of return"]]],"3996":["(Hai Daud, sesungguhnya Kami menjadikan kamu khalifah penguasa di muka bumi) yaitu sebagai penguasa yang mengatur perkara manusia (maka berilah keputusan perkara di antara manusia dengan adil dan janganlah kamu mengikuti hawa nafsu) kemauan hawa nafsu (karena ia akan menyesatkan kamu dari jalan Allah) dari bukti-bukti yang menunjukkan keesaan-Nya. (Sesungguhnya orang-orang yang sesat dari jalan Allah) dari iman kepada Allah (mereka akan mendapat siksa yang berat karena mereka melupakan) artinya, disebabkan mereka lupa akan (hari perhitungan) hal ini ditunjukkan oleh sikap mereka yang tidak mau beriman, seandainya mereka beriman dengan adanya hari perhitungan itu, niscaya mereka akan beriman kepada Allah sewaktu mereka di dunia.",[["يَـٰدَاوُۥدُ","O Dawood"],["إِنَّا","Indeed, We"],["جَعَلْنَـٰكَ","[We] have made you"],["خَلِيفَةًۭ","a vicegerent"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَٱحْكُم","so judge"],["بَيْنَ","between"],["ٱلنَّاسِ","[the] men"],["بِٱلْحَقِّ","in truth"],["وَلَا","and (do) not"],["تَتَّبِعِ","follow"],["ٱلْهَوَىٰ","the desire"],["فَيُضِلَّكَ","for it will lead you astray"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۚ","(of) Allah"],["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَضِلُّونَ","go astray"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["لَهُمْ","for them"],["عَذَابٌۭ","(is) a punishment"],["شَدِيدٌۢ","severe"],["بِمَا","because"],["نَسُوا۟","they forgot"],["يَوْمَ","(the) Day"],["ٱلْحِسَابِ","(of) Account"]]],"3997":["(Dan Kami tidak menciptakan langit dan bumi dan apa yang ada di antara keduanya dengan batil) dengan main-main. (Yang demikian itu) yakni penciptaan hal tersebut tanpa hikmah (adalah anggapan orang-orang kafir) dari penduduk Mekah (maka neraka Waillah) Wail adalah nama sebuah lembah di neraka (bagi orang-orang yang kafir karena mereka akan masuk neraka.)",[["وَمَا","And not"],["خَلَقْنَا","We created"],["ٱلسَّمَآءَ","the heaven"],["وَٱلْأَرْضَ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا","(is) between them"],["بَـٰطِلًۭا ۚ","without purpose"],["ذَٰلِكَ","That"],["ظَنُّ","(is the) assumption"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟ ۚ","disbelieve"],["فَوَيْلٌۭ","So woe"],["لِّلَّذِينَ","to those"],["كَفَرُوا۟","who disbelieve"],["مِنَ","from"],["ٱلنَّارِ","the Fire"]]],"3998":["(Patutkah Kami menganggap orang-orang yang beriman dan mengerjakan amal yang saleh sama dengan orang-orang yang berbuat kerusakan di muka bumi? Patutkah pula Kami menganggap orang-orang yang bertakwa sama dengan orang-orang yang berbuat maksiat?) Ayat ini diturunkan sewaktu orang-orang kafir Mekah berkata kepada orang-orang yang beriman, \"Sesungguhnya kami kelak di hari kemudian akan diberi seperti apa yang diberikan kepada kalian.\" Lafal Am di sini untuk menunjukkan makna sanggahan, yakni jelas tidak sama.",[["أَمْ","Or"],["نَجْعَلُ","should We treat"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["كَٱلْمُفْسِدِينَ","like those who spread corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["أَمْ","Or"],["نَجْعَلُ","should We treat"],["ٱلْمُتَّقِينَ","the pious"],["كَٱلْفُجَّارِ","like the wicked"]]],"3999":["(Ini adalah sebuah Kitab) menjadi Khabar dari Mubtada yang tidak disebutkan, yakni, Ini adalah Kitab (yang Kami turunkan kepadamu penuh dengan berkah supaya mereka memperhatikan) asal lafal Yaddabbaruu adalah Yatadabbaruu, kemudian huruf Ta diidghamkan kepada huruf Dal sehingga jadilah Yaddabbaruu (ayat-ayatnya) maksudnya supaya mereka memperhatikan makna-makna yang terkandung di dalamnya, lalu mereka beriman karenanya (dan supaya mendapat pelajaran) mendapat nasihat (orang-orang yang mempunyai pikiran) yaitu yang berakal.",[["كِتَـٰبٌ","(This is) a Book"],["أَنزَلْنَـٰهُ","We have revealed it"],["إِلَيْكَ","to you"],["مُبَـٰرَكٌۭ","blessed"],["لِّيَدَّبَّرُوٓا۟","that they may ponder"],["ءَايَـٰتِهِۦ","(over) its Verses"],["وَلِيَتَذَكَّرَ","and may be reminded"],["أُو۟لُوا۟","those of understanding"],["ٱلْأَلْبَـٰبِ","those of understanding"]]],"4000":["(Dan Kami karuniakan kepada Daud, Sulaiman) sebagai anaknya (dia adalah sebaik-baik hamba) maksudnya Sulaiman adalah sebaik-baik hamba. (Sesungguhnya dia amat taat) kepada Rabbnya, selalu bertasbih dan berzikir pada semua waktunya.",[["وَوَهَبْنَا","And We gave"],["لِدَاوُۥدَ","to Dawood"],["سُلَيْمَـٰنَ ۚ","Sulaiman"],["نِعْمَ","an excellent"],["ٱلْعَبْدُ ۖ","slave"],["إِنَّهُۥٓ","Indeed, he"],["أَوَّابٌ","(was) one who repeatedly turned"]]],"4001":["(Ingatlah ketika dipertunjukkan kepadanya di waktu sore) yakni sesudah matahari tergelincir (kuda-kuda yang tenang di waktu berhenti) lafal Ash-Shaafinaat adalah bentuk jamak dari lafal Shaafinah, artinya kuda yang kalau berhenti berdiri pada tiga kaki, sedangkan kaki yang keempatnya berdiri pada ujung teracaknya atau berjinjit. Lafal ini berasal dari kata Shafana Yashfinu Shufuunan (dan cepat pada waktu berlari) lafal Al-Jiyaad adalah bentuk jamak dari lafal Jawaadun, artinya kuda balap. Maksud ayat, bahwa kuda-kuda itu bila berhenti tenang, dan bila berlari sangat cepat. Tersebutlah bahwa Nabi Sulaiman memiliki seribu ekor kuda, kuda-kuda itu ditampilkan di hadapannya setelah ia selesai melakukan salat Zuhur, karena ia bermaksud untuk berjihad dengan memakai kuda sebagai kendaraannya untuk melawan musuh. Sewaktu penampilan kuda baru sampai sembilan ratus ekor ternyata waktu Magrib telah tiba, sedangkan ia belum melakukan salat asar. Hal ini membuatnya berduka cita.",[["إِذْ","When"],["عُرِضَ","were displayed"],["عَلَيْهِ","to him"],["بِٱلْعَشِىِّ","in the afternoon"],["ٱلصَّـٰفِنَـٰتُ","excellent bred steeds"],["ٱلْجِيَادُ","excellent bred steeds"]]],"4002":["(Maka ia berkata, \"Sesungguhnya aku menyukai) artinya, mempunyai maksud (bersenang-senang terhadap barang yang baik) yakni kuda (hingga aku lupa untuk berzikir kepada Rabbku) lupa melakukan salat asar (sehingga tertutuplah) matahari (dari pandangan mata.\") artinya sehingga matahari itu tenggelam dan tidak kelihatan lagi.",[["فَقَالَ","And he said"],["إِنِّىٓ","Indeed, I"],["أَحْبَبْتُ","[I] preferred"],["حُبَّ","(the) love"],["ٱلْخَيْرِ","(of) the good"],["عَن","over"],["ذِكْرِ","(the) remembrance"],["رَبِّى","(of) my Lord"],["حَتَّىٰ","Until"],["تَوَارَتْ","they were hidden"],["بِٱلْحِجَابِ","in the veil"]]],"4003":["(Ia berkata, \"Bawalah kuda-kuda itu kembali kepadaku\") yaitu kuda-kuda yang ditampilkan tadi kemudian mereka membawanya kepada Nabi Sulaiman (lalu ia membabat kuda-kuda itu) dengan pedangnya (pada kaki-kakinya) lafal As-Suuq ini adalah bentuk jamak dari lafal Saaqun (dan pada lehernya) artinya Nabi Sulaiman menyembelih semua kuda-kuda itu kemudian memotong kakinya sebagai kurban untuk mendekatkan diri kepada Allah swt. Karena kuda-kuda itu ternyata membuatnya lalai dari salat; kemudian ia menyedekahkan daging-dagingnya. Akhirnya Allah menggantikan kudanya dengan kendaraan yang jauh lebih baik dan lebih cepat larinya, yaitu kendaraan angin; angin dapat diperintah untuk bertiup dengan membawanya ke mana saja yang ia kehendaki.",[["رُدُّوهَا","Return them"],["عَلَىَّ ۖ","to me"],["فَطَفِقَ","Then he began"],["مَسْحًۢا","(to) pass (his hand)"],["بِٱلسُّوقِ","over the legs"],["وَٱلْأَعْنَاقِ","and the necks"]]],"4004":["(Dan sesungguhnya Kami telah menguji Sulaiman) Kami telah mencobanya dengan suatu ujian, yaitu kerajaannya dirampas oleh orang lain. Demikian itu, karena ia pernah menikahi seorang perempuan yang ia sukai, hanya perempuan itu termasuk orang yang menyembah berhala, tanpa sepengetahuan Nabi Sulaiman. Dan tersebutlah bahwa kebesarannya itu terletak pada cincinnya kemudian pada suatu hari ketika ia bermaksud untuk pergi ke kamar mandi, ia melepaskan cincinnya itu. Lalu ia menitipkannya kepada salah seorang dari istrinya yang bernama Aminah, sebagaimana biasanya. Setelah ia pergi tiba-tiba datanglah makhluk jin yang menyerupai Nabi Sulaiman, kemudian jin itu mengambil cincin itu dari Aminah dan langsung memakainya (dan Kami dudukkan pada singgasananya sesosok jasad) yaitu jin tersebut, yang bernama Shakhr atau jin lainnya, kemudian jin itu menduduki singgasana Nabi Sulaiman. Ketika itu juga ia dikelilingi burung-burung dan lain-lainnya. Lalu muncullah Nabi Sulaiman dalam bentuk yang tidak seperti biasanya, yakni tanpa pakaian kebesaran, ia melihat bahwa di singgasananya telah duduk seseorang. Kemudian ia berkata kepada orang-orang yang ada di situ, \"Aku adalah Sulaiman.\" Akan tetapi orang-orang mengingkarinya (kemudian ia kembali) yakni kembali dapat merebut kebesarannya setelah selang beberapa hari; yaitu setelah ia berhasil merebut cincin kebesarannya, lalu memakainya dan duduk di atas singgasananya kembali.",[["وَلَقَدْ","And certainly"],["فَتَنَّا","We tried"],["سُلَيْمَـٰنَ","Sulaiman"],["وَأَلْقَيْنَا","and We placed"],["عَلَىٰ","on"],["كُرْسِيِّهِۦ","his throne"],["جَسَدًۭا","a body"],["ثُمَّ","then"],["أَنَابَ","he turned"]]],"4005":["(Ia berkata, \"Ya Rabbku! Ampunilah aku dan anugerahkanlah kepadaku kerajaan yang tidak patut dimiliki) maksudnya, belum pernah dimiliki (oleh seorang jua pun sesudahku) artinya, yang tidak layak dimiliki oleh orang selainku. Pengertian ungkapan ini sama dengan makna yang terkandung di dalam firman-Nya yang lain, yaitu, 'Maka siapakah yang akan memberinya petunjuk sesudah Allah?' (Q.S. Al-Jatsiyah, 23) yakni selain Allah (sesungguhnya Engkaulah Yang Maha Pemberi.\")",[["قَالَ","He said"],["رَبِّ","O my Lord"],["ٱغْفِرْ","Forgive"],["لِى","me"],["وَهَبْ","and grant"],["لِى","me"],["مُلْكًۭا","a kingdom"],["لَّا","not"],["يَنۢبَغِى","(will) belong"],["لِأَحَدٍۢ","to anyone"],["مِّنۢ","after me"],["بَعْدِىٓ ۖ","after me"],["إِنَّكَ","Indeed, You"],["أَنتَ","[You]"],["ٱلْوَهَّابُ","(are) the Bestower"]]],"4006":["(Kemudian Kami tundukkan kepadanya angin yang berembus dengan baik menurut perintahnya) yakni berembus dengan lembut (ke mana saja yang ia kehendaki) sesuai dengan keinginan Nabi Sulaiman.",[["فَسَخَّرْنَا","Then We subjected"],["لَهُ","to him"],["ٱلرِّيحَ","the wind"],["تَجْرِى","to flow"],["بِأَمْرِهِۦ","by his command"],["رُخَآءً","gently"],["حَيْثُ","wherever"],["أَصَابَ","he directed"]]],"4007":["(Dan Kami tundukkan pula kepadanya setan-setan, semuanya ahli bangunan) yakni pandai membuat bangunan-bangunan yang menakjubkan dan aneh (dan penyelam) ahli menyelam di dalam laut untuk mengambil mutiara-mutiara yang terkandung di dalamnya.",[["وَٱلشَّيَـٰطِينَ","And the devils"],["كُلَّ","every"],["بَنَّآءٍۢ","builder"],["وَغَوَّاصٍۢ","and diver"]]],"4008":["(Dan setan yang lain) setan-setan yang lainnya (yang terikat) dirantai (dalam belenggu) yaitu, tangan mereka masing-masing diikatkan ke kepalanya dengan memakai belenggu.",[["وَءَاخَرِينَ","And others"],["مُقَرَّنِينَ","bound"],["فِى","in"],["ٱلْأَصْفَادِ","chains"]]],"4009":["Dan Kami berfirman kepada Sulaiman (Inilah anugerah Kami; maka berikanlah) maksudnya, berikanlah sebagian daripadanya kepada orang yang kamu sukai (atau tahanlah) maksudnya, tidak memberikannya (dengan tiada pertanggungjawaban) tanpa ada hisab bagimu dalam hal ini.",[["هَـٰذَا","This"],["عَطَآؤُنَا","(is) Our gift"],["فَٱمْنُنْ","so grant"],["أَوْ","or"],["أَمْسِكْ","withhold"],["بِغَيْرِ","without"],["حِسَابٍۢ","account"]]],"4010":["(Dan sesungguhnya dia mempunyai kedudukan yang dekat pada sisi Kami dan tempat kembali yang baik) penafsiran ayat ini sebagaimana yang telah lalu.",[["وَإِنَّ","And indeed"],["لَهُۥ","for him"],["عِندَنَا","with Us"],["لَزُلْفَىٰ","surely is a near access"],["وَحُسْنَ","and a good"],["مَـَٔابٍۢ","place of return"]]],"4011":["(Dan ingatlah akan hamba Kami Ayub ketika ia menyeru Rabbnya, \"Sesungguhnya aku) bahwasanya aku (diganggu oleh setan dengan kepayahan) kemudaratan (dan siksaan\") yakni rasa sakit. Nabi Ayub menisbatkan atau mengaitkan hal tersebut kepada setan, sekalipun pada kenyataannya segala sesuatu itu berasal dari Allah swt. Dimaksud sebagai sopan santun Nabi Ayub terhadap Allah.",[["وَٱذْكُرْ","And remember"],["عَبْدَنَآ","Our slave"],["أَيُّوبَ","Ayyub"],["إِذْ","when"],["نَادَىٰ","he called"],["رَبَّهُۥٓ","his Lord"],["أَنِّى","That [I]"],["مَسَّنِىَ","(has) touched me"],["ٱلشَّيْطَـٰنُ","Shaitaan"],["بِنُصْبٍۢ","with distress"],["وَعَذَابٍ","and suffering"]]],"4012":["Dikatakan kepada Ayub (\"Hantamkanlah) maksudnya hentakkanlah (kakimu) ke bumi, lalu ia menghantamkannya, setelah itu tiba-tiba mengalirlah mata air dari bekas hentakan kakinya. Kemudian dikatakan pula kepadanya (inilah air untuk mandi) artinya, mandilah kamu dengan air ini (yang dingin, dan untuk minum\") minumlah kamu daripadanya. Segeralah Nabi Ayub mandi dan minum dan hilanglah semua penyakit yang ada di dalam dan di luar tubuhnya.",[["ٱرْكُضْ","Strike"],["بِرِجْلِكَ ۖ","with your foot"],["هَـٰذَا","This"],["مُغْتَسَلٌۢ","(is a spring of) water to bathe"],["بَارِدٌۭ","cool"],["وَشَرَابٌۭ","and a drink"]]],"4013":["(Dan Kami anugerahi dia dengan mengumpulkan kembali keluarganya dan Kami tambahkan kepada mereka sebanyak mereka) maksudnya, Allah menghidupkan kembali anak-anaknya yang telah mati itu, dan menambah pula kepadanya anak lain sejumlah anak yang telah mati itu (sebagai rahmat) sebagai nikmat dan karunia (dari Kami dan pelajaran) nasihat (bagi orang-orang yang mempunyai pikiran) yaitu bagi orang-orang yang berakal.",[["وَوَهَبْنَا","And We granted"],["لَهُۥٓ","[to] him"],["أَهْلَهُۥ","his family"],["وَمِثْلَهُم","and a like of them"],["مَّعَهُمْ","with them"],["رَحْمَةًۭ","a Mercy"],["مِّنَّا","from Us"],["وَذِكْرَىٰ","and a Reminder"],["لِأُو۟لِى","for those of understanding"],["ٱلْأَلْبَـٰبِ","for those of understanding"]]],"4014":["(Dan ambillah dengan tanganmu seikat rumput) yakni seikat rumput lalang atau seikat ranting-ranting (maka pukullah dengan itu) istrimu, karena Nabi Ayub pernah bersumpah, bahwa ia sungguh akan memukul istrinya sebanyak seratus kali deraan, karena pada suatu hari ia pernah tidak menuruti perintahnya (dan janganlah kamu melanggar sumpah) dengan tidak memukulnya, lalu Nabi Ayub mengambil seratus tangkai kayu Idzkhir atau kayu lainnya, lalu ia memukulkannya sekali pukul kepada istrinya. (Sesungguhnya Kami dapati dia seorang yang sabar. Dialah sebaik-baik hamba) adalah Nabi Ayub. (Sesungguhnya dia amat taat) kepada Allah swt.",[["وَخُذْ","And take"],["بِيَدِكَ","in your hand"],["ضِغْثًۭا","a bunch"],["فَٱضْرِب","and strike"],["بِّهِۦ","with it"],["وَلَا","and (do) not"],["تَحْنَثْ ۗ","break (your) oath"],["إِنَّا","Indeed, We"],["وَجَدْنَـٰهُ","[We] found him"],["صَابِرًۭا ۚ","patient"],["نِّعْمَ","an excellent"],["ٱلْعَبْدُ ۖ","slave"],["إِنَّهُۥٓ","Indeed, he"],["أَوَّابٌۭ","repeatedly turned"]]],"4015":["(Dan ingatlah hamba-hamba Kami; Ibrahim, Ishak dan Yakub yang mempunyai kekuatan) dalam hal beribadah (dan pandangan) yang tajam dalam masalah agama. Menurut suatu qiraat lafal 'Ibaadanaa dibaca 'Abdanaa dalam bentuk Mufrad, sedangkan lafal Ibrahiim merupakan Athaf Bayan baginya, dan lafal-lafal yang sesudahnya diathafkan kepada lafal 'Abdanaa.",[["وَٱذْكُرْ","And remember"],["عِبَـٰدَنَآ","Our slaves"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْحَـٰقَ","and Isaac"],["وَيَعْقُوبَ","and Ayyub"],["أُو۟لِى","possessors"],["ٱلْأَيْدِى","(of) strength"],["وَٱلْأَبْصَـٰرِ","and vision"]]],"4016":["(Sesungguhnya Kami telah menyucikan mereka dengan menganugerahkan kepada mereka akhlak yang tinggi) yaitu (selalu mengingatkan manusia kepada negeri akhirat) atau alam akhirat; maksudnya mengingatkan manusia kepada hari akhirat dan menganjurkan mereka untuk beramal baik sebagai bekal untuk menghadapinya. Menurut suatu qiraat dibaca Bikhaalishati Dzikrad Daar yaitu dengan dimudhafkan untuk menunjukkan makna Bayan, atau keterangan.",[["إِنَّآ","Indeed, We"],["أَخْلَصْنَـٰهُم","[We] chose them"],["بِخَالِصَةٍۢ","for an exclusive (quality)"],["ذِكْرَى","remembrance"],["ٱلدَّارِ","(of) the Home"]]],"4017":["(Dan sesungguhnya mereka pada sisi Kami benar-benar termasuk orang-orang pilihan) yakni orang-orang yang terpilih (yang paling baik) lafal Al-Akhyaar ini adalah bentuk jamak dari lafal Khayyirun, artinya paling baik.",[["وَإِنَّهُمْ","And indeed, they"],["عِندَنَا","to Us"],["لَمِنَ","(are) from"],["ٱلْمُصْطَفَيْنَ","the chosen ones"],["ٱلْأَخْيَارِ","the best"]]],"4018":["(Dan ingatlah akan Ismail, Ilyasa') Ilyasa' adalah Yasu', dia seorang nabi; Huruf Alif dan lamnya adalah Zaidah atau tambahan (dan Zulkifli) yang masih diperselisihkan kenabiannya. Menurut suatu pendapat dikatakan, bahwa ia pernah menjamin seratus orang nabi yang berlindung kepadanya untuk menghindari pembunuhan. (Semuanya) artinya, masing-masing dari kesemuanya (termasuk orang-orang yang paling baik) lafal Al-Akhyaar adalah bentuk jamak dari lafal Khayyirun, artinya orang yang paling baik.",[["وَٱذْكُرْ","And remember"],["إِسْمَـٰعِيلَ","Ishmael"],["وَٱلْيَسَعَ","and Elisha"],["وَذَا","and Dhul-kifl"],["ٱلْكِفْلِ ۖ","and Dhul-kifl"],["وَكُلٌّۭ","and all"],["مِّنَ","(are) from"],["ٱلْأَخْيَارِ","the best"]]],"4019":["(Ini adalah kehormatan) bagi mereka, yaitu mendapat pujian yang baik di sini. (Dan sesungguhnya bagi orang-orang yang bertakwa) antara lain adalah termasuk mereka (benar-benar disediakan tempat kembali yang baik) nanti di akhirat.",[["هَـٰذَا","This"],["ذِكْرٌۭ ۚ","(is) a Reminder"],["وَإِنَّ","And indeed"],["لِلْمُتَّقِينَ","for the righteous"],["لَحُسْنَ","surely, is a good"],["مَـَٔابٍۢ","place of return"]]],"4020":["(Yaitu surga Adn) menjadi Badal atau 'Athaf Bayan bagi lafal Lahusna Ma-aab (yang pintu-pintunya terbuka bagi mereka) artinya, pintu-pintu surga itu terbuka lebar-lebar buat mereka.",[["جَنَّـٰتِ","Gardens"],["عَدْنٍۢ","(of) Eternity"],["مُّفَتَّحَةًۭ","(will be) opened"],["لَّهُمُ","for them"],["ٱلْأَبْوَٰبُ","the gates"]]],"4021":["(Di dalamnya mereka bertelekan) di atas dipan-dipan (sambil meminta buah-buahan yang banyak dan minuman di surga itu.)",[["مُتَّكِـِٔينَ","Reclining"],["فِيهَا","therein"],["يَدْعُونَ","they will call"],["فِيهَا","therein"],["بِفَـٰكِهَةٍۢ","for fruit"],["كَثِيرَةٍۢ","many"],["وَشَرَابٍۢ","and drink"]]],"4022":["(Dan pada sisi mereka ada bidadari-bidadari yang tidak liar pandangannya) yakni mereka hanya memandang kepada suaminya dan menundukkan pandangan mata dari yang lainnya (dan sebaya umurnya) umur mereka sebaya, yaitu sekitar tiga puluh tiga tahunan. Lafal Atraabun adalah bentuk jamak dari lafal Turbun.",[["۞ وَعِندَهُمْ","And with them"],["قَـٰصِرَٰتُ","(will be) companions of modest gaze"],["ٱلطَّرْفِ","(will be) companions of modest gaze"],["أَتْرَابٌ","well-matched"]]],"4023":["(Inilah) hal-hal yang telah disebutkan itu (apa yang dijanjikan kepada kalian) dapat dibaca Yuu'aduuna atau Tuu'aduuna, kalau dibaca Tuu'aduna berarti Iltifat (pada hari berhisab) pada saat hari berhisab.",[["هَـٰذَا","This"],["مَا","(is) what"],["تُوعَدُونَ","you are promised"],["لِيَوْمِ","for (the) Day"],["ٱلْحِسَابِ","(of) Account"]]],"4024":["(Sesungguhnya ini adalah benar-benar rezeki dari Kami yang tiada habis-habisnya) yang tak putus-putusnya; jumlah ayat ini menjadi Haal dari lafal Larizqunaa, atau sebagai Khabar kedua dari Inna, artinya selama-lamanya.",[["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَرِزْقُنَا","(is) surely Our provision"],["مَا","not"],["لَهُۥ","for it"],["مِن","any"],["نَّفَادٍ","depletion"]]],"4025":["(Beginilah) keadaan yang dialami oleh orang-orang yang beriman. (Dan sesungguhnya bagi orang-orang yang durhaka) kalimat ayat ini merupakan jumlah Isti'naf atau kalimat baru (benar-benar disediakan tempat kembali yang paling buruk.)",[["هَـٰذَا ۚ","This (is so)"],["وَإِنَّ","And indeed"],["لِلطَّـٰغِينَ","for the transgressors"],["لَشَرَّ","surely (is) an evil"],["مَـَٔابٍۢ","place of return"]]],"4026":["(Yaitu neraka Jahanam, yang mereka masuk ke dalamnya) mereka dimasukkan ke dalamnya (maka amat buruklah Jahanam itu sebagai tempat tinggal) artinya, hamparan yang paling buruk.",[["جَهَنَّمَ","Hell"],["يَصْلَوْنَهَا","they will burn therein"],["فَبِئْسَ","and wretched (is)"],["ٱلْمِهَادُ","the resting place"]]],"4027":["(Inilah) azab neraka; pengertian ini disimpulkan dari lafal sesudahnya (biarlah mereka merasakannya, minuman mereka air yang sangat panas) lagi membakar (dan nanah ahli neraka) dapat dibaca Ghassaaqun atau Ghasaaqun artinya nanah yang meleleh dari penghuni neraka.",[["هَـٰذَا","This (is so)"],["فَلْيَذُوقُوهُ","Then let them taste it"],["حَمِيمٌۭ","boiling fluid"],["وَغَسَّاقٌۭ","and purulence"]]],"4028":["(Dan azab yang lain) dapat dibaca dalam bentuk jamak sehingga menjadi Ukharu atau dapat pula dibaca dalam bentuk Mufrad sehingga bacaannya menjadi Aakharu (yang serupa itu) serupa dengan azab yang telah disebutkan tadi, yaitu air yang sangat panas dan cairan nanah (berbagai macam) beraneka ragam siksaan, maksudnya, azab mereka bermacam-macam.",[["وَءَاخَرُ","And other"],["مِن","of"],["شَكْلِهِۦٓ","its type"],["أَزْوَٰجٌ","(of various) kinds"]]],"4029":["Dan dikatakan kepada mereka sewaktu mereka diseret ke dalam neraka bersama dengan para pengikutnya (\"Ini adalah suatu rombongan) suatu gelombang (yang masuk berdesak-desak) dijejalkan masuk (bersama kalian\") ke neraka. Kalimat itu dikatakan kepada mereka dengan nada yang keras; maka berkatalah pemimpin-pemimpin mereka yang durhaka, (\"Tiadalah ucapan selamat datang kepada mereka) artinya, tiada kelapangan buat mereka (karena sesungguhnya mereka akan masuk neraka.\")",[["هَـٰذَا","This"],["فَوْجٌۭ","(is) a company"],["مُّقْتَحِمٌۭ","bursting"],["مَّعَكُمْ ۖ","(in) with you"],["لَا","No"],["مَرْحَبًۢا","welcome"],["بِهِمْ ۚ","for them"],["إِنَّهُمْ","Indeed, they"],["صَالُوا۟","(will) burn"],["ٱلنَّارِ","(in) the Fire"]]],"4030":["(Pengikut-pengikut mereka berkata) atau mengatakan, (\"Sebenarnya kalianlah; tiada ucapan selamat datang bagi kalian, karena kalianlah yang menjerumuskan kami) ke dalam kekafiran (maka amat buruklah tempat tinggal\") bagi kami dan kalian, yaitu neraka.",[["قَالُوا۟","They say"],["بَلْ","Nay"],["أَنتُمْ","You "],["لَا","no"],["مَرْحَبًۢا","welcome"],["بِكُمْ ۖ","for you"],["أَنتُمْ","You"],["قَدَّمْتُمُوهُ","brought this"],["لَنَا ۖ","upon us"],["فَبِئْسَ","So wretched (is)"],["ٱلْقَرَارُ","the settlement"]]],"4031":["(Mereka berkata) lagi, (\"Ya Rabb kami! Barang siapa yang menjerumuskan kami ke dalam azab ini, maka tambahkanlah azab kepadanya dengan berlipat ganda) dua kali lipat azab yang diterimanya, sebagai balasan dari kekafirannya (di dalam neraka.\")",[["قَالُوا۟","They will say"],["رَبَّنَا","Our Lord"],["مَن","whoever"],["قَدَّمَ","brought"],["لَنَا","upon us"],["هَـٰذَا","this"],["فَزِدْهُ","increase for him"],["عَذَابًۭا","a punishment"],["ضِعْفًۭا","double"],["فِى","in"],["ٱلنَّارِ","the Fire"]]],"4032":["(Dan mereka berkata,) yakni orang-orang kafir Mekah, sedang mereka berada dalam neraka, (\"Mengapa kami tidak melihat orang-orang yang dahulu kami anggap) sewaktu di dunia (sebagai orang-orang yang hina.\")",[["وَقَالُوا۟","And they (will) say"],["مَا","What (is)"],["لَنَا","for us"],["لَا","not"],["نَرَىٰ","we see"],["رِجَالًۭا","men"],["كُنَّا","we used to"],["نَعُدُّهُم","count them"],["مِّنَ","among"],["ٱلْأَشْرَارِ","the bad ones"]]],"4033":["(Apakah kami dahulu menjadikan mereka olok-olokan) lafal Sukhriyyan dapat pula dibaca Sikhriyyan, yakni kami dahulu sewaktu di dunia menghina mereka. Huruf Ya pada lafal Sukhriyyan adalah Nasab; maksudnya apakah mereka tidak ada (ataukah karena tidak melihat) yakni terhalang (mata kami dari melihat mereka) sehingga mata kami tidak dapat melihat mereka. Yang mereka maksud adalah kaum muslimin yang miskin, seperti Ammar, Bilal, Shuhaib, dan Salman.",[["أَتَّخَذْنَـٰهُمْ","Did we take them"],["سِخْرِيًّا","(in) ridicule"],["أَمْ","or"],["زَاغَتْ","has turned away"],["عَنْهُمُ","from them"],["ٱلْأَبْصَـٰرُ","the vision"]]],"4034":["(Sesungguhnya yang demikian itu pasti terjadi) sudah pasti terjadinya, yaitu (pertengkaran penghuni neraka) sebagaimana yang telah dijelaskan tadi.",[["إِنَّ","Indeed"],["ذَٰلِكَ","that"],["لَحَقٌّۭ","(is) surely (the) truth "],["تَخَاصُمُ","(the) quarreling"],["أَهْلِ","(of the) people"],["ٱلنَّارِ","(of) the Fire"]]],"4035":["(Katakanlah) hai Muhammad kepada orang-orang kafir Mekah! (\"Sesungguhnya aku hanya seorang pemberi peringatan) seorang yang memperingatkan kalian dengan neraka (dan sekali-kali tidak ada Tuhan selain Allah Yang Maha Esa lagi Maha Mengalahkan) semua makhluk-Nya.",[["قُلْ","Say"],["إِنَّمَآ","Only"],["أَنَا۠","I am"],["مُنذِرٌۭ ۖ","a warner"],["وَمَا","and not"],["مِنْ","(is there) any"],["إِلَـٰهٍ","god"],["إِلَّا","except"],["ٱللَّهُ","Allah"],["ٱلْوَٰحِدُ","the One"],["ٱلْقَهَّارُ","the Irresistible"]]],"4036":["(Rabb langit dan bumi dan apa yang ada di antara keduanya Yang Maha Perkasa) yakni Maha Menang atas semua perkara-Nya (lagi Maha Pengampun\") terhadap kekasih-kekasih-Nya.",[["رَبُّ","Lord"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا","(is) between them"],["ٱلْعَزِيزُ","the All-Mighty"],["ٱلْغَفَّـٰرُ","the Oft-Forgiving"]]],"4037":["(Katakanlah) kepada mereka! (\"Berita itu adalah berita besar.)",[["قُلْ","Say"],["هُوَ","It (is)"],["نَبَؤٌا۟","a news"],["عَظِيمٌ","great"]]],"4038":["(Yang kalian berpaling darinya) dari Alquran yang aku beritakan dan aku datangkan kepada kalian; di dalamnya terdapat hal-hal yang tidak dapat diketahui, melainkan hanya dengan jalan wahyu. Yang dimaksud dengan berita yang besar itu ialah:",[["أَنتُمْ","You"],["عَنْهُ","from it"],["مُعْرِضُونَ","turn away"]]],"4039":["(Aku tiada mempunyai pengetahuan sedikit pun tentang Al-Mala'ul A'la) yakni para malaikat itu (ketika mereka berbantah-bantahan) tentang perihal Nabi Adam, ketika Allah berfirman, 'Sesungguhnya Aku hendak menjadikan seorang khalifah di muka bumi...' (Q.S. Al-Baqarah, 30)",[["مَا","Not"],["كَانَ","is"],["لِىَ","for me"],["مِنْ","any"],["عِلْمٍۭ","knowledge"],["بِٱلْمَلَإِ","(of) the chiefs"],["ٱلْأَعْلَىٰٓ","the exalted"],["إِذْ","when"],["يَخْتَصِمُونَ","they were disputing"]]],"4040":["(Tidak) tiada (diwahyukan kepadaku, melainkan bahwa sesungguhnya aku) yakni aku ini (hanyalah seorang pemberi peringatan yang nyata\") artinya nyata peringatannya.",[["إِن","Not"],["يُوحَىٰٓ","has been revealed"],["إِلَىَّ","to me"],["إِلَّآ","except"],["أَنَّمَآ","that only"],["أَنَا۠","I am"],["نَذِيرٌۭ","a warner"],["مُّبِينٌ","clear"]]],"4041":["Ingatlah (ketika Rabbmu berfirman kepada malaikat, \"Sesungguhnya Aku akan menciptakan manusia dari tanah) yaitu Adam.",[["إِذْ","When"],["قَالَ","said"],["رَبُّكَ","your Lord"],["لِلْمَلَـٰٓئِكَةِ","to the Angels"],["إِنِّى","Indeed, I Am"],["خَـٰلِقٌۢ","going to create"],["بَشَرًۭا","a human being"],["مِّن","from"],["طِينٍۢ","clay"]]],"4042":["(Maka apabila telah Kusempurnakan kejadiannya) telah sempurna kejadiannya (dan Kutiupkan) Kualirkan (kepadanya roh ciptaan-Ku) sehingga ia menjadi hidup. Dimudhafkannya lafal ruh kepada Allah dimaksud untuk memuliakan Nabi Adam. Roh adalah tubuh yang lembut dan tidak kelihatan oleh mata, yang membuat manusia dapat hidup karena memasuki tubuhnya (maka hendaklah kalian bersungkur dengan sujud kepadanya\") sujud penghormatan dengan cara membungkukkan badan.",[["فَإِذَا","So when"],["سَوَّيْتُهُۥ","I have proportioned him"],["وَنَفَخْتُ","and breathed"],["فِيهِ","into him"],["مِن","of"],["رُّوحِى","My spirit"],["فَقَعُوا۟","then fall down"],["لَهُۥ","to him"],["سَـٰجِدِينَ","prostrating"]]],"4043":["(Lalu seluruh malaikat itu sujud semuanya) di dalam ayat ini terdapat dua Taukid, yaitu lafal Kulluhum dan lafal Ajma 'uuna.",[["فَسَجَدَ","So prostrated"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["كُلُّهُمْ","all of them"],["أَجْمَعُونَ","together"]]],"4044":["(Kecuali iblis) dia adalah bapaknya jin yang dahulunya campur bersama dengan malaikat (dia menyombongkan diri dan adalah dia termasuk orang-orang yang kafir) menurut ilmu Allah.",[["إِلَّآ","Except"],["إِبْلِيسَ","Iblis"],["ٱسْتَكْبَرَ","he was arrogant"],["وَكَانَ","and became"],["مِنَ","of"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"4045":["(Allah berfirman, \"Hai iblis! Apakah yang menghalangi kamu sujud kepada yang telah Kuciptakan dengan kedua tangan kekuasaan-Ku?) maksudnya, yang telah Aku atur penciptaannya secara langsung; ungkapan ini dimaksud memuliakan kedudukan Nabi Adam, karena sesungguhnya setiap makhluk diciptakan oleh Allah secara langsung. (Apakah kamu menyombongkan diri) sekarang sehingga kamu tidak mau bersujud kepadanya; Istifham atau kata tanya di sini menunjukkan makna cemoohan (ataukah kamu merasa termasuk orang-orang yang lebih tinggi?\") merasa tinggi diri sehingga kamu bersikap takabur tidak mau bersujud.",[["قَالَ","He said"],["يَـٰٓإِبْلِيسُ","O Iblis"],["مَا","What"],["مَنَعَكَ","prevented you"],["أَن","that"],["تَسْجُدَ","you (should) prostrate"],["لِمَا","to (one) whom"],["خَلَقْتُ","I created"],["بِيَدَىَّ ۖ","with My Hands"],["أَسْتَكْبَرْتَ","Are you arrogant"],["أَمْ","or"],["كُنتَ","are you"],["مِنَ","of"],["ٱلْعَالِينَ","the exalted ones"]]],"4046":["(Iblis berkata, \"Aku lebih baik daripadanya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah.\")",[["قَالَ","He said"],["أَنَا۠","I am"],["خَيْرٌۭ","better"],["مِّنْهُ ۖ","than him"],["خَلَقْتَنِى","You created me"],["مِن","from"],["نَّارٍۢ","fire"],["وَخَلَقْتَهُۥ","and You created him"],["مِن","from"],["طِينٍۢ","clay"]]],"4047":["(Allah berfirman, \"Maka keluarlah kamu dari surga) menurut pendapat yang lain dari langit (sesungguhnya kamu adalah orang yang diusir) yang terusir.",[["قَالَ","He said"],["فَٱخْرُجْ","Then get out"],["مِنْهَا","of it"],["فَإِنَّكَ","for indeed, you"],["رَجِيمٌۭ","(are) accursed"]]],"4048":["(Sesungguhnya kutukan-Ku tetap atasmu sampai hari pembalasan\") yakni hari Allah melakukan pembalasan.",[["وَإِنَّ","And indeed"],["عَلَيْكَ","upon you"],["لَعْنَتِىٓ","(is) My curse"],["إِلَىٰ","until"],["يَوْمِ","(the) Day"],["ٱلدِّينِ","(of) Judgment"]]],"4049":["(Iblis berkata, \"Ya Rabbku! Berilah aku tenggang waktu sampai hari mereka dibangkitkan\") sampai manusia dibangkitkan.",[["قَالَ","He said"],["رَبِّ","My Lord"],["فَأَنظِرْنِىٓ","Then give me respite"],["إِلَىٰ","until"],["يَوْمِ","(the) Day"],["يُبْعَثُونَ","they are resurrected"]]],"4050":["(Allah berfirman, \"Sesungguhnya kamu termasuk orang-orang yang diberi tangguh.)",[["قَالَ","He said"],["فَإِنَّكَ","Then indeed, you"],["مِنَ","(are) of"],["ٱلْمُنظَرِينَ","those given respite"]]],"4051":["(Sampai kepada hari yang telah ditentukan waktunya\") yakni waktu tiupan sangkakala yang pertama atau hari kiamat.",[["إِلَىٰ","Until"],["يَوْمِ","(the) Day"],["ٱلْوَقْتِ","(of) the time"],["ٱلْمَعْلُومِ","well-known"]]],"4052":["(Iblis menjawab, \"Demi kekuasaan Engkau, aku akan menyesatkan mereka semuanya).",[["قَالَ","He said"],["فَبِعِزَّتِكَ","Then by Your might"],["لَأُغْوِيَنَّهُمْ","I will surely mislead them"],["أَجْمَعِينَ","all"]]],"4053":["(Kecuali hamba-hamba-Mu yang mukhlis di antara mereka\") yakni orang-orang yang beriman.",[["إِلَّا","Except"],["عِبَادَكَ","Your slaves"],["مِنْهُمُ","among them"],["ٱلْمُخْلَصِينَ","the chosen ones"]]],"4054":["(Allah berfirman, \"Maka yang benar adalah sumpah-Ku dan hanya kebenaran itulah yang Kukatakan\") dapat dibaca Falhaqqa Wal Haqqa atau Falhaqqu Wal Haqqa; kalau dibaca Nashab berarti dinashabkan oleh Fi'il yang sesudahnya. Bila lafal pertama dinashabkan, menurut suatu pendapat dikatakan, bahwa dinashabkan oleh Fi'll yang telah disebutkan. Menurut pendapat yang lainnya lagi dinashabkan karena menjadi Mashdar, bentuk asalnya adalah Uhiqqal Haqqa. Menurut pendapat yang lainnya lagi karena huruf Qasamnya dicabut. Dibaca Rafa' atas dasar karena menjadi Mubtada yang dibuang Khabarnya, bentuk asalnya adalah Falhaqqu Minnii. Menurut pendapat yang lainnya lagi bentuk asalnya adalah, Falhaqqu Qasami, dan jawab Qasamnya ialah kalimat berikutnya, yaitu:",[["قَالَ","He said"],["فَٱلْحَقُّ","Then (it is) the truth"],["وَٱلْحَقَّ","and the truth"],["أَقُولُ","I say"]]],"4055":["(Sesungguhnya Aku pasti akan memenuhi neraka Jahanam dengan jenis kamu) berikut keturunanmu (dan dengan orang-orang yang mengikuti kamu di antara mereka) yakni umat manusia (semuanya.)",[["لَأَمْلَأَنَّ","Surely I will fill"],["جَهَنَّمَ","Hell"],["مِنكَ","with you"],["وَمِمَّن","and those who"],["تَبِعَكَ","follow you"],["مِنْهُمْ","among them"],["أَجْمَعِينَ","all"]]],"4056":["(Katakanlah! \"Aku tidak meminta kepada kalian atas hal ini) atas penyampaian risalah ini (upah sedikit pun) persenan sedikit pun dari kalian (dan bukanlah aku termasuk orang-orang yang mengada-adakan) maksudnya, membuat-buat Alquran dari diriku sendiri.",[["قُلْ","Say"],["مَآ","Not"],["أَسْـَٔلُكُمْ","I ask of you"],["عَلَيْهِ","for it"],["مِنْ","any"],["أَجْرٍۢ","payment"],["وَمَآ","and not"],["أَنَا۠","I am"],["مِنَ","of"],["ٱلْمُتَكَلِّفِينَ","the ones who pretend"]]],"4057":["(Tiada lain ini) Alquran ini (hanyalah peringatan) yakni nasihat dan peringatan (bagi semesta alam) maksudnya bagi jenis manusia, jin dan makhluk-makhluk yang berakal selain malaikat.",[["إِنْ","Not"],["هُوَ","it (is)"],["إِلَّا","except"],["ذِكْرٌۭ","a Reminder"],["لِّلْعَـٰلَمِينَ","to the worlds"]]],"4058":["(Dan sesungguhnya kalian akan mengetahui) hai orang-orang kafir Mekah (berita Alquran) yaitu berita kebenarannya (setelah beberapa waktu lagi\") yakni pada hari kiamat nanti. Lafal 'Alima bermakna 'Arafa yakni mengetahui. Huruf Lam sebelumnya adalah Lam Qasam bagi lafal yang diperkirakan, bentuk asalnya adalah, Wallaahi Lata'lamunna.",[["وَلَتَعْلَمُنَّ","And surely you will know"],["نَبَأَهُۥ","its information"],["بَعْدَ","after"],["حِينٍۭ","a time"]]],"4059":["(Turunnya Kitab ini) yakni Alquran; berkedudukan sebagai Mubtaba (dari Allah) berkedudukan sebagai Khabar dari Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) dalam tindakan-Nya.",[["تَنزِيلُ","(The) revelation"],["ٱلْكِتَـٰبِ","(of) the Book"],["مِنَ","(is) from"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْحَكِيمِ","the All-Wise"]]],"4060":["(Sesungguhnya Kami menurunkan kepadamu) hai Muhammad (Kitab Alquran dengan membawa kebenaran) lafal Bilhaqqi berta'alluq kepada lafal Anzalnaa. (Maka sembahlah Allah dengan memurnikan ketaatan kepada-Nya) yakni dari kemusyrikan, maksudnya mentauhidkan-Nya.",[["إِنَّآ","Indeed, We"],["أَنزَلْنَآ","[We] have revealed"],["إِلَيْكَ","to you"],["ٱلْكِتَـٰبَ","the Book"],["بِٱلْحَقِّ","in truth"],["فَٱعْبُدِ","so worship"],["ٱللَّهَ","Allah"],["مُخْلِصًۭا","(being) sincere"],["لَّهُ","to Him"],["ٱلدِّينَ","(in) the religion"]]],"4061":["(Ingatlah, hanya kepada Allahlah ketaatan yang murni itu) tiada seorang pun yang berhak menerimanya selain-Nya. (Dan orang-orang yang mengambil selain-Nya) yang mengambil berhala-berhala (sebagai pelindung) mereka adalah orang-orang kafir Mekah yang mengatakan, (\"Kami tidak menyembah mereka melainkan supaya mereka mendekatkan kami kepada Allah dengan sedekat-dekatnya.\") yakni untuk mendekatkan diri kami kepada-Nya. Lafal Zulfaa adalah Mashdar yang maknanya sama dengan lafal Taqriiban/mendekatkan diri. (Sesungguhnya Allah akan memutuskan di antara mereka) dan kaum Muslimin (tentang apa yang mereka berselisih padanya) tentang masalah agama, maka kelak orang-orang yang beriman akan masuk surga dan orang-orang yang kafir akan masuk neraka. (Sesungguhnya Allah tidak menunjuki orang yang pendusta) yaitu orang yang mengatakan terhadap Allah, bahwa Dia mempunyai anak (lagi sangat ingkar) karena menyembah kepada selain-Nya.",[["أَلَا","Unquestionably"],["لِلَّهِ","for Allah"],["ٱلدِّينُ","(is) the religion"],["ٱلْخَالِصُ ۚ","the pure"],["وَٱلَّذِينَ","And those who"],["ٱتَّخَذُوا۟","take"],["مِن","besides Him"],["دُونِهِۦٓ","besides Him"],["أَوْلِيَآءَ","protectors"],["مَا","Not"],["نَعْبُدُهُمْ","we worship them"],["إِلَّا","except"],["لِيُقَرِّبُونَآ","that they may bring us near"],["إِلَى","to"],["ٱللَّهِ","Allah"],["زُلْفَىٰٓ","(in) nearness"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَحْكُمُ","will judge"],["بَيْنَهُمْ","between them"],["فِى","in"],["مَا","what"],["هُمْ","they"],["فِيهِ","[in it]"],["يَخْتَلِفُونَ ۗ","differ"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["مَنْ","(one) who"],["هُوَ","[he]"],["كَـٰذِبٌۭ","(is) a liar"],["كَفَّارٌۭ","and a disbeliever"]]],"4062":["(Kalau sekiranya Allah hendak mengambil anak) seperti apa yang mereka katakan, yaitu sebagaimana yang disitir oleh firman-Nya, \"Tuhan Yang Maha Pemurah telah mengambil (mempunyai) anak...\" (Q.S. Al-Anbiya, 26) (tentu Dia akan memilih apa yang dikehendaki-Nya di antara ciptaan-ciptaan yang diciptakan-Nya) untuk dijadikan-Nya anak; bukan seperti apa yang telah mereka katakan, bahwa para malaikat itu adalah anak-anak perempuan Allah, Uzair itu putra Allah dan juga Al-Masih adalah putra Allah (Maha Suci Allah) kalimat ini memahasucikan-Nya dari mengambil anak (Dialah Allah Yang Maha Esa lagi Maha Mengalahkan) semua makhluk-Nya.",[["لَّوْ","If"],["أَرَادَ","Allah (had) intended"],["ٱللَّهُ","Allah (had) intended"],["أَن","to"],["يَتَّخِذَ","take"],["وَلَدًۭا","a son"],["لَّٱصْطَفَىٰ","surely, He (could) have chosen"],["مِمَّا","from what"],["يَخْلُقُ","He creates"],["مَا","whatever"],["يَشَآءُ ۚ","He willed"],["سُبْحَـٰنَهُۥ ۖ","Glory be to Him"],["هُوَ","He"],["ٱللَّهُ","(is) Allah"],["ٱلْوَٰحِدُ","the One"],["ٱلْقَهَّارُ","the Irresistible"]]],"4063":["(Dia menciptakan langit dan bumi dengan -tujuan- yang benar) lafal Bilhaqqi berta'alluq kepada lafal Khalaqa (Dia menutupkan) yakni memasukkan (malam atas siang) sehingga waktu malam bertambah. (dan menutupkan siang) memasukkannya (atas malam) sehingga waktu siang bertambah (dan Dia menundukkan matahari dan bulan, masing-masing berjalan) pada garis edarnya (hingga waktu yang ditentukan) yakni hari kiamat. (Ingatlah Dialah Yang Maha Perkasa) Yang Maha Menang atas semua perkara-Nya dan Yang Maha Membalas terhadap musuh-musuh-Nya (lagi Maha Pengampun) kepada kekasih-kekasih-Nya.",[["خَلَقَ","He created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["بِٱلْحَقِّ ۖ","in [the] truth"],["يُكَوِّرُ","He wraps"],["ٱلَّيْلَ","the night"],["عَلَى","over"],["ٱلنَّهَارِ","the day"],["وَيُكَوِّرُ","and wraps"],["ٱلنَّهَارَ","the day"],["عَلَى","over"],["ٱلَّيْلِ ۖ","the night"],["وَسَخَّرَ","And He subjected"],["ٱلشَّمْسَ","the sun"],["وَٱلْقَمَرَ ۖ","and the moon"],["كُلٌّۭ","each"],["يَجْرِى","running"],["لِأَجَلٍۢ","for a term"],["مُّسَمًّى ۗ","specified"],["أَلَا","Unquestionably"],["هُوَ","He"],["ٱلْعَزِيزُ","(is) the All-Mighty"],["ٱلْغَفَّـٰرُ","the Oft-Forgiving"]]],"4064":["(Dia menciptakan kalian dari seorang diri) yaitu dari Nabi Adam (kemudian Dia jadikan daripadanya istrinya) yaitu Siti Hawa (dan Dia menurunkan untuk kalian binatang ternak) yakni unta, sapi, kambing, domba dan biri-biri (sebanyak delapan ekor yang berpasang-pasangan) yakni dari setiap jenis sepasang, yaitu jantan dan betina sebagaimana yang telah dijelaskan dalam surah Al-An'am (Dia menjadikan kalian dalam perut ibu kalian kejadian demi kejadian) yaitu mulai dari air mani, kemudian menjadi segumpal darah, lalu menjadi segumpal daging (dalam tiga kegelapan) yaitu gelapnya perut, gelapnya rahim dan gelapnya selaput pelindung bayi. (Yang berbuat demikian itu adalah Allah, Rabb kalian, Rabb Yang mempunyai kerajaan; tidak ada Tuhan selain Dia, maka bagaimanakah kalian dapat dipalingkan?) dari menyembah kepada-Nya, kemudian kalian menyembah yang lain-Nya.",[["خَلَقَكُم","He created you"],["مِّن","from"],["نَّفْسٍۢ","a soul"],["وَٰحِدَةٍۢ","single"],["ثُمَّ","Then"],["جَعَلَ","He made"],["مِنْهَا","from it"],["زَوْجَهَا","its mate"],["وَأَنزَلَ","And He sent down"],["لَكُم","for you"],["مِّنَ","of"],["ٱلْأَنْعَـٰمِ","the cattle"],["ثَمَـٰنِيَةَ","eight"],["أَزْوَٰجٍۢ ۚ","kinds"],["يَخْلُقُكُمْ","He creates you"],["فِى","in"],["بُطُونِ","(the) wombs"],["أُمَّهَـٰتِكُمْ","(of) your mothers"],["خَلْقًۭا","creation"],["مِّنۢ","after"],["بَعْدِ","after"],["خَلْقٍۢ","creation"],["فِى","in"],["ظُلُمَـٰتٍۢ","darkness[es]"],["ثَلَـٰثٍۢ ۚ","three"],["ذَٰلِكُمُ","That"],["ٱللَّهُ","(is) Allah"],["رَبُّكُمْ","your Lord"],["لَهُ","for Him"],["ٱلْمُلْكُ ۖ","(is) the dominion"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ ۖ","He"],["فَأَنَّىٰ","Then how"],["تُصْرَفُونَ","are you turning away"]]],"4065":["(Jika kalian kafir maka sesungguhnya Allah tidak memerlukan kalian dan Dia tidak meridai kekafiran bagi hamba-hamba-Nya) sekalipun ada di antara hamba-hamba-Nya yang menghendakinya (dan jika kalian bersyukur) kepada Allah, karenanya lalu kalian beriman (niscaya Dia meridai tasyakur) dapat dibaca Yardhah atau Yardhahu, artinya Dia pasti meridai tasyakur (kalian itu; dan tidaklah akan menanggung dosa) yakni seseorang (yang telah berbuat dosa akan dosa) orang (yang lain) maksudnya, seseorang yang berdosa tidak akan memikul dosa orang lain. (Kemudian kepada Rabb kalianlah kembali kalian lalu Dia memberitakan kepada kalian apa yang telah kalian kerjakan. Sesungguhnya Dia Maha Mengetahui apa yang tersimpan dalam dada) dalam kalbu kalian.",[["إِن","If"],["تَكْفُرُوا۟","you disbelieve"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["غَنِىٌّ","(is) free from need"],["عَنكُمْ ۖ","of you"],["وَلَا","And not"],["يَرْضَىٰ","He likes"],["لِعِبَادِهِ","in His slaves"],["ٱلْكُفْرَ ۖ","ungratefulness"],["وَإِن","And if"],["تَشْكُرُوا۟","you are grateful"],["يَرْضَهُ","He likes it"],["لَكُمْ ۗ","in you"],["وَلَا","And not"],["تَزِرُ","will bear"],["وَازِرَةٌۭ","bearer of burdens"],["وِزْرَ","(the) burden"],["أُخْرَىٰ ۗ","(of) another"],["ثُمَّ","Then"],["إِلَىٰ","to"],["رَبِّكُم","your Lord"],["مَّرْجِعُكُمْ","(is) your return"],["فَيُنَبِّئُكُم","then He will inform you"],["بِمَا","about what"],["كُنتُمْ","you used to"],["تَعْمَلُونَ ۚ","do"],["إِنَّهُۥ","Indeed, He"],["عَلِيمٌۢ","(is) the All-Knower"],["بِذَاتِ","of what (is) in the breasts"],["ٱلصُّدُورِ","of what (is) in the breasts"]]],"4066":["(Dan apabila manusia itu ditimpa) yakni orang yang kafir (kemudaratan, dia memohon -pertolongan- kepada Rabbnya) yakni merintih kepada-Nya meminta pertolongan (dengan kembali) maksudnya, bertobat (kepada-Nya; kemudian apabila Rabb memberikan nikmat kepadanya) Dia memberinya nikmat (dari-Nya lupalah dia) artinya, dia meninggalkan (akan apa yang pernah ia serukan) yaitu lupa akan rintihannya (kepada-Nya sebelum itu) lupa kepada Allah. Lafal Maa di sini bermakna Man (dan dia mengada-adakan sekutu-sekutu bagi Allah) tandingan-tandingan bagi-Nya (untuk menyesatkan) manusia; lafal liyudhilla dapat dibaca liyadhilla (dari jalan-Nya) dari agama Islam (Katakanlah, \"Bersenang-senanglah dengan kekafiranmu itu sementara waktu) selama sisa hidupmu (sesungguhnya kamu termasuk penghuni neraka.\")",[["۞ وَإِذَا","And when"],["مَسَّ","touches"],["ٱلْإِنسَـٰنَ","[the] man"],["ضُرٌّۭ","adversity"],["دَعَا","he calls"],["رَبَّهُۥ","his Lord"],["مُنِيبًا","turning"],["إِلَيْهِ","to Him"],["ثُمَّ","then"],["إِذَا","when"],["خَوَّلَهُۥ","He bestows on him"],["نِعْمَةًۭ","a favor"],["مِّنْهُ","from Himself"],["نَسِىَ","he forgets"],["مَا","(for) what"],["كَانَ","he used to call"],["يَدْعُوٓا۟","he used to call"],["إِلَيْهِ","[to] Him"],["مِن","before"],["قَبْلُ","before"],["وَجَعَلَ","and he sets up"],["لِلَّهِ","to Allah"],["أَندَادًۭا","rivals"],["لِّيُضِلَّ","to mislead"],["عَن","from"],["سَبِيلِهِۦ ۚ","His Path"],["قُلْ","Say"],["تَمَتَّعْ","Enjoy"],["بِكُفْرِكَ","in your disbelief"],["قَلِيلًا ۖ","(for) a little"],["إِنَّكَ","Indeed, you"],["مِنْ","(are) of"],["أَصْحَـٰبِ","(the) companions"],["ٱلنَّارِ","(of) the Fire"]]],"4067":["(Apakah orang) dibaca Amman, dan dapat dibaca Aman (yang beribadah) yang berdiri melakukan amal ketaatan, yakni salat (di waktu-waktu malam) di saat-saat malam hari (dengan sujud dan berdiri) dalam salat (sedangkan ia takut kepada hari akhirat) yakni takut akan azab pada hari itu (dan mengharapkan rahmat) yakni surga (Rabbnya) apakah dia sama dengan orang yang durhaka karena melakukan kekafiran atau perbuatan-perbuatan dosa lainnya. Menurut qiraat yang lain lafal Amman dibaca Am Man secara terpisah, dengan demikian berarti lafal Am bermakna Bal atau Hamzah Istifham (Katakanlah, \"Adakah sama orang-orang yong mengetahui dengan orang-orang yong tidak mengetahui?\") tentu saja tidak, perihalnya sama dengan perbedaan antara orang yang alim dan orang yang jahil. (Sesungguhnya orang yang dapat menerima pelajaran) artinya, man menerima nasihat (hanyalah orang-orang yang berakal) yakni orang-orang yang mempunyai pikiran.",[["أَمَّنْ","Is (one) who"],["هُوَ","[he]"],["قَـٰنِتٌ","(is) devoutly obedient "],["ءَانَآءَ","(during) hours"],["ٱلَّيْلِ","(of) the night"],["سَاجِدًۭا","prostrating"],["وَقَآئِمًۭا","and standing"],["يَحْذَرُ","fearing"],["ٱلْـَٔاخِرَةَ","the Hereafter"],["وَيَرْجُوا۟","and hoping"],["رَحْمَةَ","(for the) Mercy"],["رَبِّهِۦ ۗ","(of) his Lord"],["قُلْ","Say"],["هَلْ","Are"],["يَسْتَوِى","equal"],["ٱلَّذِينَ","those who"],["يَعْلَمُونَ","know"],["وَٱلَّذِينَ","and those who"],["لَا","(do) not"],["يَعْلَمُونَ ۗ","know"],["إِنَّمَا","Only"],["يَتَذَكَّرُ","will take heed"],["أُو۟لُوا۟","those of understanding"],["ٱلْأَلْبَـٰبِ","those of understanding"]]],"4068":["(Katakanlah, \"Hai hamba-hamba-Ku yang beriman, bertakwalah kalian kepada Rabb kalian\") takutlah kalian akan azab-Nya, yaitu dengan jalan menaati-Nya. (Orang-orang yang berbuat baik di dunia ini memperoleh) melalui jalan ketaatan kepada Rabbnya (kebaikan) yakni surga. (Dan bumi Allah itu adalah luas) maka hijrahlah ke negeri yang lain meninggalkan orang-orang kafir demi menghindarkan diri dari menyaksikan hal-hal yang mungkar. (Sesungguhnya orang-orang yang bersabarlah yang dicukupkan) yang sabar di dalam menjalankan ketaatan dan sabar di dalam menahan ujian yang menimpa diri mereka (pahala mereka tanpa batas) yakni tanpa memakai neraca dan timbangan lagi.",[["قُلْ","Say"],["يَـٰعِبَادِ","O My slaves"],["ٱلَّذِينَ","[those] who"],["ءَامَنُوا۟","believe"],["ٱتَّقُوا۟","Fear"],["رَبَّكُمْ ۚ","your Lord"],["لِلَّذِينَ","For those who"],["أَحْسَنُوا۟","do good"],["فِى","in"],["هَـٰذِهِ","this"],["ٱلدُّنْيَا","world"],["حَسَنَةٌۭ ۗ","(is) good"],["وَأَرْضُ","and the earth"],["ٱللَّهِ","(of) Allah"],["وَٰسِعَةٌ ۗ","(is) spacious"],["إِنَّمَا","Only"],["يُوَفَّى","will be paid back in full"],["ٱلصَّـٰبِرُونَ","the patient ones"],["أَجْرَهُم","their reward"],["بِغَيْرِ","without"],["حِسَابٍۢ","account"]]],"4069":["(Katakanlah sesungguhnya aku diperintahkan supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya) dari perbuatan syirik.",[["قُلْ","Say"],["إِنِّىٓ","Indeed, I"],["أُمِرْتُ","[I] am commanded"],["أَنْ","that"],["أَعْبُدَ","I worship"],["ٱللَّهَ","Allah"],["مُخْلِصًۭا","(being) sincere"],["لَّهُ","to Him"],["ٱلدِّينَ","(in) the religion"]]],"4070":["(Dan aku diperintahkan supaya menjadi orang yang pertama-tama berserah diri) dari kalangan umat ini.",[["وَأُمِرْتُ","And I am commanded"],["لِأَنْ","that"],["أَكُونَ","I be"],["أَوَّلَ","(the) first"],["ٱلْمُسْلِمِينَ","(of) those who submit"]]],"4071":["(Katakanlah, \"Sesungguhnya aku takut akan siksaan hari yang besar jika aku durhaka kepada Rabbku\").",[["قُلْ","Say"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["إِنْ","if"],["عَصَيْتُ","I disobey"],["رَبِّى","my Lord"],["عَذَابَ","(the) punishment"],["يَوْمٍ","(of) a Day"],["عَظِيمٍۢ","great"]]],"4072":["(Katakanlah, \"Hanya Allah saja yang aku sembah dengan memurnikan ketaatan kepada-Nya\") dari perbuatan syirik atau menyekutukan Allah.",[["قُلِ","Say"],["ٱللَّهَ","I worship Allah"],["أَعْبُدُ","I worship Allah"],["مُخْلِصًۭا","(being) sincere"],["لَّهُۥ","to Him"],["دِينِى","(in) my religion"]]],"4073":["(Maka sembahlah oleh kalian apa yang kalian kehendaki selain Dia) selain-Nya. Di dalam ungkapan ayat ini terkandung makna ancaman bagi orang-orang musyrik dan sekaligus sebagai pemberitahuan, bahwa mereka tidak menyembah Allah swt. (Katakanlah, \"Sesungguhnya orang-orang yang rugi ialah orang-orang yang merugikan diri mereka sendiri dan keluarganya pada hari kiamat\") karena mereka akan menjadi penghuni neraka yang abadi, dan karena mereka tidak memperoleh bidadari-bidadari yang disediakan buat mereka, jika mereka beriman.- (Ingatlah yang demikian itu adalah kerugian yang nyata) jelas sekali ruginya.",[["فَٱعْبُدُوا۟","So worship"],["مَا","what"],["شِئْتُم","you will"],["مِّن","besides Him"],["دُونِهِۦ ۗ","besides Him"],["قُلْ","Say"],["إِنَّ","Indeed"],["ٱلْخَـٰسِرِينَ","the losers"],["ٱلَّذِينَ","(are) those who"],["خَسِرُوٓا۟","(will) lose"],["أَنفُسَهُمْ","themselves"],["وَأَهْلِيهِمْ","and their families"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۗ","(of) the Resurrection"],["أَلَا","Unquestionably"],["ذَٰلِكَ","that "],["هُوَ","it"],["ٱلْخُسْرَانُ","(is) the loss"],["ٱلْمُبِينُ","the clear"]]],"4074":["(Bagi mereka gumpalan-gumpalan di atas mereka) lapisan-lapisan (dari api dan di bawah mereka pun gumpalan-gumpalan) lapisan-lapisan dari api. (Demikianlah Allah mempertakuti hamba-hamba-Nya dengan azab itu) yakni hamba-hamba-Nya yang beriman, supaya mereka bertakwa kepada-Nya; pengertian ini disimpulkan dari firman selanjutnya, yaitu, (Maka bertakwalah kepada-Ku hai hamba-hamba-Ku).",[["لَهُم","For them"],["مِّن","from"],["فَوْقِهِمْ","above them"],["ظُلَلٌۭ","coverings"],["مِّنَ","of"],["ٱلنَّارِ","the Fire"],["وَمِن","and from"],["تَحْتِهِمْ","below them"],["ظُلَلٌۭ ۚ","coverings"],["ذَٰلِكَ","(With) that"],["يُخَوِّفُ","threatens"],["ٱللَّهُ","Allah"],["بِهِۦ","[with it]"],["عِبَادَهُۥ ۚ","His slaves"],["يَـٰعِبَادِ","O My slaves"],["فَٱتَّقُونِ","So fear Me"]]],"4075":["(Dan orang-orang yang menjauhi thaghut) yakni berhala-berhala (yaitu tidak menyembahnya dan kembali) menghadap (kepada Allah, bagi mereka berita gembira) yaitu mendapatkan surga (sebab itu sampaikanlah berita itu kepada hamba-hamba-Ku).",[["وَٱلَّذِينَ","And those who"],["ٱجْتَنَبُوا۟","avoid"],["ٱلطَّـٰغُوتَ","the false gods"],["أَن","lest"],["يَعْبُدُوهَا","they worship them"],["وَأَنَابُوٓا۟","and turn"],["إِلَى","to"],["ٱللَّهِ","Allah"],["لَهُمُ","for them"],["ٱلْبُشْرَىٰ ۚ","(are) glad tidings"],["فَبَشِّرْ","So give glad tidings"],["عِبَادِ","(to) My slaves"]]],"4076":["(Yaitu, orang-orang yang mendengarkan perkataan lalu mengikuti apa yang paling baik di antaranya) mengikuti sesuatu yang mengandung kemaslahatan bagi mereka. (Mereka itulah orang-orang yang telah diberi Allah petunjuk dan mereka itulah orang-orang yang mempunyai akal) yang mempunyai pikiran.",[["ٱلَّذِينَ","Those who"],["يَسْتَمِعُونَ","they listen (to)"],["ٱلْقَوْلَ","the Word"],["فَيَتَّبِعُونَ","then follow"],["أَحْسَنَهُۥٓ ۚ","the best thereof"],["أُو۟لَـٰٓئِكَ","those"],["ٱلَّذِينَ","(are) they whom"],["هَدَىٰهُمُ","Allah has guided them"],["ٱللَّهُ ۖ","Allah has guided them"],["وَأُو۟لَـٰٓئِكَ","and those"],["هُمْ","are [they]"],["أُو۟لُوا۟","the men of understanding"],["ٱلْأَلْبَـٰبِ","the men of understanding"]]],"4077":["(Apakah orang yang telah pasti ketentuan azab atasnya?) termasuk orang-orang yang digolongkan oleh firman-Nya, \"Sesungguhnya akan Aku penuhi neraka jahanam...\" (Q.S. As-Sajdah, 13). (Apakah kamu akan menyelamatkan) maksudnya, mengeluarkan (orang yang berada dalam neraka) kalimat ayat ini menjadi Jawab Syarath, kemudian di dalamnya terdapat Isim Zhahir yaitu lafal Man yang menduduki tempat Isim Mudhmar; dan Hamzah Istifham di sini menunjukkan makna ingkar, yakni, kamu tidak akan mampu memberikan hidayah kepadanya sehingga ia dapat kamu selamatkan dari neraka.",[["أَفَمَنْ","Then, is (one) who"],["حَقَّ","became due"],["عَلَيْهِ","on him"],["كَلِمَةُ","the word"],["ٱلْعَذَابِ","(of) the punishment"],["أَفَأَنتَ","Then can you"],["تُنقِذُ","save"],["مَن","(one) who"],["فِى","(is) in"],["ٱلنَّارِ","the Fire"]]],"4078":["(Tetapi orang-orang yang bertakwa kepada Rabbnya) yaitu bertakwa melalui jalan taat kepada-Nya (mereka mendapat tempat-tempat yang tinggi, di atasnya dibangun pula tempat-tempat yang tinggi, di bawahnya mengalir sungai-sungai) artinya sungai-sungai yang mengalir, baik di bawah tempat-tempat yang teratas maupun di tempat-tempat yang terbawah (sebagai janji Allah) lafal Wa'dallaahi dinashabkan oleh Fi'il yang diperkirakan keberadaannya pada sebelumnya (Allah tidak akan memungkiri janji-Nya) atau mengingkarinya.",[["لَـٰكِنِ","But"],["ٱلَّذِينَ","those who"],["ٱتَّقَوْا۟","fear"],["رَبَّهُمْ","their Lord"],["لَهُمْ","for them"],["غُرَفٌۭ","(are) lofty mansions"],["مِّن","above them"],["فَوْقِهَا","above them"],["غُرَفٌۭ","lofty mansions"],["مَّبْنِيَّةٌۭ","built high"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","beneath it"],["ٱلْأَنْهَـٰرُ ۖ","the rivers"],["وَعْدَ","(The) Promise"],["ٱللَّهِ ۖ","(of) Allah"],["لَا","Not"],["يُخْلِفُ","Allah fails"],["ٱللَّهُ","Allah fails"],["ٱلْمِيعَادَ","(in His) promise"]]],"4079":["(Apakah kamu tidak memperhatikan) maksudnya tidak mengetahui (bahwa sesungguhnya Allah menurunkan air dari langit, maka diatur-Nya menjadi sumber-sumber) yakni, dia memasukkan air itu ke tempat-tempat yang dapat menjadi sumber air (di bumi kemudian ditumbuhkan-Nya dengan air itu tanam-tanaman yang bermacam-macam warnanya, lalu ia menjadi kering) menjadi layu dan kering (lalu kamu melihatnya) sesudah hijau menjadi (kekuning-kuningan kemudian dijadikan-Nya hancur berderai) yakni rontok (Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran) peringatan (bagi orang-orang yang mempunyai akal) bagi orang-orang yang mau mengambil pelajaran darinya untuk menyimpulkan keesaan dan kekuasaan Allah swt.",[["أَلَمْ","Do not"],["تَرَ","you see"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["أَنزَلَ","sends down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ","water"],["فَسَلَكَهُۥ","and He makes it flow"],["يَنَـٰبِيعَ","(as) springs"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["ثُمَّ","then"],["يُخْرِجُ","He produces"],["بِهِۦ","with it"],["زَرْعًۭا","crops"],["مُّخْتَلِفًا","(of) different"],["أَلْوَٰنُهُۥ","colors"],["ثُمَّ","then"],["يَهِيجُ","they wither"],["فَتَرَىٰهُ","and you see it"],["مُصْفَرًّۭا","turn yellow"],["ثُمَّ","then"],["يَجْعَلُهُۥ","He makes them"],["حُطَـٰمًا ۚ","debris"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَذِكْرَىٰ","surely, (is) a reminder"],["لِأُو۟لِى","for those of understanding"],["ٱلْأَلْبَـٰبِ","for those of understanding"]]],"4080":["(Maka apakah orang-orang yang dibukakan Allah hatinya untuk menerima Islam) sehingga ia mendapat petunjuk (lalu ia mendapat cahaya dari Rabbnya) sama dengan orang yang hatinya dikunci mati; pengertian ini tersimpul dari firman selanjutnya (Maka kecelakaan yang besarlah) artinya, azab yang besarlah (bagi mereka yang telah membatu hatinya untuk mengingat Allah) maksudnya, untuk menerima Alquran. (Mereka itu dalam kesesatan yang nyata) nyata sekali sesatnya.",[["أَفَمَن","So is (one for) whom"],["شَرَحَ","Allah has expanded"],["ٱللَّهُ","Allah has expanded"],["صَدْرَهُۥ","his breast"],["لِلْإِسْلَـٰمِ","for Islam"],["فَهُوَ","so he"],["عَلَىٰ","(is) upon"],["نُورٍۢ","a light"],["مِّن","from"],["رَّبِّهِۦ ۚ","his Lord"],["فَوَيْلٌۭ","So woe"],["لِّلْقَـٰسِيَةِ","to (those are) hardened"],["قُلُوبُهُم","their hearts"],["مِّن","from"],["ذِكْرِ","(the) remembrance of Allah"],["ٱللَّهِ ۚ","(the) remembrance of Allah"],["أُو۟لَـٰٓئِكَ","Those"],["فِى","(are) in"],["ضَلَـٰلٍۢ","error"],["مُّبِينٍ","clear"]]],"4081":["(Allah telah menurunkan perkataan yang paling baik yaitu Kitab) Alquran; lafal Kitaaban menjadi Badal lafal Ahsanal Hadiitsi (yang serupa) satu sama lainnya sama dalam hal Nuzhum dan hal-hal lainnya (lagi berulang-ulang) diulang-ulang di dalamnya janji dan ancaman serta hal-hal lainnya (gemetarlah karenanya) yakni gemetar karena takut di kala disebutkan ancaman-Nya (kulit orang-orang yang takut) yang merasa takut (kepada Rabbnya, kemudian menjadi tenang kulit dan kalbu mereka di waktu mengingat Allah) sewaktu ingat akan janji-Nya. (Itulah) kitab Alquran itu (petunjuk Allah, dengan Kitab itu Dia menunjuki siapa yang dikehendaki-Nya. Dan barang siapa yang disesatkan Allah, niscaya tak ada baginya seorang pemberi petunjuk.)",[["ٱللَّهُ","Allah"],["نَزَّلَ","has revealed"],["أَحْسَنَ","(the) best"],["ٱلْحَدِيثِ","(of) [the] statement "],["كِتَـٰبًۭا","a Book"],["مُّتَشَـٰبِهًۭا","(its parts) resembling each other"],["مَّثَانِىَ","oft-repeated"],["تَقْشَعِرُّ","Shiver"],["مِنْهُ","from it"],["جُلُودُ","(the) skins"],["ٱلَّذِينَ","(of) those who"],["يَخْشَوْنَ","fear"],["رَبَّهُمْ","their Lord"],["ثُمَّ","then"],["تَلِينُ","relax"],["جُلُودُهُمْ","their skins"],["وَقُلُوبُهُمْ","and their hearts"],["إِلَىٰ","at"],["ذِكْرِ","(the) remembrance"],["ٱللَّهِ ۚ","(of) Allah"],["ذَٰلِكَ","That"],["هُدَى","(is the) guidance"],["ٱللَّهِ","(of) Allah"],["يَهْدِى","He guides"],["بِهِۦ","with it"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَمَن","And whoever"],["يُضْلِلِ","Allah lets go astray"],["ٱللَّهُ","Allah lets go astray"],["فَمَا","then not"],["لَهُۥ","for him"],["مِنْ","any"],["هَادٍ","guide"]]],"4082":["(Maka apakah orang yang menghindarkan) supaya jangan dilemparkan (dirinya ke dalam azab yang paling buruk di hari kiamat), azab yang paling keras, seumpamanya ia dicampakkan ke dalam neraka dalam keadaan terbelenggu tangannya disatukan dengan kepalanya, sama dengan orang yang beriman kepadanya yang dimasukkan ke dalam surga? (Dan dikatakan kepada orang-orang yang aniaya) yakni orang-orang kafir Mekah (\"Rasakanlah oleh kalian balasan apa yang telah kalian kerjakan\") sebagai pembalasannya.",[["أَفَمَن","Then (is) he who"],["يَتَّقِى","will shield"],["بِوَجْهِهِۦ","with his face"],["سُوٓءَ","(the) worst"],["ٱلْعَذَابِ","punishment"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) the Resurrection"],["وَقِيلَ","And it will be said"],["لِلظَّـٰلِمِينَ","to the wrongdoers"],["ذُوقُوا۟","Taste"],["مَا","what"],["كُنتُمْ","you used to"],["تَكْسِبُونَ","earn"]]],"4083":["(Orang-orang yang sebelum mereka telah mendustakan) rasul-rasulnya yang mengatakan bahwa azab pasti datang (maka datanglah kepada mereka azab dari arah yang tidak mereka sangka) yang tidak mereka duga sedikit pun.",[["كَذَّبَ","Denied"],["ٱلَّذِينَ","those who"],["مِن","(were) before them"],["قَبْلِهِمْ","(were) before them"],["فَأَتَىٰهُمُ","so came upon them"],["ٱلْعَذَابُ","the punishment"],["مِنْ","from"],["حَيْثُ","where"],["لَا","not"],["يَشْعُرُونَ","they perceive"]]],"4084":["(Maka Allah merasakan kepada mereka kehinaan) artinya, mereka dihina dan direndahkan dengan berupa kutukan, pembunuhan dan lain sebagainya (pada kehidupan dunia. Dan sesungguhnya azab pada hari akhirat lebih besar kalau mereka) yakni orang-orang yang mendustakannya (mengetahui) azab akhirat, dan niscaya kalau mereka mengetahuinya maka mereka tidak akan mendustakannya.",[["فَأَذَاقَهُمُ","So Allah made them"],["ٱللَّهُ","So Allah made them"],["ٱلْخِزْىَ","the disgrace"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا ۖ","(of) the world"],["وَلَعَذَابُ","and certainly (the) punishment"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["أَكْبَرُ ۚ","(is) greater"],["لَوْ","if"],["كَانُوا۟","they"],["يَعْلَمُونَ","knew"]]],"4085":["(Sesungguhnya telah Kami buatkan) telah Kami jadikan (bagi manusia dalam Alquran ini setiap macam perumpamaan supaya mereka dapat pelajaran) maksudnya, supaya mereka mau menerima nasihatnya.",[["وَلَقَدْ","And indeed"],["ضَرَبْنَا","We have set forth"],["لِلنَّاسِ","for people"],["فِى","in"],["هَـٰذَا","this"],["ٱلْقُرْءَانِ","Quran"],["مِن","of"],["كُلِّ","every"],["مَثَلٍۢ","example"],["لَّعَلَّهُمْ","so that they may"],["يَتَذَكَّرُونَ","take heed"]]],"4086":["(Ialah Alquran dalam bahasa Arab) ayat ini berkedudukan menjadi Hal Muakkidah atau kata keterangan yang mengukuhkan (yang tidak ada kebengkokan di dalamnya) tidak ada kekeliruan dan pertentangan (supaya mereka bertakwa) maksudnya, menghindarkan diri dari kekafiran.",[["قُرْءَانًا","A Quran"],["عَرَبِيًّا","(in) Arabic"],["غَيْرَ","without"],["ذِى","any"],["عِوَجٍۢ","crookedness"],["لَّعَلَّهُمْ","so that they may"],["يَتَّقُونَ","(become) righteous"]]],"4087":["(Allah telah membuat) bagi orang yang musyrik dan orang yang bertauhid (perumpamaan yaitu seorang laki-laki) lafal Rajulan ini menjadi Badal dari lafal Matsalan (yang menjadi budak milik beberapa orang yang berserikat dalam perselisihan) yaitu mereka terlihat di dalam persengketaan dan akhlak mereka sangat buruk (dan seorang budak laki-laki yang menjadi milik penuh) milik sepenuhnya (dari seorang laki-laki saja; adakah kedua budak itu sama halnya?) lafal Matsalan berkedudukan menjadi Tamyiz maksudnya, tentu saja tidak sama antara seorang budak yang menjadi milik suatu kelompok dengan seorang budak yang menjadi milik penuh seorang saja. Sesungguhnya, budak yang pertama tadi apabila disuruh oleh masing-masing dari pemilik dirinya secara sekaligus; ia bingung, siapakah yang harus ia layani di antara mereka. Ini adalah perumpamaan orang yang musyrik sedangkan budak yang kedua adalah perumpamaan bagi orang yang bertauhid. (Segala puji bagi Allah) semata (tetapi kebanyakan mereka) penduduk Mekah (tidak mengetahui) azab apakah yang akan menimpa mereka akibat kemusyrikannya, oleh karena itu mereka berbuat kemusyrikan.",[["ضَرَبَ","Allah sets forth"],["ٱللَّهُ","Allah sets forth"],["مَثَلًۭا","an example "],["رَّجُلًۭا","a man"],["فِيهِ","about him"],["شُرَكَآءُ","partners"],["مُتَشَـٰكِسُونَ","quarreling"],["وَرَجُلًۭا","and a man"],["سَلَمًۭا","(belonging) exclusively"],["لِّرَجُلٍ","to one man "],["هَلْ","are"],["يَسْتَوِيَانِ","they both equal"],["مَثَلًا ۚ","(in) comparison"],["ٱلْحَمْدُ","All praise"],["لِلَّهِ ۚ","(be) to Allah"],["بَلْ","Nay"],["أَكْثَرُهُمْ","most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"4088":["(Sesungguhnya kamu) khithab ini ditujukan kepada Nabi saw. (akan mati dan mereka akan mati pula) kelak kamu akan mati dan mereka kelak akan mati pula, maka tidak usah ditunggu-tunggu datangnya mati itu. Ayat ini diturunkan sewaktu mereka merasa lambat akan kematian Nabi saw.",[["إِنَّكَ","Indeed, you"],["مَيِّتٌۭ","will die"],["وَإِنَّهُم","and indeed, they"],["مَّيِّتُونَ","(will also) die"]]],"4089":["(Kemudian sesungguhnya kalian) hai manusia tentang kelaliman-kelaliman yang telah terjadi di antara kalian (pada hari kiamat akan berbantah-bantahan di hadapan Rabb kalian.)",[["ثُمَّ","Then"],["إِنَّكُمْ","indeed you"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["عِندَ","before"],["رَبِّكُمْ","your Lord"],["تَخْتَصِمُونَ","will dispute"]]]});